        @{$event_waits || []};
    my @sink_triggers = grep { ($_->{instance} // '') eq ($sink_instance // '') }
        @triggers;
    my @sink_waits = grep { ($_->{instance} // '') eq ($sink_instance // '') }
        @{$event_waits || []};

    return unless @source_triggers == 1
        && @source_waits == 1
        && @sink_triggers == 1
        && @sink_waits == 1;

    return ($source_triggers[0], $source_waits[0], $sink_triggers[0], $sink_waits[0]);
}

