}

sub _validate_transaction_condition_aggregate_storage_paths {
    my ($condition, $aggregate_roots, $context) = @_;

    if (!ref($condition)) {
        my $path = _aggregate_storage_path_token($condition, $aggregate_roots);
        _validate_aggregate_storage_leaf_read_path($path, $aggregate_roots, $context)
            if defined $path;
        return 1;
    }

    return _validate_transaction_condition_aggregate_storage_expr($condition, $aggregate_roots, $context);
}

sub _validate_transaction_condition_aggregate_storage_expr {
    my ($expr, $aggregate_roots, $context) = @_;

    if (!ref($expr)) {
        my $path = _aggregate_storage_path_token($expr, $aggregate_roots);
        _validate_aggregate_storage_leaf_read_path($path, $aggregate_roots, $context)
            if defined $path;
        return 1;
    }

    return _reject_aggregate_storage_paths($expr, $aggregate_roots, "$context expression")
        unless ref($expr) eq 'ARRAY';

    for my $index (0 .. $#$expr) {
        my $item = $expr->[$index];
        if ($index == 0 && defined($item) && !ref($item)) {
            my $path = _aggregate_storage_path_token($item, $aggregate_roots);
            confess "Error: $context expression operator references aggregate storage path '$path'; this ISF slice accepts aggregate storage paths inside transaction condition expressions only as scalar operands\n"
                if defined $path;
            next;
        }
        _validate_transaction_condition_aggregate_storage_expr($item, $aggregate_roots, $context);
    }

    return 1;
}

sub _validate_transaction_set_rhs_aggregate_storage_reads {
    my ($value, $aggregate_roots, $context) = @_;
    if (!ref($value)) {
        my $path = _aggregate_storage_path_token($value, $aggregate_roots);
        _validate_aggregate_storage_leaf_read_path($path, $aggregate_roots, $context)
            if defined $path;
        return 1;
    }

    if (ref($value) eq 'ARRAY') {
        for my $index (0 .. $#$value) {
            my $item = $value->[$index];
            if ($index == 0 && defined($item) && !ref($item)) {
                my $path = _aggregate_storage_path_token($item, $aggregate_roots);
                confess "Error: $context expression operator references aggregate storage path '$path'; this ISF slice accepts aggregate storage paths inside set RHS expressions only as scalar operands\n"
                    if defined $path;
                next;
            }
            _validate_transaction_set_rhs_aggregate_storage_reads($item, $aggregate_roots, $context);
        }
    }

    return 1;
}

sub _validate_aggregate_storage_leaf_write_target {
    my ($target, $aggregate_roots, $context) = @_;
    if (!ref($target)) {
        my $path = _aggregate_storage_path_token($target, $aggregate_roots);
        _validate_aggregate_storage_leaf_write_path($path, $aggregate_roots, $context)
            if defined $path;
        confess "Error: $context must be a scalar HDL identifier or declared aggregate storage path\n"
            if !defined($path)
                && !_is_hdl_identifier($target)
                && !defined(_enum_member_value_token($target, $aggregate_roots));
        return 1;
    }

    return _reject_aggregate_storage_paths($target, $aggregate_roots, $context);
}

sub _validate_aggregate_storage_leaf_read_path {
    return _validate_aggregate_storage_scalar_leaf_path(@_, 'read');
}

sub _validate_aggregate_storage_leaf_write_path {
    return _validate_aggregate_storage_scalar_leaf_path(@_, 'write');
}

sub _validate_aggregate_storage_scalar_leaf_path {
    my ($path, $aggregate_roots, $context, $access) = @_;
    $access //= 'read';
    my $access_noun = $access eq 'write' ? 'writes' : 'reads';
    my ($root, $path_text) = _aggregate_storage_path_parts($path, $aggregate_roots);
    confess "Error: $context references aggregate storage path '$path'; this ISF slice accepts aggregate storage leaf $access_noun only from declared actor-owned storage variables\n"
        unless defined($root) && defined($path_text);

    my $result = FSM::Package::AggregatePathSupport->resolve(
        root_type_spec => $aggregate_roots->{$root},
        path_text => $path_text,
    );
    confess "Error: $context references invalid aggregate storage path '$path': "
        . _aggregate_storage_path_error_summary($result) . "\n"
        unless $result->{ok};

    my $type_spec = $result->{type_spec};
    confess "Error: $context references aggregate storage path '$path' that resolves to aggregate kind '$type_spec->{kind}'; this ISF slice accepts only scalar aggregate leaf $access_noun\n"
        if _is_aggregate_type_spec($type_spec);

    return 1;
}

sub _reject_aggregate_storage_paths {
    my ($value, $aggregate_roots, $context) = @_;
    if (!ref($value)) {
        my $path = _aggregate_storage_path_token($value, $aggregate_roots);
        confess "Error: $context references aggregate storage path '$path'; this ISF slice accepts aggregate storage paths only as direct transaction set RHS scalar leaf reads, direct transaction set target scalar leaf writes, transaction condition scalar values or expression scalar operands, transaction switch selector or branch scalar values, rule assignment target scalar leaf writes, rule assignment RHS scalar values or operands, rule guard scalar values or expression scalar operands, drive target scalar leaf writes, drive body RHS scalar values or operands, inline drive target scalar leaf writes, inline drive assignment RHS scalar values or operands, or drive-call actual scalar values or operands\n"
            if defined $path;
        return 1;
    }

    if (ref($value) eq 'ARRAY') {
        _reject_aggregate_storage_paths($_, $aggregate_roots, $context) for @$value;
    }

    return 1;
}

sub _aggregate_storage_path_token {
    my ($value, $aggregate_roots) = @_;
    return undef unless defined($value) && !ref($value);
    for my $root (sort { length($b) <=> length($a) } keys %{$aggregate_roots || {}}) {
        return $value if $value =~ /\A\Q$root\E(?:\.|\[)/;
    }
    return undef;
}

sub _aggregate_storage_path_parts {
    my ($value, $aggregate_roots) = @_;
    return unless defined($value) && !ref($value);
    for my $root (sort { length($b) <=> length($a) } keys %{$aggregate_roots || {}}) {
        return ($root, $1) if $value =~ /\A\Q$root\E((?:\.|\[).*)\z/;
    }
    return;
}

sub _aggregate_storage_path_error_summary {
    my ($error) = @_;
    my $code = ref($error) eq 'HASH' ? ($error->{code} || 'unknown') : 'unknown';

    return "member access '." . ($error->{member_name} // '?') . "' is only valid on record values; current path type is '"
        . ($error->{current_type_label} || 'unknown') . "'"
        if $code eq 'member_on_non_record';

    return "record member '" . ($error->{member_name} // '?') . "' is not declared; known members: "
        . join(', ', @{ $error->{known_members} || [] })
        if $code eq 'unknown_member';

    return "list ranges are not supported; select one item with '[N]'"
        if $code eq 'list_range_not_supported';

    return "list index '" . ($error->{index} // '?') . "' is outside the declared item range 0.."
        . ($error->{max_index} // -1)
        if $code eq 'list_index_out_of_range';

    return "scalar slice [" . ($error->{high} // '?') . ':' . ($error->{low} // '?')
        . "] exceeds resolved scalar width '" . ($error->{scalar_width} // '?') . "'"
        if $code eq 'scalar_slice_out_of_range';

    return "scalar index '" . ($error->{index} // '?')
        . "' exceeds resolved scalar width '" . ($error->{scalar_width} // '?') . "'"
        if $code eq 'scalar_index_out_of_range';

    return "index access is valid only on list and scalar bit-vector values; current path type is '"
        . ($error->{current_type_label} || 'unknown') . "'"
        if $code eq 'index_on_non_indexable';

    return "could not parse remaining path '" . ($error->{remaining} || '') . "'"
        if $code eq 'parse_error';

    return "resolved aggregate leaf has no positive packed width"
        if $code eq 'missing_leaf_width';

    return "aggregate path resolution failed with code '$code'";
}

sub _validate_actor_constant_names($self, $actor) {
    my $actor_name = $actor->{actor_name} // 'unknown';
    my %params = map { $_->{name} => 1 } @{$actor->{params} || []};
    for my $constant (@{$actor->{constants} || []}) {
        my $name = $constant->{name};
        confess "Error: actor '$actor_name' constant '$name' conflicts with actor parameter '$name'\n"
            if $params{$name};
    }

    return 1;
}

sub _actor_constant_by_name {
    my ($actor, $name) = @_;
    return undef unless ref($actor) eq 'HASH' && defined($name) && !ref($name);

    for my $constant (@{$actor->{constants} || []}) {
        next unless ref($constant) eq 'HASH';
        return $constant if ($constant->{name} // '') eq $name;
    }

    return undef;
}

sub _actor_param_by_name {
    my ($actor, $name) = @_;
    return undef unless ref($actor) eq 'HASH' && defined($name) && !ref($name);

    for my $param (@{$actor->{params} || []}) {
        next unless ref($param) eq 'HASH';
        return $param if ($param->{name} // '') eq $name;
    }

    return undef;
}

sub _transaction_param_by_name {
    my ($tx, $name) = @_;
    return undef unless ref($tx) eq 'HASH' && defined($name) && !ref($name);

    for my $clause (@{$tx->{clauses} || []}) {
        next unless ref($clause) eq 'ARRAY'
            && @$clause >= 2
            && defined($clause->[0])
            && !ref($clause->[0])
            && $clause->[0] eq 'params';
        for my $entry (@{$clause}[1 .. $#$clause]) {
            next unless ref($entry) eq 'ARRAY' && @$entry >= 1;
            my $param_name = $entry->[0];
            next unless defined($param_name) && !ref($param_name);
            return $entry if $param_name eq $name;
        }
    }

    return undef;
}

sub _actor_transaction_param_by_name {
    my ($actor, $name) = @_;
    return undef unless ref($actor) eq 'HASH' && defined($name) && !ref($name);

    for my $tx (@{$actor->{transactions} || []}) {
        next unless ref($tx) eq 'HASH';
        return $tx if _transaction_param_by_name($tx, $name);
    }

    return undef;
}

sub _actor_interface_signal_by_name {
    my ($actor, $name) = @_;
    return undef unless ref($actor) eq 'HASH' && defined($name) && !ref($name);

    for my $direction (qw(inputs outputs)) {
        for my $port (@{($actor->{interface} || {})->{$direction} || []}) {
            next unless ref($port) eq 'HASH';
            return $port if ($port->{name} // '') eq $name;
        }
    }

    return undef;
}

sub _actor_storage_signal_by_name {
    my ($actor, $name) = @_;
    return undef unless ref($actor) eq 'HASH' && defined($name) && !ref($name);

    for my $entry (@{$actor->{storage} || []}) {
        next unless ref($entry) eq 'HASH';
        return $entry if ($entry->{name} // '') eq $name;
        for my $signal (@{$entry->{signals} || []}) {
            next unless ref($signal) eq 'HASH';
            return $signal if ($signal->{name} // '') eq $name;
        }
    }

    return undef;
}

sub _actor_transaction_port_by_name {
    my ($actor, $name) = @_;
    return undef unless ref($actor) eq 'HASH' && defined($name) && !ref($name);

    for my $tx (@{$actor->{transactions} || []}) {
        next unless ref($tx) eq 'HASH';
        for my $direction (qw(inputs outputs)) {
            for my $port (@{($tx->{ports} || {})->{$direction} || []}) {
                next unless ref($port) eq 'HASH';
                if (($port->{name} // '') eq $name) {
                    return {
                        transaction => $tx->{name},
                        port        => $port,
                    };
                }
            }
        }
    }

    return undef;
}

sub _finalize_actor_domain_annotations($self, $actor) {
    my $actor_name = $actor->{actor_name} // 'unknown';
    my $clock_domains = $actor->{clock_domains};
    my $has_clock_domains = ref($clock_domains) eq 'HASH';
    my %declared_domains = $has_clock_domains
        ? map { $_->{name} => 1 } @{$clock_domains->{domains} || []}
        : (default => 1);
    my $default_domain = $has_clock_domains
        ? $clock_domains->{default}
        : 'default';

    for my $direction (qw(inputs outputs)) {
        for my $port (@{$actor->{interface}{$direction} || []}) {
            $self->_finalize_domain_annotation(
                $port,
                $default_domain,
                \%declared_domains,
                "actor '$actor_name' interface port '$port->{name}'",
                $has_clock_domains,
            );
        }
    }

    for my $entry (@{$actor->{storage} || []}) {
        $self->_finalize_domain_annotation(
            $entry,
            $default_domain,
            \%declared_domains,
            "actor '$actor_name' storage '$entry->{name}'",
            $has_clock_domains,
        );
        if (exists $entry->{domain}) {
            for my $signal (@{$entry->{signals} || []}) {
                $signal->{domain} = $entry->{domain};
            }
        }
    }

    for my $tx (@{$actor->{transactions} || []}) {
        $self->_finalize_domain_annotation(
            $tx,
            $default_domain,
            \%declared_domains,
            "actor '$actor_name' transaction '$tx->{name}'",
            $has_clock_domains,
        );
    }

    for my $rule (@{$actor->{rules} || []}) {
        $self->_finalize_domain_annotation(
            $rule,
            $default_domain,
            \%declared_domains,
            "actor '$actor_name' rule '$rule->{name}'",
            $has_clock_domains,
        );
    }

    for my $use (@{$actor->{uses} || []}) {
        $self->_finalize_domain_annotation(
            $use,
            $default_domain,
            \%declared_domains,
            "actor '$actor_name' use '$use->{instance}'",
            $has_clock_domains,
        );
    }

    for my $use (@{$actor->{library_uses} || []}) {
        $self->_finalize_domain_annotation(
            $use,
            $default_domain,
            \%declared_domains,
            "actor '$actor_name' library use '$use->{instance}'",
            $has_clock_domains,
        );
    }

    return 1;
}

sub _finalize_actor_crossings($self, $actor) {
    my $actor_name = $actor->{actor_name} // 'unknown';
    return 1 unless @{$actor->{crossings} || []};

    confess "Error: actor '$actor_name' crossings require '(clock-domains ...)'\n"
        unless ref($actor->{clock_domains}) eq 'HASH';

    my %declared_domains = map {
        $_->{name} => 1
    } @{$actor->{clock_domains}{domains} || []};

    my %declared_transactions = map {
        $_->{name} => 1
    } @{$actor->{transactions} || []};

    for my $crossing (@{$actor->{crossings} || []}) {
        if (($crossing->{kind} // 'event') eq 'activation') {
            my $child = $crossing->{child};
            my $from = $crossing->{from}{domain};
            my $to = $crossing->{to}{domain};
            confess "Error: actor '$actor_name' activation crossing '$child' source domain '$from' is not declared\n"
                unless $declared_domains{$from};
            confess "Error: actor '$actor_name' activation crossing '$child' destination domain '$to' is not declared\n"
                unless $declared_domains{$to};
            confess "Error: actor '$actor_name' activation crossing '$child' source and destination domains must differ\n"
                if $from eq $to;
            confess "Error: actor '$actor_name' activation crossing child '$child' is not a declared transaction\n"
                unless $declared_transactions{$child};
            next;
        }

        my $name = $crossing->{name};
        my $from = $crossing->{from};
        my $to = $crossing->{to};

        confess "Error: actor '$actor_name' crossing event '$name' source domain '$from->{domain}' is not declared\n"
            unless $declared_domains{$from->{domain}};
        confess "Error: actor '$actor_name' crossing event '$name' destination domain '$to->{domain}' is not declared\n"
            unless $declared_domains{$to->{domain}};
        confess "Error: actor '$actor_name' crossing event '$name' source and destination domains must differ\n"
            if $from->{domain} eq $to->{domain};

        $crossing->{ready}{domain} = $from->{domain};
    }

    return 1;
}

sub _finalize_domain_annotation($self, $entry, $default_domain, $declared_domains, $context, $materialize_default) {
    confess "Error: $context uses unknown clock domain '$entry->{domain}'\n"
        if exists($entry->{domain}) && !$declared_domains->{$entry->{domain}};

    if (!exists($entry->{domain}) && $materialize_default) {
        $entry->{domain} = $default_domain;
    }

    return 1;
}

sub _parse_imports($self, $clause, $actor_name) {
    my @library_imports;
    my @package_imports;
    my %seen_namespace;

    confess "Error: actor '$actor_name' imports require '(imports (library name [as alias]) ... (package NAME) ...)'\n"
        unless @$clause >= 2;

    for my $entry (@{$clause}[1 .. $#$clause]) {
        confess "Error: actor '$actor_name' import entries must be list forms\n"
            unless ref($entry) eq 'ARRAY' && @$entry;
        my $kind = $entry->[0];
        confess "Error: actor '$actor_name' import entry kind must be 'library' or 'package'\n"
            unless defined($kind) && !ref($kind) && ($kind eq 'library' || $kind eq 'package');

        if ($kind eq 'package') {
            confess "Error: actor '$actor_name' package imports require '(package NAME)'\n"
                unless @$entry == 2
                    && defined($entry->[1])
                    && !ref($entry->[1])
                    && _is_hdl_identifier($entry->[1]);
            my $package = $entry->[1];
            confess "Error: actor '$actor_name' has duplicate import namespace '$package'\n"
                if $seen_namespace{$package}++;
            push @package_imports, $package;
            next;
        }

        confess "Error: actor '$actor_name' import entries require '(library name [as alias])'\n"
            unless (@$entry == 2 || @$entry == 4)
                && defined($entry->[1])
                && !ref($entry->[1])
                && _is_library_namespace($entry->[1]);

        my $library = $entry->[1];
        my $alias = $library;
        if (@$entry == 4) {
            confess "Error: actor '$actor_name' import for library '$library' requires '(library $library as alias)'\n"
                unless defined($entry->[2])
                    && !ref($entry->[2])
                    && $entry->[2] eq 'as'
                    && defined($entry->[3])
                    && !ref($entry->[3])
                    && _is_hdl_identifier($entry->[3]);
            $alias = $entry->[3];
        }

        confess "Error: actor '$actor_name' has duplicate import namespace '$alias'\n"
            if $seen_namespace{$alias}++;

        push @library_imports, {
            kind    => 'library',
            library => $library,
            alias   => $alias,
        };
    }

    return {
        libraries => \@library_imports,
        packages  => \@package_imports,
    };
}

sub _parse_use($self, $clause, $actor_name) {
    confess "Error: actor '$actor_name' use requires '(use alias.actor as instance [(domain name)] [(params ...)] (bind ...))'\n"
        unless @$clause >= 4
            && defined($clause->[1])
            && !ref($clause->[1])
            && length($clause->[1])
            && defined($clause->[2])
            && !ref($clause->[2])
            && $clause->[2] eq 'as'
            && defined($clause->[3])
            && !ref($clause->[3])
            && _is_hdl_identifier($clause->[3]);

    FSM::Support::HDLInstanceIdentifierPolicy->assert_authored_instance_identifier(
        $clause->[3],
        origin => "Actor '$actor_name' library use instance",
    );

    my %seen_subclause;
    my @params;
    my @bindings;
    my $domain;
    my $saw_bind;

    for my $subclause (@{$clause}[4 .. $#$clause]) {
        confess "Error: actor '$actor_name' use '$clause->[3]' subclauses must be list forms\n"
            unless ref($subclause) eq 'ARRAY' && @$subclause;
        my $head = $subclause->[0];
        confess "Error: actor '$actor_name' use '$clause->[3]' subclause heads must be scalar\n"
            unless defined($head) && !ref($head) && length($head);
        confess "Error: actor '$actor_name' use '$clause->[3]' has duplicate '$head' subclause\n"
            if $seen_subclause{$head}++;

        if ($head eq 'params') {
            @params = @{$self->_parse_use_params($subclause, $actor_name, $clause->[3])};
            next;
        }
        if ($head eq 'domain') {
            $domain = _parse_domain_option(
                $subclause,
                "Error: actor '$actor_name' use '$clause->[3]' domain",
            );
            next;
        }
        if ($head eq 'bind') {
            $saw_bind = 1;
            @bindings = @{$self->_parse_use_bind($subclause, $actor_name, $clause->[3])};
            next;
        }

        confess "Error: actor '$actor_name' use '$clause->[3]' has unsupported subclause '$head'\n";
    }

    confess "Error: actor '$actor_name' use '$clause->[3]' requires a '(bind ...)' subclause\n"
        unless $saw_bind;

    return {
        target              => $clause->[1],
        instance            => $clause->[3],
        parameter_overrides => \@params,
        bindings            => \@bindings,
        (defined($domain) ? (domain => $domain) : ()),
    };
}

sub _parse_use_params($self, $clause, $actor_name, $instance) {
    confess "Error: actor '$actor_name' use '$instance' params require '(params (NAME value) ...)'\n"
        unless @$clause >= 2;

    my @params;
    my %seen;
    for my $entry (@{$clause}[1 .. $#$clause]) {
        confess "Error: actor '$actor_name' use '$instance' params entries require '(NAME value)'\n"
            unless ref($entry) eq 'ARRAY' && @$entry == 2;
        my ($name, $value) = @$entry;
        confess "Error: actor '$actor_name' use '$instance' parameter override names must be scalar HDL identifiers\n"
            unless _is_hdl_identifier($name);
        confess "Error: actor '$actor_name' use '$instance' has duplicate parameter override '$name'\n"
            if $seen{$name}++;
        _validate_isf_param_value(
            $value,
            "Error: actor '$actor_name' use '$instance' parameter '$name'",
        );
        push @params, {
            name  => $name,
            value => _clone_isf_value($value),
        };
    }

    return \@params;
}

sub _parse_use_bind($self, $clause, $actor_name, $instance) {
    confess "Error: actor '$actor_name' use '$instance' bind requires binding entries\n"
        unless @$clause >= 2;

    my @bindings;
    for my $entry (@{$clause}[1 .. $#$clause]) {
        confess "Error: actor '$actor_name' use '$instance' bind entries must be list forms\n"
            unless ref($entry) eq 'ARRAY' && @$entry;
        my $role = $entry->[0];
        confess "Error: actor '$actor_name' use '$instance' bind entry roles must be scalar\n"
            unless defined($role) && !ref($role) && length($role);

        if ($role eq 'clock' || $role eq 'reset') {
            confess "Error: actor '$actor_name' use '$instance' $role binding requires '($role parent_signal)'\n"
                unless @$entry == 2
                    && defined($entry->[1])
                    && !ref($entry->[1])
                    && length($entry->[1]);
            push @bindings, {
                role        => $role,
                parent_name => $entry->[1],
            };
            next;
        }

        if ($role eq 'input' || $role eq 'output') {
            confess "Error: actor '$actor_name' use '$instance' $role binding requires '($role library_port parent_signal)'\n"
                unless @$entry == 3
                    && defined($entry->[1])
                    && !ref($entry->[1])
                    && length($entry->[1])
                    && defined($entry->[2])
                    && !ref($entry->[2])
                    && length($entry->[2]);
            push @bindings, {
                role         => $role,
                library_name => $entry->[1],
                parent_name  => $entry->[2],
            };
            next;
        }

        confess "Error: actor '$actor_name' use '$instance' has unsupported bind role '$role'\n";
    }

    return \@bindings;
}

sub _resolve_library_uses($self, $actor, $forms, $source_label) {
    return 1 unless @{$actor->{uses} || []};

    confess "Error: actor '$actor->{actor_name}' uses imported libraries but has no '(imports ...)' clause\n"
        unless @{$actor->{imports} || []};

    my %same_source_libraries = $self->_same_source_libraries($forms, $source_label);
    my %imports_by_alias;
    my %resolved_by_alias;

    for my $import (@{$actor->{imports}}) {
        my $alias = $import->{alias};
        my $library = $import->{library};
        confess "Error: actor '$actor->{actor_name}' has duplicate library import alias '$alias'\n"
            if $imports_by_alias{$alias}++;
        $resolved_by_alias{$alias} = $self->_resolve_library(
            $library,
            \%same_source_libraries,
            $source_label,
            {},
        );
    }

    my %seen_instance;
    my @resolved_uses;
    for my $use (@{$actor->{uses}}) {
        my $instance = $use->{instance};
        confess "Error: actor '$actor->{actor_name}' has duplicate library use instance '$instance'\n"
            if $seen_instance{$instance}++;

        my ($alias, $export) = _split_use_target($use->{target}, \%resolved_by_alias);
        confess "Error: actor '$actor->{actor_name}' use '$instance' target '$use->{target}' does not match any imported library alias\n"
            unless defined $alias;

        my $library = $resolved_by_alias{$alias};
        my $exported_actor = $library->{exports}{actor}{$export};
        confess "Error: actor '$actor->{actor_name}' use '$instance' references missing actor export '$export' from library '$library->{name}'\n"
            unless $exported_actor;

        $self->_validate_use_params($actor, $use, $exported_actor);
        my $bindings = $self->_validate_use_bindings($actor, $use, $exported_actor);

        my $module = _specialized_library_module_name($actor->{actor_name}, $instance);
        push @resolved_uses, {
            library             => $library->{name},
            library_source      => $library->{source},
            alias               => $alias,
            export              => $export,
            kind                => 'actor',
            instance            => $instance,
            module              => $module,
            scheduled_fsm       => "$module.fsm",
            actor               => _clone_isf_value($exported_actor),
            parameter_overrides => _clone_isf_value($use->{parameter_overrides} || []),
            bindings            => $bindings,
            (defined($use->{domain}) ? (domain => $use->{domain}) : ()),
        };
    }

    $actor->{library_uses} = \@resolved_uses;
    return 1;
}

sub _resolve_atl_actor_type_metadata($self, $actor, $forms, $source_label) {
    my @qualified_instances = grep {
        defined($_->{actor_type})
            && !ref($_->{actor_type})
            && _is_library_qualified_actor_type($_->{actor_type})
    } @{(($actor->{actor_network} || {})->{instances}) || []};
    return 1 unless @qualified_instances;

    my @imports = @{$actor->{imports} || []};
    confess "Error: actor '$actor->{actor_name}' ATL library-qualified static actor instance type"
        . " '$qualified_instances[0]->{actor_type}' requires an '(imports (library ... as alias))' clause;"
        . " valid ATL actor type resolution is required before generated child emission\n"
        unless @imports;

    my %same_source_libraries = $self->_same_source_libraries($forms, $source_label);
    my %imports_by_alias;
    my %resolved_by_alias;

    for my $import (@imports) {
        my $alias = $import->{alias};
        my $library = $import->{library};
        confess "Error: actor '$actor->{actor_name}' has duplicate library import alias '$alias'\n"
            if $imports_by_alias{$alias}++;
        $resolved_by_alias{$alias} = $self->_resolve_library(
            $library,
            \%same_source_libraries,
            $source_label,
            {},
        );
    }

    for my $instance (@qualified_instances) {
        my $name = $instance->{name};
        my $actor_type = $instance->{actor_type};
        my ($alias, $export) = _split_use_target($actor_type, \%resolved_by_alias);

        confess "Error: actor '$actor->{actor_name}' ATL static actor instance '$name' type '$actor_type'"
            . " must use '(instance $name of ALIAS.EXPORT)' where ALIAS is an imported library alias and EXPORT is a scalar actor export;"
            . " valid ATL actor type resolution is required before generated child emission\n"
            unless defined $alias;

        my $library = $resolved_by_alias{$alias};
        confess "Error: actor '$actor->{actor_name}' ATL static actor instance '$name' type '$actor_type'"
            . " must use an explicit HDL identifier library alias from '(imports (library $library->{name} as ALIAS))';"
            . " valid ATL actor type resolution is required before generated child emission\n"
            unless _is_hdl_identifier($alias);

        my $exported_actor = $library->{exports}{actor}{$export};
        confess "Error: actor '$actor->{actor_name}' ATL static actor instance '$name' type '$actor_type'"
            . " references missing actor export '$export' from library '$library->{name}';"
            . " valid ATL actor type resolution is required before generated child emission\n"
            unless $exported_actor;

        my $module = _specialized_library_module_name($actor->{actor_name}, $name);
        $instance->{type_resolution} = 'library_actor_export';
        $instance->{library}         = $library->{name};
        $instance->{alias}           = $alias;
        $instance->{export}          = $export;
        $instance->{module}          = $module;
        $instance->{scheduled_fsm}   = "$module.fsm";

        $actor->{_atl_actor_type_resolutions}{$name} = {
            library        => $library->{name},
            library_source => $library->{source},
            alias          => $alias,
            export         => $export,
            kind           => 'actor',
            instance       => $name,
            module         => $module,
            scheduled_fsm  => "$module.fsm",
            actor          => _clone_isf_value($exported_actor),
        };
    }

    return 1;
}

sub _finalize_atl_data_movement_endpoint_widths($self, $actor) {
    my $network = $actor->{actor_network};
    return 1 unless ref($network) eq 'HASH'
        && ref($network->{data_movements}) eq 'ARRAY'
        && @{$network->{data_movements}};

    my $resolutions = $actor->{_atl_actor_type_resolutions};
    if (!(ref($resolutions) eq 'HASH' && %$resolutions)) {
        for my $movement (@{$network->{data_movements}}) {
            my $kind = $movement->{kind} // '';
            if ($kind eq 'vector_pin_to_actor_handoff') {
                confess "Error: actor '$actor->{actor_name}' ATL generated-child pin-ingress data movement '$movement->{drive}' requires resolved child actor type metadata before vector top-level pin routes can be accepted; unqualified external vector pin routing remains deferred\n";
            }
            if ($kind eq 'vector_actor_to_pin_handoff') {
                confess "Error: actor '$actor->{actor_name}' ATL generated-child pin-egress data movement '$movement->{drive}' requires resolved child actor type metadata before vector top-level pin routes can be accepted; unqualified external vector pin routing remains deferred\n";
            }
        }
        return 1;
    }

    for my $movement (@{$network->{data_movements}}) {
        if ((($movement->{kind} // '') eq 'scalar_pin_to_actor_handoff'
                || ($movement->{kind} // '') eq 'vector_pin_to_actor_handoff')
            && ($movement->{source} // '') eq 'top_level_pin'
            && ($movement->{sink} // '') eq 'external_handoff')
        {
            my $sink_instance = $movement->{sink_instance};
            my $sink_endpoint = $movement->{sink_endpoint};
            my $source_pin = $movement->{source_endpoint};
            next unless defined($sink_instance) && !ref($sink_instance) && length($sink_instance)
                && defined($sink_endpoint) && !ref($sink_endpoint) && length($sink_endpoint)
                && defined($source_pin) && !ref($source_pin) && length($source_pin);

            my $sink_resolution = $resolutions->{$sink_instance};
            next unless ref($sink_resolution) eq 'HASH';

            my $sink_port = _atl_actor_type_resolution_port($sink_resolution, 'input', $sink_endpoint);
            next unless ref($sink_port) eq 'HASH';

            my $source_width = $movement->{width} // 1;
            my $sink_width = $sink_port->{width} // 1;
            confess "Error: actor '$actor->{actor_name}' ATL generated-child pin-ingress data movement '$movement->{drive}' top-level input pin 'pins.$source_pin' width $source_width does not match sink endpoint '$sink_instance.$sink_endpoint' width $sink_width; width adaptation remains deferred\n"
                unless $source_width == $sink_width;

            $movement->{width} = $source_width;
            if ($source_width > 1) {
                $movement->{kind} = 'vector_pin_to_actor_handoff';
                $movement->{width_source} = 'top_level_input_pin_resolved_child_endpoint_exact_width';
            } else {
                $movement->{kind} = 'scalar_pin_to_actor_handoff';
                $movement->{width_source} = 'top_level_pin_scalar_one_bit';
            }
            next;
        }

        if ((($movement->{kind} // '') eq 'scalar_actor_to_pin_handoff'
                || ($movement->{kind} // '') eq 'vector_actor_to_pin_handoff')
            && ($movement->{source} // '') eq 'external_handoff'
            && ($movement->{sink} // '') eq 'top_level_pin')
        {
            my $source_instance = $movement->{source_instance};
            my $source_endpoint = $movement->{source_endpoint};
            my $sink_pin = $movement->{sink_endpoint};
            next unless defined($source_instance) && !ref($source_instance) && length($source_instance)
                && defined($source_endpoint) && !ref($source_endpoint) && length($source_endpoint)
                && defined($sink_pin) && !ref($sink_pin) && length($sink_pin);

            my $source_resolution = $resolutions->{$source_instance};
            next unless ref($source_resolution) eq 'HASH';

            my $source_port = _atl_actor_type_resolution_port($source_resolution, 'output', $source_endpoint);
            next unless ref($source_port) eq 'HASH';

            my $source_width = $source_port->{width} // 1;
            my $sink_width = $movement->{width} // 1;
            confess "Error: actor '$actor->{actor_name}' ATL generated-child pin-egress data movement '$movement->{drive}' source endpoint '$source_instance.$source_endpoint' width $source_width does not match top-level output pin 'pins.$sink_pin' width $sink_width; width adaptation remains deferred\n"
                unless $source_width == $sink_width;

            $movement->{width} = $source_width;
            if ($source_width > 1) {
                $movement->{kind} = 'vector_actor_to_pin_handoff';
                $movement->{width_source} = 'top_level_output_pin_resolved_child_endpoint_exact_width';
            } else {
                $movement->{kind} = 'scalar_actor_to_pin_handoff';
                $movement->{width_source} = 'top_level_output_pin_scalar_one_bit';
            }
            next;
        }

        next unless ($movement->{kind} // '') eq 'scalar_actor_handoff'
            && ($movement->{source} // '') eq 'external_handoff'
            && ($movement->{sink} // '') eq 'external_handoff';

        my $source_instance = $movement->{source_instance};
        my $sink_instance = $movement->{sink_instance};
        my $source_endpoint = $movement->{source_endpoint};
        my $sink_endpoint = $movement->{sink_endpoint};
        next unless defined($source_instance) && !ref($source_instance) && length($source_instance)
            && defined($sink_instance) && !ref($sink_instance) && length($sink_instance)
            && defined($source_endpoint) && !ref($source_endpoint) && length($source_endpoint)
            && defined($sink_endpoint) && !ref($sink_endpoint) && length($sink_endpoint);

        my $source_resolution = $resolutions->{$source_instance};
        my $sink_resolution = $resolutions->{$sink_instance};
        next unless ref($source_resolution) eq 'HASH' && ref($sink_resolution) eq 'HASH';

        my $source_port = _atl_actor_type_resolution_port($source_resolution, 'output', $source_endpoint);
        my $sink_port = _atl_actor_type_resolution_port($sink_resolution, 'input', $sink_endpoint);
        next unless ref($source_port) eq 'HASH' && ref($sink_port) eq 'HASH';

        my $source_width = $source_port->{width} // 1;
        my $sink_width = $sink_port->{width} // 1;
        confess "Error: actor '$actor->{actor_name}' ATL generated-child actor-to-actor data movement '$movement->{drive}' source endpoint '$source_instance.$source_endpoint' width $source_width does not match sink endpoint '$sink_instance.$sink_endpoint' width $sink_width; width adaptation remains deferred\n"
            unless $source_width == $sink_width;

        $movement->{width} = $source_width;
        if ($source_width > 1) {
            $movement->{kind} = 'vector_actor_handoff';
            $movement->{width_source} = 'resolved_child_endpoint_exact_width';
        } else {
            $movement->{kind} = 'scalar_actor_handoff';
            $movement->{width_source} = 'scalar_one_bit';
        }
    }

    return 1;
}

sub _atl_actor_type_resolution_port {
    my ($resolution, $direction, $port_name) = @_;
    return undef unless ref($resolution) eq 'HASH'
        && defined($direction)
        && !ref($direction)
        && defined($port_name)
        && !ref($port_name);

    my $actor = $resolution->{actor};
    return undef unless ref($actor) eq 'HASH';

    my $ports = $direction eq 'input'
        ? (($actor->{interface} || {})->{inputs} || [])
        : $direction eq 'output'
            ? (($actor->{interface} || {})->{outputs} || [])
            : undef;
    return undef unless ref($ports) eq 'ARRAY';

    for my $port (@$ports) {
        next unless ref($port) eq 'HASH'
            && defined($port->{name})
            && !ref($port->{name})
            && $port->{name} eq $port_name;
        return $port;
    }

    return undef;
}

sub _same_source_libraries($self, $forms, $source_label) {
    my %libraries;
    for my $form (_forms_by_head($forms, 'library')) {
        my $library = $self->_parse_library_form($form, $source_label);
        confess "Error: duplicate library '$library->{name}' in '$source_label'\n"
            if exists $libraries{$library->{name}};
        $libraries{$library->{name}} = $library;
    }
    return %libraries;
}

sub _resolve_library($self, $library_name, $same_source_libraries, $source_label, $seen) {
    return $same_source_libraries->{$library_name}
        if exists $same_source_libraries->{$library_name};

    my @candidates = _library_file_candidates($library_name, $source_label);
    my @searched;
    for my $candidate (@candidates) {
        push @searched, $candidate;
        next unless -f $candidate && -r $candidate;
        my $abs = abs_path($candidate) || $candidate;
        my $key = "$abs:$library_name";
        confess "Error: recursive library import of '$library_name' through '$candidate' is unsupported\n"
            if $seen->{$key}++;

        my $source = _read_text_file($candidate);
        my $raw = Lispish::multi(\$source);
        confess "Error: failed to parse library '$library_name' source '$candidate' with Lispish\n"
            unless defined $raw && ref($raw) eq 'ARRAY';
        my $forms = $self->{adapter}->normalize_multi($raw);

        my @matching;
        for my $form (_forms_by_head($forms, 'library')) {
            next unless defined($form->[1]) && !ref($form->[1]) && $form->[1] eq $library_name;
            push @matching, $form;
        }
        confess "Error: library source '$candidate' contains multiple '(library $library_name ...)' roots\n"
            if @matching > 1;
        confess "Error: library source '$candidate' does not contain '(library $library_name ...)'\n"
            unless @matching;

        return $self->_parse_library_form($matching[0], $candidate);
    }

    confess "Error: library '$library_name' not found for '$source_label'; searched:\n"
        . join('', map { "  - $_\n" } @searched);
}

sub _parse_library_form($self, $form, $source_label) {
    confess "Error: (library ...) requires a scalar dotted namespace name\n"
        unless ref($form) eq 'ARRAY'
            && @$form >= 3
            && defined($form->[1])
            && !ref($form->[1])
            && _is_library_namespace($form->[1]);

    my $library_name = $form->[1];
    my %exported_actor_names;
    my %actor_defs;
    my $saw_exports;

    for my $clause (@{$form}[2 .. $#$form]) {
        confess "Error: library '$library_name' body clauses must be list forms\n"
            unless ref($clause) eq 'ARRAY' && @$clause;
        my $head = $clause->[0];
        confess "Error: library '$library_name' body clause heads must be scalar\n"
            unless defined($head) && !ref($head) && length($head);

        if ($head eq 'exports') {
            confess "Error: library '$library_name' accepts only one '(exports ...)'\n"
                if $saw_exports++;
            for my $entry (@{$clause}[1 .. $#$clause]) {
                confess "Error: library '$library_name' exports require '(actor name)' entries\n"
                    unless ref($entry) eq 'ARRAY'
                        && @$entry == 2
                        && defined($entry->[0])
                        && !ref($entry->[0])
                        && defined($entry->[1])
                        && !ref($entry->[1])
                        && length($entry->[1]);
                confess "Error: library '$library_name' export kind '$entry->[0]' is not supported yet; first shipped library exports are actors\n"
                    unless $entry->[0] eq 'actor';
                confess "Error: library '$library_name' has duplicate actor export '$entry->[1]'\n"
                    if $exported_actor_names{$entry->[1]}++;
            }
            next;
        }

        if ($head eq 'actor') {
            my $actor = $self->_build_actor($clause, $source_label);
            confess "Error: library '$library_name' has duplicate actor definition '$actor->{actor_name}'\n"
                if exists $actor_defs{$actor->{actor_name}};
            confess "Error: library '$library_name' actor '$actor->{actor_name}' cannot import libraries yet\n"
                if @{$actor->{imports} || []} || @{$actor->{uses} || []};
            $actor_defs{$actor->{actor_name}} = $actor;
            next;
        }

        confess "Error: library '$library_name' has unsupported body clause '$head'\n";
    }

    confess "Error: library '$library_name' requires an '(exports ...)' clause\n"
        unless $saw_exports;
    confess "Error: library '$library_name' exports at least one actor\n"
        unless keys %exported_actor_names;

    my %exports = (actor => {});
    for my $actor_name (sort keys %exported_actor_names) {
        confess "Error: library '$library_name' exports unknown actor '$actor_name'\n"
            unless exists $actor_defs{$actor_name};
        $exports{actor}{$actor_name} = $actor_defs{$actor_name};
    }

    return {
        name    => $library_name,
        source  => $source_label,
        exports => \%exports,
    };
}

sub _validate_use_params($self, $actor, $use, $exported_actor) {
    my %declared = map { $_->{name} => $_ } @{$exported_actor->{params} || []};
    for my $override (@{$use->{parameter_overrides} || []}) {
        my $name = $override->{name};
        confess "Error: actor '$actor->{actor_name}' use '$use->{instance}' overrides unknown parameter '$name'\n"
            unless exists $declared{$name};
        confess "Error: actor '$actor->{actor_name}' use '$use->{instance}' parameter '$name' shape does not match actor '$exported_actor->{actor_name}' declaration\n"
            unless _param_values_shape_compatible($declared{$name}{value}, $override->{value});
        $override->{value} = $self->_resolve_library_use_param_value(
            $actor,
            $override->{value},
            "actor '$actor->{actor_name}' use '$use->{instance}' parameter '$name'",
        );
    }
    return 1;
}

sub _resolve_library_use_param_value($self, $actor, $value, $context) {
    if (!ref($value)) {
        confess "Error: $context uses undefined parameter value; reusable-library use-site parameter overrides accept numeric, exact-width, actor-constant, actor scalar parameter, enum member, qualified package scalar constant, and aggregate/list literal values only\n"
            unless defined($value);
        return _clone_isf_value($value)
            if _is_numeric_or_exact_width_literal($value);
        if (_is_hdl_identifier($value)) {
            my $constant = _actor_constant_by_name($actor, $value);
            return _clone_isf_value(_constant_resolved_value($constant))
                if $constant;

            my $param = _actor_param_by_name($actor, $value);
            if ($param) {
                my $resolved_value = _param_resolved_value($param);
                confess "Error: $context actor parameter '$value' must resolve to a scalar numeric or exact-width literal\n"
                    unless defined($resolved_value)
                        && !ref($resolved_value)
                        && _is_numeric_or_exact_width_literal($resolved_value);
                return _clone_isf_value($resolved_value);
            }

            confess "Error: $context value '$value' is a runtime interface signal; reusable-library use-site parameter overrides accept static literals, actor constants, actor scalar parameters, enum members, qualified package scalar constants, and aggregate/list literals only\n"
                if _actor_interface_signal_by_name($actor, $value);

            confess "Error: $context uses unsupported parameter value '$value'; reusable-library use-site parameter overrides accept numeric, exact-width, actor-constant, actor scalar parameter, enum member, qualified package scalar constant, and aggregate/list literal values only\n";
        }
        if (my $package_constant = _actor_package_constant_reference($actor, $value)) {
            my ($package_name, $constant_name, $suffix) = @$package_constant;
            my $constant_payload = _actor_package_constant_payload($actor, $package_name, $constant_name);
            if (defined $constant_payload) {
                confess "Error: $context token '$value' is ambiguous: it matches local enum member '$value' and imported package constant '$value'\n"
                    if $suffix eq '' && _actor_local_enum_member_exists($actor, $package_name, $constant_name);
                confess "Error: $context package constant '$package_name.$constant_name' aggregate/member path '$value' remains deferred; reusable-library use-site parameter overrides accept only qualified package scalar constants in this slice\n"
                    if $suffix ne '';
                my $resolved_value = _package_constant_scalar_value($constant_payload);
                confess "Error: $context package constant '$package_name.$constant_name' must resolve to a scalar numeric or exact-width literal value\n"
                    unless defined($resolved_value)
                        && !ref($resolved_value)
                        && _is_numeric_or_exact_width_literal($resolved_value);
                return _clone_isf_value($resolved_value);
            }

            confess "Error: $context references unknown package constant '$value'\n"
                if $suffix eq '' && !_actor_local_enum_member_exists($actor, $package_name, $constant_name);
        }
        if (_is_enum_member_reference($value)) {
            my $resolved_value = $self->_resolve_actor_enum_member_value($actor, $value);
            confess "Error: $context references unknown enum member '$value'\n"
                unless defined($resolved_value) && !ref($resolved_value);
            confess "Error: $context enum member '$value' must resolve to a non-negative integer literal value\n"
                unless _is_non_negative_integer_literal_value($resolved_value);
            return _clone_isf_value($resolved_value);
        }

        confess "Error: $context uses unsupported parameter value '$value'; reusable-library use-site parameter overrides accept numeric, exact-width, actor-constant, actor scalar parameter, enum member, qualified package scalar constant, and aggregate/list literal values only\n";
    }

    confess "Error: $context uses unsupported parameter value shape; reusable-library use-site parameter overrides accept non-empty aggregate/list literal values only\n"
        unless ref($value) eq 'ARRAY' && @$value;

    return [
        map {
            $self->_resolve_library_use_param_value($actor, $_, $context)
        } @$value
    ];
}

sub _validate_use_bindings($self, $actor, $use, $exported_actor) {
    my $timing = _library_use_timing($actor, $use);
    my @bindings = @{$use->{bindings} || []};
    my %parent_ports = (
        map({ $_->{name} => { %$_, direction => 'input' } } @{$actor->{interface}{inputs} || []}),
        map({ $_->{name} => { %$_, direction => 'output' } } @{$actor->{interface}{outputs} || []}),
    );
    my %library_ports = (
        map({ $_->{name} => { %$_, direction => 'input' } } @{$exported_actor->{interface}{inputs} || []}),
        map({ $_->{name} => { %$_, direction => 'output' } } @{$exported_actor->{interface}{outputs} || []}),
    );

    my %seen_clock_reset;
    my %seen_library_port;
    my @resolved;

    for my $binding (@bindings) {
        my $role = $binding->{role};
        if ($role eq 'clock' || $role eq 'reset') {
            confess "Error: actor '$actor->{actor_name}' use '$use->{instance}' has duplicate $role binding\n"
                if $seen_clock_reset{$role}++;
            my $parent_name = $binding->{parent_name};
            confess "Error: actor '$actor->{actor_name}' use '$use->{instance}' $role binding references unknown parent signal '$parent_name'\n"
                unless exists $parent_ports{$parent_name}
                    || _actor_has_system_signal($actor, $role, $parent_name);
            if (ref($actor->{clock_domains}) eq 'HASH') {
                my $expected = $role eq 'clock' ? $timing->{clock} : ($timing->{reset} || {})->{name};
                confess "Error: actor '$actor->{actor_name}' use '$use->{instance}' $role binding must use domain '$timing->{name}' $role signal '" . ($expected // '<none>') . "', not '$parent_name'\n"
                    unless defined($expected) && $parent_name eq $expected;
            }
            push @resolved, { %$binding, width => 1 };
            next;
        }

        my $library_name = $binding->{library_name};
        my $parent_name = $binding->{parent_name};
        confess "Error: actor '$actor->{actor_name}' use '$use->{instance}' has duplicate binding for library port '$library_name'\n"
            if $seen_library_port{$library_name}++;
        confess "Error: actor '$actor->{actor_name}' use '$use->{instance}' references unknown library port '$library_name'\n"
            unless exists $library_ports{$library_name};
        confess "Error: actor '$actor->{actor_name}' use '$use->{instance}' binding for '$library_name' declares role '$role' but exported actor role is '$library_ports{$library_name}{direction}'\n"
            unless $library_ports{$library_name}{direction} eq $role;
        confess "Error: actor '$actor->{actor_name}' use '$use->{instance}' binding for '$library_name' references unknown parent signal '$parent_name'\n"
            unless exists $parent_ports{$parent_name};
        confess "Error: actor '$actor->{actor_name}' use '$use->{instance}' binding for '$library_name' targets parent '$parent_name' with direction '$parent_ports{$parent_name}{direction}', expected '$role'\n"
            unless $parent_ports{$parent_name}{direction} eq $role;

        my $library_width = $library_ports{$library_name}{width} // 1;
        my $parent_width = $parent_ports{$parent_name}{width} // 1;
        confess "Error: actor '$actor->{actor_name}' use '$use->{instance}' binding for '$library_name' width $library_width does not match parent '$parent_name' width $parent_width\n"
            unless $library_width == $parent_width;

        push @resolved, { %$binding, width => $library_width };
    }

    if (defined($exported_actor->{clock}) && length($exported_actor->{clock}) && !$seen_clock_reset{clock}) {
        my $implicit_clock = _implicit_same_name_clock_binding($timing, $exported_actor);
        if ($implicit_clock) {
            push @resolved, $implicit_clock;
            $seen_clock_reset{clock} = 1;
        }
    }
    confess "Error: actor '$actor->{actor_name}' use '$use->{instance}' requires a clock binding for actor '$exported_actor->{actor_name}'\n"
        if defined($exported_actor->{clock}) && length($exported_actor->{clock}) && !$seen_clock_reset{clock};
    confess "Error: actor '$actor->{actor_name}' use '$use->{instance}' has a clock binding but actor '$exported_actor->{actor_name}' has no clock\n"
        if (!defined($exported_actor->{clock}) || !length($exported_actor->{clock})) && $seen_clock_reset{clock};
    if ($exported_actor->{reset} && !$seen_clock_reset{reset}) {
        my $implicit_reset = _implicit_same_name_reset_binding($timing, $exported_actor);
        if ($implicit_reset) {
            push @resolved, $implicit_reset;
            $seen_clock_reset{reset} = 1;
        }
    }
    confess "Error: actor '$actor->{actor_name}' use '$use->{instance}' requires a reset binding for actor '$exported_actor->{actor_name}'\n"
        if $exported_actor->{reset} && !$seen_clock_reset{reset};
    confess "Error: actor '$actor->{actor_name}' use '$use->{instance}' has a reset binding but actor '$exported_actor->{actor_name}' has no reset\n"
        if !$exported_actor->{reset} && $seen_clock_reset{reset};

    for my $port_name (sort keys %library_ports) {
        confess "Error: actor '$actor->{actor_name}' use '$use->{instance}' does not bind library port '$port_name'\n"
            unless $seen_library_port{$port_name};
    }

    return \@resolved;
}

# Library resolution precedes annotation materialization. Resolve the use's
# explicit/default domain here without borrowing the default compatibility pins.
sub _library_use_timing {
    my ($actor, $use) = @_;
    return $actor unless ref($actor->{clock_domains}) eq 'HASH';
    my $name = $use->{domain} // $actor->{clock_domains}{default};
    my ($domain) = grep { $_->{name} eq $name } @{$actor->{clock_domains}{domains} || []};
    confess "Error: actor '$actor->{actor_name}' use '$use->{instance}' uses unknown clock domain '$name'\n"
        unless $domain;
    return $domain;
}

sub _actor_has_system_signal {
    my ($actor, $role, $name) = @_;
    my @timings = ref($actor->{clock_domains}) eq 'HASH'
        ? @{$actor->{clock_domains}{domains} || []} : ($actor);
    for my $timing (@timings) {
        my $signal = $role eq 'clock' ? $timing->{clock} : ($timing->{reset} || {})->{name};
        return 1 if defined($signal) && $signal eq $name;
    }
    return 0;
}

sub _implicit_same_name_clock_binding {
    my ($actor, $exported_actor) = @_;
    return undef unless defined($actor->{clock})
        && defined($exported_actor->{clock})
        && length($actor->{clock})
        && length($exported_actor->{clock})
        && $actor->{clock} eq $exported_actor->{clock};

    return {
        role         => 'clock',
        library_name => undef,
        parent_name  => $actor->{clock},
        width        => 1,
    };
}

sub _implicit_same_name_reset_binding {
    my ($actor, $exported_actor) = @_;
    return undef unless ref($actor->{reset}) eq 'HASH'
        && ref($exported_actor->{reset}) eq 'HASH';
    return undef unless _reset_policy_signature($actor->{reset})
        eq _reset_policy_signature($exported_actor->{reset});

    return {
        role         => 'reset',
        library_name => undef,
        parent_name  => $actor->{reset}{name},
        width        => 1,
    };
}

sub _reset_policy_signature {
    my ($reset) = @_;
    return join "\0",
        $reset->{name} // '',
        $reset->{kind} // 'sync',
        $reset->{polarity} // 'active_high';
}

sub _split_use_target($target, $libraries_by_alias) {
    for my $alias (sort { length($b) <=> length($a) || $a cmp $b } keys %{$libraries_by_alias || {}}) {
        next unless index($target, "$alias.") == 0;
        my $export = substr($target, length($alias) + 1);
        next unless defined($export) && length($export) && _is_hdl_identifier($export);
        return ($alias, $export);
    }
    return (undef, undef);
}

sub _library_file_candidates($library_name, $source_label) {
    my @roots;
    if (defined($source_label) && !ref($source_label) && -f $source_label) {
        push @roots, dirname(File::Spec->rel2abs($source_label));
    }
    push @roots, grep { defined($_) && length($_) } split(/:/, $ENV{FSMLIB} || '');
    push @roots, File::Spec->curdir();

    my $flat = "$library_name.isf";
    my $pathish = File::Spec->catfile(split(/\./, $library_name)) . '.isf';
    my @candidates;
    my %seen;
    for my $root (@roots) {
        for my $rel ($flat, $pathish) {
            my $candidate = File::Spec->catfile($root, $rel);
            push @candidates, $candidate unless $seen{$candidate}++;
        }
    }
    return @candidates;
}

sub _specialized_library_module_name($actor_name, $instance) {
    my $name = "${actor_name}__${instance}";
    $name =~ s/[^A-Za-z0-9_]/_/g;
    return $name;
}

sub _is_hdl_identifier {
    my ($value) = @_;
    return defined($value) && !ref($value) && $value =~ /\A[A-Za-z_]\w*\z/;
}

sub _is_library_qualified_actor_type {
    my ($value) = @_;
    return defined($value)
        && !ref($value)
        && index($value, '.') >= 0
        && _is_library_namespace($value);
}

sub _is_type_reference {
    my ($value) = @_;
    return defined($value) && !ref($value) && $value =~ /\A[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)?\z/;
}

sub _is_enum_member_reference {
    my ($value) = @_;
    return defined($value) && !ref($value) && $value =~ /\A[A-Za-z_]\w*\.[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)?\z/;
}

sub _is_package_constant_path_reference_shape {
    my ($value) = @_;
    return defined($value)
        && !ref($value)
        && $value =~ /\A[A-Za-z_]\w*\.[A-Za-z_]\w*(?:\.[A-Za-z_]\w*|\[\d+\])+\z/;
}

sub _is_aggregate_type_spec {
    my ($type_spec) = @_;
    return 0 unless ref($type_spec) eq 'HASH';
    my $kind = $type_spec->{kind} || '';
    return ($kind eq 'list' || $kind eq 'record') ? 1 : 0;
}

sub _is_activation_input_binding_expr_shape {
    my ($expr) = @_;
    return 1 if ref($expr) eq 'ARRAY' && @$expr;
    return 0 if ref($expr);
    return 0 unless defined($expr) && length($expr);
    return 1 if _is_hdl_identifier($expr);
    return 1 if _is_numeric_or_exact_width_literal($expr);
    return 0;
}

sub _is_library_namespace {
    my ($value) = @_;
    return defined($value)
        && !ref($value)
        && $value =~ /\A[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)*\z/;
}

sub _is_package_constant_reference_shape {
    my ($value) = @_;
    return defined($value)
        && !ref($value)
        && $value =~ /\A[A-Za-z_]\w*\.[A-Za-z_]\w*(?:\.[A-Za-z_]\w*|\[\d+\])*\z/;
}

sub _validate_isf_param_value {
    my ($value, $context) = @_;
    if (!ref($value)) {
        confess "$context uses unsupported parameter value '$value'; first ISF library parameter binding accepts numeric, exact-width, actor-constant, actor scalar parameter, enum member, qualified package scalar constant, and aggregate/list literals only\n"
            unless defined($value)
                && (_is_numeric_or_exact_width_literal($value)
                    || _is_hdl_identifier($value)
                    || _is_enum_member_reference($value)
                    || _is_package_constant_reference_shape($value));
        return 1;
    }

    confess "$context uses unsupported parameter value shape; first ISF library parameter binding accepts non-empty aggregate/list literals only\n"
        unless ref($value) eq 'ARRAY' && @$value;

    for my $item (@$value) {
        _validate_isf_param_value($item, $context);
    }
    return 1;
}

sub _validate_actor_param_value {
    my ($value, $context) = @_;
    if (!ref($value)) {
        confess "$context uses unsupported parameter value '$value'; actor parameter defaults accept numeric, exact-width, aggregate/list, actor constant, earlier scalar actor parameter, scalar enum member, and qualified package scalar constant literals only\n"
            unless defined($value)
                && (_is_numeric_or_exact_width_literal($value)
                    || _is_hdl_identifier($value)
                    || _is_enum_member_reference($value)
                    || _is_package_constant_path_reference_shape($value));
        return 1;
    }

    confess "$context uses unsupported parameter value shape; actor parameter defaults accept non-empty aggregate/list literals\n"
        unless ref($value) eq 'ARRAY' && @$value;

    for my $item (@$value) {
        _validate_actor_param_aggregate_leaf_value($item, $context);
    }
    return 1;
}

sub _validate_actor_param_aggregate_leaf_value {
    my ($value, $context) = @_;
    if (!ref($value)) {
        confess "$context uses unsupported aggregate/list parameter leaf '$value'; actor parameter aggregate/list defaults accept numeric, exact-width, actor constant, earlier scalar actor parameter, enum member, and qualified package scalar constant literal leaves only\n"
            unless defined($value)
                && (_is_numeric_or_exact_width_literal($value)
                    || _is_hdl_identifier($value)
                    || _is_enum_member_reference($value)
                    || _is_package_constant_path_reference_shape($value));
        return 1;
    }

    confess "$context uses unsupported parameter value shape; actor parameter defaults accept non-empty aggregate/list literals\n"
        unless ref($value) eq 'ARRAY' && @$value;

    for my $item (@$value) {
        _validate_actor_param_aggregate_leaf_value($item, $context);
    }
    return 1;
}

sub _is_numeric_or_exact_width_literal {
    my ($value) = @_;
    return 0 unless defined($value) && !ref($value);
    return 1 if $value =~ /\A\d+\z/;
    return 1 if $value =~ /\A\d+'[bBoOdDhH][0-9a-fA-F_xXzZ]+\z/;
    return 0;
}

sub _is_non_negative_integer_literal_value {
    my ($value) = @_;
    return 0 unless defined($value) && !ref($value);

    my $integer = FSM::Package::IntegerLiteralSupport->integer_from_literal_like($value);
    return 0 unless defined $integer;
    return $integer->bcmp(0) >= 0;
}

sub _positive_integer_from_literal_value {
    my ($value) = @_;
    return undef unless defined($value) && !ref($value);

    my $integer = FSM::Package::IntegerLiteralSupport->integer_from_literal_like($value);
    return undef unless defined $integer && $integer->bcmp(0) > 0;
    return 0 + $integer->bstr;
}

sub _constant_resolved_value {
    my ($constant) = @_;
    return undef unless ref($constant) eq 'HASH';
    return exists($constant->{resolved_value})
        ? $constant->{resolved_value}
        : $constant->{value};
}

sub _param_resolved_value {
    my ($param) = @_;
    return undef unless ref($param) eq 'HASH';
    return exists($param->{resolved_value})
        ? $param->{resolved_value}
        : $param->{value};
}

sub _param_values_shape_compatible {
    my ($declared, $override) = @_;
    return 1 if !ref($declared) && !ref($override);
    return 0 unless ref($declared) eq 'ARRAY' && ref($override) eq 'ARRAY';
    return 0 unless @$declared == @$override;
    for my $index (0 .. $#$declared) {
        return 0 unless _param_values_shape_compatible($declared->[$index], $override->[$index]);
    }
    return 1;
}

sub _clone_isf_value {
    my ($value) = @_;
    return [ map { _clone_isf_value($_) } @$value ] if ref($value) eq 'ARRAY';
    return { map { $_ => _clone_isf_value($value->{$_}) } keys %$value } if ref($value) eq 'HASH';
    return $value;
}

sub _parse_clock($self, $clause) {
    confess "Error: (clock ...) requires exactly one name\n" unless @$clause == 2;
    confess "Error: (clock ...) requires a scalar name\n"
        unless defined($clause->[1]) && !ref($clause->[1]) && length($clause->[1]);
    return $clause->[1];
}

sub _parse_reset($self, $clause) {
    confess "Error: (reset ...) requires exactly one reset specification\n"
        unless @$clause == 2;
    my $spec = $clause->[1];
    # Flat form: (reset rst_n)
    if (!ref($spec)) {
        confess "Error: (reset ...) requires a scalar name\n"
            unless defined($spec) && length($spec);
        my $polarity = $spec =~ /_[nb]$/ ? 'active_low' : 'active_high';
        return { name => $spec, kind => 'sync', polarity => $polarity };
    }
    # List form: (reset (rst_n async active_low))
    confess "Error: (reset ...) requires a name\n" unless ref($spec) eq 'ARRAY';
    my $name = $spec->[0];
    confess "Error: (reset ...) requires a scalar name\n"
        unless defined($name) && !ref($name) && length($name);
    my $kind = 'sync';
    my $polarity = $name =~ /_[nb]$/ ? 'active_low' : 'active_high';
    my %seen;

    for my $i (1 .. $#$spec) {
        my $val = $spec->[$i];
        # Lispish may retain an undefined tail; it is not an authored option.
        next unless defined $val;
        confess "Error: (reset ...) reset options must be scalar\n" if ref($val);
        if ($val eq 'sync' || $val eq 'async') {
            confess "Error: (reset ...) duplicate or conflicting reset timing\n"
                if $seen{kind}++;
            $kind = $val;
        } elsif ($val eq 'active_low' || $val eq 'active_high') {
            confess "Error: (reset ...) duplicate or conflicting reset polarity\n"
                if $seen{polarity}++;
            $polarity = $val;
        } else {
            confess "Error: (reset ...) unsupported reset option '$val'; expected sync, async, active_low, or active_high\n";
        }
    }

    return { name => $name, kind => $kind, polarity => $polarity };
}

sub _parse_clock_domains($self, $clause, $actor_name) {
    confess "Error: actor '$actor_name' clock-domains require '(clock-domains (domain name (clock clk) ...) ...)'\n"
        unless @$clause >= 2;

    my @domains;
    my %seen_domain;
    my %seen_clock;
    my %reset_by_name;
    my @default_domains;

    for my $entry (@{$clause}[1 .. $#$clause]) {
        confess "Error: actor '$actor_name' clock-domains entries require '(domain name (clock clk) ...)'\n"
            unless ref($entry) eq 'ARRAY'
                && @$entry >= 3
                && defined($entry->[0])
                && !ref($entry->[0])
                && $entry->[0] eq 'domain';

        my $name = $entry->[1];
        confess "Error: actor '$actor_name' clock-domain names must be scalar HDL identifiers\n"
            unless _is_hdl_identifier($name);
        confess "Error: actor '$actor_name' has duplicate clock domain '$name'\n"
            if $seen_domain{$name}++;

        my (%seen_subclause, $clock, $reset);
        my $is_default = 0;
        for my $part (@{$entry}[2 .. $#$entry]) {
            if (defined($part) && !ref($part) && $part eq ':default') {
                confess "Error: actor '$actor_name' clock domain '$name' has duplicate ':default' marker\n"
                    if $is_default++;
                push @default_domains, $name;
                next;
            }

            confess "Error: actor '$actor_name' clock domain '$name' entries must be '(clock ...)', '(reset ...)', or ':default'\n"
                unless ref($part) eq 'ARRAY'
                    && @$part
                    && defined($part->[0])
                    && !ref($part->[0])
                    && length($part->[0]);

            my $head = $part->[0];
            confess "Error: actor '$actor_name' clock domain '$name' has duplicate '$head' subclause\n"
                if $seen_subclause{$head}++;

            if ($head eq 'clock') {
                $clock = $self->_parse_clock($part);
                next;
            }
            if ($head eq 'reset') {
                confess "Error: actor '$actor_name' clock domain '$name' reset requires '(reset name_or_reset_spec)'\n"
                    unless @$part == 2;
                $reset = $self->_parse_reset($part);
                next;
            }

            confess "Error: actor '$actor_name' clock domain '$name' has unsupported subclause '$head'\n";
        }

        confess "Error: actor '$actor_name' clock domain '$name' requires '(clock name)'\n"
            unless defined($clock);
        confess "Error: actor '$actor_name' clock signal '$clock' is used by multiple clock domains\n"
            if $seen_clock{$clock}++;

        if ($reset) {
            my $previous = $reset_by_name{$reset->{name}};
            confess "Error: actor '$actor_name' reset '$reset->{name}' is reused with conflicting clock-domain reset policy\n"
                if $previous
                    && (($previous->{kind} // 'sync') ne ($reset->{kind} // 'sync')
                        || ($previous->{polarity} // 'active_high') ne ($reset->{polarity} // 'active_high'));
            $reset_by_name{$reset->{name}} = $reset;
        }

        my %domain = (
            name  => $name,
            clock => $clock,
        );
        $domain{reset} = $reset if $reset;
        $domain{default} = 1 if $is_default;
        push @domains, \%domain;
    }

    my $default;
    if (@domains == 1 && !@default_domains) {
        $default = $domains[0]{name};
        $domains[0]{default} = 1;
    } else {
        confess "Error: actor '$actor_name' multi-domain clock-domains require exactly one ':default' domain\n"
            unless @default_domains == 1;
        $default = $default_domains[0];
    }

    return {
        default => $default,
        domains => \@domains,
    };
}

sub _parse_crossings($self, $clause, $actor_name) {
    confess "Error: actor '$actor_name' crossings require '(crossings (event name ...) ...)'\n"
        unless @$clause >= 2;

    my @crossings;
    my %seen_event;
    my %seen_signal;
    my %seen_activation_child;

    for my $entry (@{$clause}[1 .. $#$clause]) {
        confess "Error: actor '$actor_name' crossings entries require '(event name (from domain signal) (to domain signal) (ready signal))' or '(activation child (from domain) (to domain))'\n"
            unless ref($entry) eq 'ARRAY'
                && @$entry >= 2
                && defined($entry->[0])
                && !ref($entry->[0])
                && ($entry->[0] eq 'event' || $entry->[0] eq 'activation');

        if ($entry->[0] eq 'activation') {
            push @crossings,
                $self->_parse_activation_crossing($entry, $actor_name, \%seen_activation_child);
            next;
        }

        confess "Error: actor '$actor_name' crossings event entries require '(event name (from domain signal) (to domain signal) (ready signal))'\n"
            unless @$entry >= 5;

        my $name = $entry->[1];
        confess "Error: actor '$actor_name' crossing event names must be scalar HDL identifiers\n"
            unless _is_hdl_identifier($name);
        confess "Error: actor '$actor_name' has duplicate crossing event '$name'\n"
            if $seen_event{$name}++;

        my (%seen_subclause, $from, $to, $ready);
        for my $part (@{$entry}[2 .. $#$entry]) {
            confess "Error: actor '$actor_name' crossing event '$name' subclauses must be '(from domain signal)', '(to domain signal)', or '(ready signal)'\n"
                unless ref($part) eq 'ARRAY'
                    && @$part
                    && defined($part->[0])
                    && !ref($part->[0])
                    && length($part->[0]);

            my $head = $part->[0];
            confess "Error: actor '$actor_name' crossing event '$name' has duplicate '$head' subclause\n"
                if $seen_subclause{$head}++;

            if ($head eq 'from' || $head eq 'to') {
                confess "Error: actor '$actor_name' crossing event '$name' requires '($head domain signal)'\n"
                    unless @$part == 3
                        && _is_hdl_identifier($part->[1])
                        && _is_hdl_identifier($part->[2]);
                my $parsed = {
                    domain => $part->[1],
                    signal => $part->[2],
                };
                $from = $parsed if $head eq 'from';
                $to = $parsed if $head eq 'to';
                next;
            }

            if ($head eq 'ready') {
                confess "Error: actor '$actor_name' crossing event '$name' requires '(ready signal)'\n"
                    unless @$part == 2 && _is_hdl_identifier($part->[1]);
                $ready = { signal => $part->[1] };
                next;
            }

            confess "Error: actor '$actor_name' crossing event '$name' has unsupported subclause '$head'\n";
        }

        confess "Error: actor '$actor_name' crossing event '$name' requires '(from domain signal)'\n"
            unless $from;
        confess "Error: actor '$actor_name' crossing event '$name' requires '(to domain signal)'\n"
            unless $to;
        confess "Error: actor '$actor_name' crossing event '$name' requires '(ready signal)'\n"
            unless $ready;

        for my $endpoint ($from->{signal}, $to->{signal}, $ready->{signal}) {
            confess "Error: actor '$actor_name' crossing endpoint signal '$endpoint' is used by multiple crossing endpoints\n"
                if $seen_signal{$endpoint}++;
        }

        push @crossings, {
            kind  => 'event',
            name  => $name,
            from  => $from,
            to    => $to,
            ready => $ready,
        };
    }

    return \@crossings;
}

# Parse a `(activation child (from domain) (to domain))` crossing: declares that
# `child` (a transaction in the `to` domain) may be activated by a blocking
# cross-domain (do)/(spawn) from a transaction in the `from` domain. Unlike an
# event crossing, the synchronized signals are the activation start/done handoff
# ports, which are compiler-internal, so the entry names only the child and the
# two domains (no explicit signals).
sub _parse_activation_crossing($self, $entry, $actor_name, $seen_child) {
    confess "Error: actor '$actor_name' activation crossing requires '(activation child (from domain) (to domain))'\n"
        unless @$entry >= 4;

    my $child = $entry->[1];
    confess "Error: actor '$actor_name' activation crossing child must be a scalar HDL identifier\n"
        unless _is_hdl_identifier($child);
    confess "Error: actor '$actor_name' has duplicate activation crossing for child '$child'\n"
        if $seen_child->{$child}++;

    my (%seen_subclause, $from, $to);
    for my $part (@{$entry}[2 .. $#$entry]) {
        confess "Error: actor '$actor_name' activation crossing '$child' subclauses must be '(from domain)' or '(to domain)'\n"
            unless ref($part) eq 'ARRAY'
                && @$part
                && defined($part->[0])
                && !ref($part->[0])
                && length($part->[0]);

        my $head = $part->[0];
        confess "Error: actor '$actor_name' activation crossing '$child' has duplicate '$head' subclause\n"
            if $seen_subclause{$head}++;

        if ($head eq 'from' || $head eq 'to') {
            confess "Error: actor '$actor_name' activation crossing '$child' requires '($head domain)'\n"
                unless @$part == 2 && _is_hdl_identifier($part->[1]);
            $from = { domain => $part->[1] } if $head eq 'from';
            $to   = { domain => $part->[1] } if $head eq 'to';
            next;
        }

        confess "Error: actor '$actor_name' activation crossing '$child' has unsupported subclause '$head'\n";
    }

    confess "Error: actor '$actor_name' activation crossing '$child' requires '(from domain)'\n"
        unless $from;
    confess "Error: actor '$actor_name' activation crossing '$child' requires '(to domain)'\n"
        unless $to;

    return {
        kind  => 'activation',
        child => $child,
        from  => $from,
        to    => $to,
    };
}

sub _finalize_actor_clock_domain_timing($self, $actor, $singleton_actor_clauses) {
    return 1 unless ref($actor->{clock_domains}) eq 'HASH';

    my $actor_name = $actor->{actor_name};
    confess "Error: actor '$actor_name' cannot mix '(clock ...)' with '(clock-domains ...)'\n"
        if $singleton_actor_clauses->{clock};
    confess "Error: actor '$actor_name' cannot mix actor-level '(reset ...)' with '(clock-domains ...)'\n"
        if $singleton_actor_clauses->{reset};

    my $default_domain = $actor->{clock_domains}{default};
    my ($domain) = grep { $_->{name} eq $default_domain } @{$actor->{clock_domains}{domains} || []};
    confess "Error: actor '$actor_name' clock-domains default '$default_domain' is not declared\n"
        unless $domain;

    $actor->{clock} = $domain->{clock};
    $actor->{reset} = _clone_isf_value($domain->{reset}) if $domain->{reset};
    return 1;
}

sub _finalize_actor_timing_conventions($self, $actor, $singleton_actor_clauses) {
    my $has_clock_domains = ref($actor->{clock_domains}) eq 'HASH';

    # Capture source evidence before legacy defaults make the policies identical.
    $actor->{reset_provenance} = $has_clock_domains
        ? [map { {domain => $_->{name}, origin => $_->{reset} ? 'explicit' : 'domain_absent'} }
            @{$actor->{clock_domains}{domains}}]
        : [{domain => undef, origin => $singleton_actor_clauses->{reset} ? 'explicit' : 'legacy_default'}];

    if (!$has_clock_domains) {
        $actor->{clock} = ISF_DEFAULT_CLOCK_NAME
            unless $singleton_actor_clauses->{clock};
        $actor->{reset} = _default_actor_reset()
            unless $singleton_actor_clauses->{reset};
    }

    $actor->{watchdog} = ISF_DEFAULT_WATCHDOG_LIMIT
        unless $singleton_actor_clauses->{watchdog};

    return 1;
}

sub _default_actor_reset {
    return {
        name     => ISF_DEFAULT_RESET_NAME,
        kind     => 'async',
        polarity => 'active_low',
    };
}

sub _parse_watchdog($self, $clause) {
    confess "Error: (watchdog ...) requires a positive integer literal, actor constant, actor scalar parameter, or qualified package scalar constant\n"
        unless @$clause == 2;
    confess "Error: (watchdog ...) requires a positive integer literal, actor constant, actor scalar parameter, or qualified package scalar constant\n"
        unless defined($clause->[1])
            && !ref($clause->[1])
            && ($clause->[1] =~ /\A[1-9][0-9]*\z/
                || _is_hdl_identifier($clause->[1])
                || _is_package_constant_reference_shape($clause->[1]));
    return $clause->[1];
}

sub _parse_interface($self, $clause) {
    my @inputs;
    my @outputs;
    my %seen_names;

    for my $i (1 .. $#$clause) {
        my $port = $clause->[$i];
        confess "Error: interface port must be a list\n" unless ref($port) eq 'ARRAY';
        my $dir = $port->[0];
        my $name = $port->[1];
        my $width = 1;
        my $type;
        my $domain;
        my $reset_value;
        my $default_value;

        confess "Error: interface port direction must be input or output\n"
            unless defined($dir) && !ref($dir) && ($dir eq 'input' || $dir eq 'output');
        confess "Error: interface port requires a scalar name\n"
            unless defined($name) && !ref($name) && length($name);
        confess "Error: duplicate interface port '$name'\n" if $seen_names{$name}++;

        # Interface options are closed: never discard an authored clause.
        my %seen_options;
        for my $j (2 .. $#$port) {
            my $prop = $port->[$j];
            confess "Error: interface port '$name' option must be a non-empty list\n"
                unless ref($prop) eq 'ARRAY' && @$prop;
            my $option_name = $prop->[0];
            confess "Error: interface port '$name' option name must be a non-empty scalar\n"
                unless defined($option_name) && !ref($option_name) && length($option_name);
            confess "Error: interface port '$name' has duplicate '$option_name' option\n"
                if $seen_options{$option_name}++;
            if ($option_name eq 'width') {
                confess "Error: interface port '$name' width must be a positive integer, actor constant, actor scalar parameter, or qualified package scalar constant\n"
                    unless @$prop == 2
                        && defined($prop->[1])
                        && !ref($prop->[1])
                        && ($prop->[1] =~ /\A[1-9][0-9]*\z/
                            || _is_hdl_identifier($prop->[1])
                            || _is_package_constant_reference_shape($prop->[1]));
                $width = $prop->[1];
                next;
            }
            if ($prop->[0] eq 'type') {
                confess "Error: interface port '$name' type requires '(type NAME)'\n"
                    unless @$prop == 2 && _is_type_reference($prop->[1]);
                $type = $prop->[1];
                next;
            }
            if ($prop->[0] eq 'domain') {
                $domain = _parse_domain_option(
                    $prop,
                    "Error: interface port '$name' domain",
                );
                next;
            }
            if ($prop->[0] eq 'reset' || $prop->[0] eq 'default') {
                confess "Error: interface input '$name' cannot specify output '$prop->[0]' metadata\n"
                    unless $dir eq 'output';
                my $value = _parse_interface_output_static_value($prop, $name);
                if ($prop->[0] eq 'reset') {
                    $reset_value = $value;
                } else {
                    $default_value = $value;
                }
                next;
            }
            confess "Error: interface port '$name' has unsupported '$option_name' option\n";
        }
        confess "Error: interface port '$name' cannot specify both '(width ...)' and '(type ...)'\n"
            if defined($type) && exists($seen_options{width});
        if (defined($reset_value) || defined($default_value)) {
            confess "Error: interface output '$name' output reset/default metadata requires a resolved positive integer width; '(type ...)' outputs remain deferred\n"
                if defined $type;
            confess "Error: interface output '$name' output reset/default metadata requires a resolved positive integer width\n"
                unless defined($width) && !ref($width) && $width =~ /\A[1-9][0-9]*\z/;
            _validate_interface_output_static_value_fits($name, 'reset', $reset_value, $width)
                if defined $reset_value;
            _validate_interface_output_static_value_fits($name, 'default', $default_value, $width)
                if defined $default_value;
        }

        my $entry = { name => $name, width => $width };
        $entry->{type} = $type if defined $type;
        $entry->{domain} = $domain if defined $domain;
        $entry->{reset_value} = $reset_value if defined $reset_value;
        $entry->{default_value} = $default_value if defined $default_value;
        if ($dir eq 'input')  { push @inputs,  $entry; }
        if ($dir eq 'output') { push @outputs, $entry; }
    }

    return { inputs => \@inputs, outputs => \@outputs };
}

sub _parse_interface_output_static_value($option, $port_name) {
    my $option_name = $option->[0];
    confess "Error: interface output '$port_name' $option_name requires '($option_name V)' with a non-negative integer literal\n"
        unless @$option == 2
            && defined($option->[1])
            && !ref($option->[1])
            && $option->[1] =~ /\A(?:0|[1-9][0-9]*)\z/;
    return $option->[1];
}

sub _validate_interface_output_static_value_fits($port_name, $option_name, $value, $width) {
    my $limit = Math::BigInt->new(2)->bpow($width + 0);
    my $actual = Math::BigInt->new($value);
    confess "Error: interface output '$port_name' $option_name value $value does not fit in $width bit(s)\n"
        if $actual->bcmp($limit) >= 0;
}

sub _parse_storage($self, $clause, $actor_name) {
    confess "Error: actor '$actor_name' storage requires '(storage (var name (width N)) ...)' entries\n"
        unless @$clause >= 2;

    my @entries;
    my %seen_logical_name;

    for my $entry (@{$clause}[1 .. $#$clause]) {
        confess "Error: actor '$actor_name' storage entries must be list forms\n"
            unless ref($entry) eq 'ARRAY' && @$entry;

        my ($authored_kind, $name, @options) = @$entry;
        my $kind = _normalize_storage_kind($authored_kind);
        confess "Error: actor '$actor_name' storage entry kind must be 'var', 'variable', or 'bank'\n"
            unless defined($kind);
        confess "Error: actor '$actor_name' storage '$kind' entry requires a scalar HDL identifier name\n"
            unless _is_hdl_identifier($name);
        confess "Error: actor '$actor_name' has duplicate storage name '$name'\n"
            if $seen_logical_name{$name}++;
        if ($kind eq 'var') {
            my $targets = FSM::Support::HDLInstanceIdentifierPolicy->reserved_target_languages($name);
            confess "Error: actor '$actor_name' storage variable '$name' is reserved in "
                . join(' and ', @$targets)
                . "; choose a non-keyword simple identifier\n"
                if @$targets;
        }

        my %parsed_options;
        for my $option (@options) {
            confess "Error: actor '$actor_name' storage '$name' options must be list forms\n"
                unless ref($option) eq 'ARRAY' && @$option;
            my $option_name = $option->[0];
            confess "Error: actor '$actor_name' storage '$name' option name must be scalar\n"
                unless defined($option_name) && !ref($option_name) && length($option_name);
            confess "Error: actor '$actor_name' storage '$name' has duplicate '$option_name' option\n"
                if $parsed_options{$option_name}++;

            if ($option_name eq 'width') {
                $parsed_options{width_value} = _parse_actor_storage_width_option(
                    $option,
                    "Error: actor '$actor_name' storage '$name' width",
                );
                next;
            }
            if ($option_name eq 'type') {
                confess "Error: actor '$actor_name' storage '$name' type requires '(type NAME)'\n"
                    unless @$option == 2 && _is_type_reference($option->[1]);
                $parsed_options{type_value} = $option->[1];
                next;
            }
            if ($option_name eq 'depth') {
                $parsed_options{depth_value} = _parse_actor_storage_depth_option(
                    $option,
                    "Error: actor '$actor_name' storage '$name' depth",
                );
                next;
            }
            if ($option_name eq 'domain') {
                $parsed_options{domain_value} = _parse_domain_option(
                    $option,
                    "Error: actor '$actor_name' storage '$name' domain",
                );
                next;
            }
            if ($option_name eq 'fields') {
                $parsed_options{fields_value} = _parse_actor_storage_fields_option(
                    $option,
                    "Error: actor '$actor_name' storage '$name' fields",
                );
                next;
            }
            if ($option_name eq 'access') {
                confess "Error: actor '$actor_name' storage '$name' access requires '(access TOKEN)' with one scalar token\n"
                    unless @$option == 2 && defined($option->[1]) && !ref($option->[1]);
                confess "Error: actor '$actor_name' storage '$name' has unknown access token '$option->[1]'; expected ro|rw|wo|w1c|w0c|rc|rs|warl|wpri|reserved\n"
                    unless _is_actor_storage_field_access($option->[1]);
                $parsed_options{access_value} = $option->[1];
                next;
            }
            # ISF-REGISTER-RESET-VALUES.4: `(reset V)` sets a storage var's hardware reset
            # assignment value — it does not establish a power-on initializer.
            if ($option_name eq 'reset') {
                confess "Error: actor '$actor_name' storage '$name' reset requires '(reset V)' with a non-negative integer literal\n"
                    unless @$option == 2 && defined($option->[1]) && !ref($option->[1]) && $option->[1] =~ /\A[0-9]+\z/;
                $parsed_options{reset_value} = $option->[1] + 0;
                next;
            }

            confess "Error: actor '$actor_name' storage '$name' has unsupported option '$option_name'\n";
        }

        my $width = $parsed_options{width_value};
        my $type = $parsed_options{type_value};
        confess "Error: actor '$actor_name' storage '$name' cannot specify both '(width ...)' and '(type ...)'\n"
            if defined($width) && defined($type);
        confess "Error: actor '$actor_name' storage '$name' requires '(width N)' or '(type NAME)'\n"
            unless defined($width) || defined($type);
        confess "Error: actor '$actor_name' storage '$name' fields require scalar '(var ...)' storage with '(width N)'; typed storage fields are not supported in this slice\n"
            if defined($parsed_options{fields_value}) && defined($type);
        confess "Error: actor '$actor_name' storage '$name' access requires scalar var or variable storage with '(width N)'; bank and typed storage access are not supported in this slice\n"
            if defined($parsed_options{access_value}) && ($kind ne 'var' || defined($type));

        my $reset = $parsed_options{reset_value};
        if (defined $reset) {
            confess "Error: actor '$actor_name' storage bank '$name' does not accept '(reset V)' (per-element bank reset values are not supported)\n"
                if $kind eq 'bank';
            # Width-fit check when the width is a literal (a param/constant width is checked
            # downstream once resolved).
            confess "Error: actor '$actor_name' storage var '$name' reset value $reset does not fit in $width bit(s)\n"
                if defined($width) && !ref($width) && $width =~ /\A[1-9][0-9]*\z/ && $reset >= (2 ** ($width + 0));
        }
        my @signals;
        if ($kind eq 'var') {
            confess "Error: actor '$actor_name' storage $kind '$name' does not accept '(depth N)'\n"
                if defined($parsed_options{depth_value});
            @signals = ({ name => $name, width => $width, (defined $reset ? (reset_value => $reset) : ()) });
        } else {
            confess "Error: actor '$actor_name' storage bank '$name' does not accept '(fields ...)'; field-structured storage is supported only on scalar var entries in this slice\n"
                if defined($parsed_options{fields_value});
            my $depth = $parsed_options{depth_value};
            confess "Error: actor '$actor_name' storage bank '$name' requires '(depth N)'\n"
                unless defined($depth);
            @signals = map { +{ name => "${name}_$_", width => $width, index => $_ } } 0 .. $depth - 1
                if !ref($depth) && $depth =~ /\A[1-9][0-9]*\z/;
        }

        push @entries, {
            kind    => $kind,
            name    => $name,
            width   => $width,
            signals => \@signals,
            ($kind eq 'bank' ? (depth => $parsed_options{depth_value}) : ()),
            (defined $reset ? (reset_value => $reset) : ()),
        };
        $entries[-1]{fields} = $parsed_options{fields_value}
            if defined($parsed_options{fields_value});
        $entries[-1]{access} = $parsed_options{access_value}
            if defined($parsed_options{access_value});
        $entries[-1]{type} = $type if defined $type;
        $entries[-1]{domain} = $parsed_options{domain_value}
            if defined($parsed_options{domain_value});
    }

    return \@entries;
}

sub _normalize_storage_kind {
    my ($kind) = @_;
    return undef unless defined($kind) && !ref($kind);
    return 'var' if $kind eq 'var' || $kind eq 'variable';
    return 'bank' if $kind eq 'bank';
    return undef;
}

sub _parse_actor_storage_depth_option {
    my ($option, $context) = @_;

    confess "$context requires '(depth positive_integer_or_actor_scalar_parameter_or_actor_constant_or_qualified_package_scalar_constant)'\n"
        unless ref($option) eq 'ARRAY'
            && @$option == 2
            && defined($option->[1])
            && !ref($option->[1])
            && ($option->[1] =~ /\A[1-9][0-9]*\z/
                || _is_hdl_identifier($option->[1])
                || _is_package_constant_reference_shape($option->[1]));

    return $option->[1] =~ /\A[1-9][0-9]*\z/
        ? 0 + $option->[1]
        : $option->[1];
}

sub _parse_actor_storage_width_option {
    my ($option, $context) = @_;

    confess "$context requires '(width positive_integer_or_actor_scalar_parameter_or_actor_constant_or_qualified_package_scalar_constant)'\n"
        unless ref($option) eq 'ARRAY'
            && @$option == 2
            && defined($option->[1])
            && !ref($option->[1])
            && ($option->[1] =~ /\A[1-9][0-9]*\z/
                || _is_hdl_identifier($option->[1])
                || _is_package_constant_reference_shape($option->[1]));

    return $option->[1] =~ /\A[1-9][0-9]*\z/
        ? 0 + $option->[1]
        : $option->[1];
}

sub _parse_actor_storage_fields_option {
    my ($option, $context) = @_;

    confess "$context requires '(fields (field NAME (bits HI LO) ...) ...)'\n"
        unless ref($option) eq 'ARRAY' && @$option >= 2;

    my @fields;
    my %seen_field;
    for my $field (@{$option}[1 .. $#$option]) {
        confess "$context entries must be '(field NAME (bits HI LO) ...)'\n"
            unless ref($field) eq 'ARRAY' && @$field >= 3;
        my ($keyword, $name, @items) = @$field;
        confess "$context entries must start with 'field'\n"
            unless defined($keyword) && !ref($keyword) && $keyword eq 'field';
        confess "$context field name must be a scalar HDL identifier\n"
            unless _is_hdl_identifier($name);
        confess "$context has duplicate field name '$name'\n"
            if $seen_field{$name}++;

        my %seen_options;
        my %entry = (name => $name);
        for my $item (@items) {
            confess "$context field '$name' options must be list forms\n"
                unless ref($item) eq 'ARRAY' && @$item;
            my $option_name = $item->[0];
            confess "$context field '$name' option name must be scalar\n"
                unless defined($option_name) && !ref($option_name) && length($option_name);
            confess "$context field '$name' has duplicate '$option_name' option\n"
                if $seen_options{$option_name}++;

            if ($option_name eq 'bits') {
                confess "$context field '$name' bits requires '(bits HI LO)' with non-negative integer literals and HI >= LO\n"
                    unless @$item == 3
                        && defined($item->[1]) && !ref($item->[1]) && $item->[1] =~ /\A[0-9]+\z/
                        && defined($item->[2]) && !ref($item->[2]) && $item->[2] =~ /\A[0-9]+\z/
                        && ($item->[1] + 0) >= ($item->[2] + 0);
                $entry{msb} = $item->[1] + 0;
                $entry{lsb} = $item->[2] + 0;
                next;
            }
            if ($option_name eq 'access') {
                confess "$context field '$name' access requires '(access ro|rw|wo|w1c|w0c|rc|rs|warl|wpri|reserved)'\n"
                    unless @$item == 2
                        && defined($item->[1])
                        && !ref($item->[1])
                        && _is_actor_storage_field_access($item->[1]);
                $entry{access} = $item->[1];
                next;
            }
            if ($option_name eq 'reset') {
                confess "$context field '$name' reset requires '(reset V)' with a non-negative integer literal\n"
                    unless @$item == 2
                        && defined($item->[1])
                        && !ref($item->[1])
                        && $item->[1] =~ /\A[0-9]+\z/;
                $entry{reset} = $item->[1] + 0;
                next;
            }
            if ($option_name eq 'enum') {
                $entry{enum} = _parse_actor_storage_field_enum_option($item, "$context field '$name' enum");
                next;
            }

            confess "$context field '$name' has unsupported option '$option_name'\n";
        }

        confess "$context field '$name' requires '(bits HI LO)'\n"
            unless exists($entry{msb}) && exists($entry{lsb});
        $entry{width} = $entry{msb} - $entry{lsb} + 1;
        push @fields, \%entry;
    }

    return \@fields;
}

sub _parse_actor_storage_field_enum_option {
    my ($option, $context) = @_;

    confess "$context requires '(enum (NAME VALUE) ...)'\n"
        unless ref($option) eq 'ARRAY' && @$option >= 2;

    my @members;
    my %seen_name;
    my %seen_value;
    for my $member (@{$option}[1 .. $#$option]) {
        confess "$context entries must be '(NAME VALUE)'\n"
            unless ref($member) eq 'ARRAY' && @$member == 2;
        my ($name, $value) = @$member;
        confess "$context member name must be a scalar HDL identifier\n"
            unless _is_hdl_identifier($name);
        confess "$context member '$name' value must be a non-negative integer literal\n"
            unless defined($value) && !ref($value) && $value =~ /\A[0-9]+\z/;
        confess "$context has duplicate member name '$name'\n"
            if $seen_name{$name}++;
        confess "$context has duplicate member value '$value'\n"
            if $seen_value{$value + 0}++;
        push @members, { name => $name, value => $value + 0 };
    }

    return \@members;
}

sub _is_actor_storage_field_access {
    my ($value) = @_;
    return 0 unless defined($value) && !ref($value);
    return {
        ro       => 1,
        rw       => 1,
        wo       => 1,
        w1c      => 1,
        w0c      => 1,
        rc       => 1,
        rs       => 1,
        warl     => 1,
        wpri     => 1,
        reserved => 1,
    }->{$value} ? 1 : 0;
}

sub _parse_transaction_port_width_option {
    my ($option, $context) = @_;

    confess "$context requires '(width positive_integer_or_same_transaction_scalar_parameter_or_actor_scalar_parameter_or_actor_constant_or_qualified_package_scalar_constant)'\n"
        unless ref($option) eq 'ARRAY'
            && @$option == 2
            && defined($option->[1])
            && !ref($option->[1])
            && ($option->[1] =~ /\A[1-9][0-9]*\z/
                || _is_hdl_identifier($option->[1])
                || _is_package_constant_reference_shape($option->[1]));

    return $option->[1] =~ /\A[1-9][0-9]*\z/
        ? 0 + $option->[1]
        : $option->[1];
}

sub _parse_domain_option {
    my ($option, $context) = @_;

    confess "$context requires '(domain name)'\n"
        unless ref($option) eq 'ARRAY'
            && @$option == 2
            && defined($option->[0])
            && !ref($option->[0])
            && $option->[0] eq 'domain'
            && _is_hdl_identifier($option->[1]);

    return $option->[1];
}

sub _parse_handshake($self, $clause) {
    confess "Error: (handshake ...) requires '(handshake name (valid signal) (ready signal))'\n"
        unless @$clause >= 3 && @$clause <= 4;
    my $name = $clause->[1];
    confess "Error: (handshake ...) requires a scalar name\n"
        unless defined($name) && !ref($name) && length($name);

    my %seen;
    for my $i (2 .. $#$clause) {
        my $pair = $clause->[$i];
        confess "Error: handshake '$name' properties must be '(valid signal)' or '(ready signal)'\n"
            unless ref($pair) eq 'ARRAY'
                && @$pair == 2
                && defined($pair->[0])
                && !ref($pair->[0])
                && ($pair->[0] eq 'valid' || $pair->[0] eq 'ready')
                && defined($pair->[1])
                && !ref($pair->[1])
                && length($pair->[1]);

        my $key = $pair->[0];
        confess "Error: duplicate handshake '$name' property '$key'\n" if $seen{$key}++;
    }

    confess "Error: handshake '$name' requires exactly one '(valid signal)' and one '(ready signal)' property; "
        . "legacy handshakes are ignored compatibility input, use '(on ...)' activation "
        . "or transaction '(stage ...)' for ready/valid behavior\n"
        unless $seen{valid} && $seen{ready};

    return $name;
}

sub _parse_transaction($self, $clause) {
    confess "Error: (transaction ...) requires a name\n" unless @$clause >= 2;
    my $name = $clause->[1];
    confess "Error: (transaction ...) requires a scalar name\n"
        unless defined($name) && !ref($name) && length($name);
    my @clauses;
    my $ports = { inputs => [], outputs => [] };
    my $saw_ports;
    my $domain;

    for my $i (2 .. $#$clause) {
        my $body_clause = $clause->[$i];
        if (ref($body_clause) eq 'ARRAY'
            && @$body_clause
            && defined($body_clause->[0])
            && !ref($body_clause->[0])
            && $body_clause->[0] eq 'ports')
        {
            confess "Error: transaction '$name' accepts only one '(ports ...)' clause\n"
                if $saw_ports++;
            $ports = $self->_parse_transaction_ports($body_clause, $name);
            next;
        }
        if (ref($body_clause) eq 'ARRAY'
            && @$body_clause
            && defined($body_clause->[0])
            && !ref($body_clause->[0])
            && $body_clause->[0] eq 'domain')
        {
            confess "Error: transaction '$name' accepts only one '(domain ...)' clause\n"
                if defined $domain;
            $domain = _parse_domain_option(
                $body_clause,
                "Error: transaction '$name' domain",
            );
            next;
        }

        push @clauses, $body_clause;
    }
    $self->_validate_transaction_phase_stage_clauses(\@clauses);

    my %transaction = (name => $name, ports => $ports, clauses => \@clauses);
    $transaction{domain} = $domain if defined $domain;
    return \%transaction;
}

sub _parse_transaction_ports($self, $clause, $transaction_name) {
    confess "Error: transaction '$transaction_name' ports require '(ports (input name [(width N)]) ...)'\n"
        unless @$clause >= 2;

    my @inputs;
    my @outputs;
    my %seen_names;

    for my $entry (@{$clause}[1 .. $#$clause]) {
        confess "Error: transaction '$transaction_name' port entries must be list forms\n"
            unless ref($entry) eq 'ARRAY' && @$entry >= 2;

        my ($direction, $name, @options) = @$entry;
        confess "Error: transaction '$transaction_name' port direction must be input or output\n"
            unless defined($direction) && !ref($direction) && ($direction eq 'input' || $direction eq 'output');
        confess "Error: transaction '$transaction_name' port requires a scalar HDL identifier name\n"
            unless _is_hdl_identifier($name);
        confess "Error: transaction '$transaction_name' has duplicate port '$name'\n"
            if $seen_names{$name}++;

        my $width = 1;
        my $type;
        my %seen_options;
        for my $option (@options) {
            confess "Error: transaction '$transaction_name' port '$name' options must be list forms\n"
                unless ref($option) eq 'ARRAY' && @$option;
            my $option_name = $option->[0];
            confess "Error: transaction '$transaction_name' port '$name' option name must be scalar\n"
                unless defined($option_name) && !ref($option_name) && length($option_name);
            confess "Error: transaction '$transaction_name' port '$name' has duplicate '$option_name' option\n"
                if $seen_options{$option_name}++;

            if ($option_name eq 'width') {
                $width = _parse_transaction_port_width_option(
                    $option,
                    "Error: transaction '$transaction_name' port '$name' width",
                );
                next;
            }
            if ($option_name eq 'type') {
                confess "Error: transaction '$transaction_name' port '$name' type requires '(type NAME)'\n"
                    unless @$option == 2 && _is_type_reference($option->[1]);
                $type = $option->[1];
                next;
            }

            confess "Error: transaction '$transaction_name' port '$name' has unsupported option '$option_name'\n";
        }
        confess "Error: transaction '$transaction_name' port '$name' cannot specify both '(width ...)' and '(type ...)'\n"
            if defined($type) && exists($seen_options{width});

        my $parsed = { name => $name, width => $width };
        $parsed->{type} = $type if defined $type;
        if ($direction eq 'input') {
            push @inputs, $parsed;
        } else {
            push @outputs, $parsed;
        }
    }

    return { inputs => \@inputs, outputs => \@outputs };
}

sub _parse_rule($self, $clause) {
    confess "Error: (rule ...) requires a name\n" unless @$clause >= 2;
    my $name = $clause->[1];
    confess "Error: (rule ...) requires a scalar name\n"
        unless defined($name) && !ref($name) && length($name);
    my $when;
    my @actions;
    my @body = @{$clause}[2 .. $#$clause];
    my $domain;
    my @domain_filtered_body;

    for my $elem (@body) {
        if (ref($elem) eq 'ARRAY'
            && @$elem
            && defined($elem->[0])
            && !ref($elem->[0])
            && $elem->[0] eq 'domain')
        {
            confess "Error: rule '$name' accepts only one '(domain ...)' clause\n"
                if defined $domain;
            $domain = _parse_domain_option(
                $elem,
                "Error: rule '$name' domain",
            );
            next;
        }
        push @domain_filtered_body, $elem;
    }
    @body = @domain_filtered_body;

    if (@body && defined($body[0]) && !ref($body[0])) {
        $when = $self->_parse_rule_when(['when', shift @body], $name);
    } elsif (@body && _is_rule_guard_shorthand_expr($body[0])) {
        $when = $self->_parse_rule_when(['when', shift @body], $name);
    }

    for my $elem (@body) {
        if (ref($elem) eq 'ARRAY' && defined($elem->[0]) && !ref($elem->[0]) && $elem->[0] eq 'when') {
            confess "Error: rule '$name' accepts only one guard condition\n"
                if defined $when;
            $when = $self->_parse_rule_when($elem, $name);
        } else {
            $self->_parse_rule_action($elem, $name);
            push @actions, $elem;
        }
    }

    my %rule = (name => $name, when => $when, actions => \@actions);
    $rule{domain} = $domain if defined $domain;
    return \%rule;
}

sub _parse_rule_when($self, $clause, $rule_name) {
    confess "Error: rule '$rule_name' guard requires exactly one condition\n"
        unless ref($clause) eq 'ARRAY'
            && @$clause == 2
            && defined($clause->[1]);

    my $condition = $clause->[1];
    if (!ref($condition)) {
        confess "Error: rule '$rule_name' guard condition must be a non-empty scalar or list expression\n"
            unless length($condition);
        return ['when', $condition];
    }

    $self->_validate_rule_guard_expr($condition, $rule_name);
    return ['when', _clone_isf_value($condition)];
}

sub _is_rule_guard_shorthand_expr {
    my ($expr) = @_;
    return 0 unless ref($expr) eq 'ARRAY' && @$expr;
    my $head = $expr->[0];
    return defined($head)
        && !ref($head)
        && $RULE_GUARD_SHORTHAND_EXPR_HEADS{$head};
}

sub _validate_rule_guard_expr($self, $expr, $rule_name) {
    confess "Error: rule '$rule_name' guard expression must be a non-empty list\n"
        unless ref($expr) eq 'ARRAY' && @$expr;

    my $head = $expr->[0];
    confess "Error: rule '$rule_name' guard expression heads must be scalar\n"
        unless defined($head) && !ref($head) && length($head);

    confess "Error: rule '$rule_name' guard expression cannot use control-flow form '$head'\n"
        if $RULE_ASSIGNMENT_FORBIDDEN_EXPR_HEADS{$head};

    for my $operand (@{$expr}[1 .. $#$expr]) {
        confess "Error: rule '$rule_name' guard expression operands must be defined\n"
            unless defined($operand);
        $self->_validate_rule_guard_expr($operand, $rule_name)
            if ref($operand);
    }

    return 1;
}

sub _parse_rule_priority($self, $clause, $rule_name) {
    confess "Error: rule '$rule_name' priority requires '(priority over other_rule)'\n"
        unless ref($clause) eq 'ARRAY'
            && @$clause == 3
            && defined($clause->[1])
            && !ref($clause->[1])
            && $clause->[1] eq 'over'
            && defined($clause->[2])
            && !ref($clause->[2])
            && length($clause->[2]);

    return 1;
}

sub _parse_rule_action($self, $action, $rule_name) {
    confess "Error: rule '$rule_name' actions must be list forms\n"
        unless ref($action) eq 'ARRAY' && @$action;

    my $keyword = $action->[0];
    confess "Error: rule '$rule_name' action heads must be scalar\n"
        unless defined($keyword) && !ref($keyword) && length($keyword);

    if ($keyword eq 'trigger') {
        confess "Error: rule '$rule_name' trigger requires '(trigger transaction [(params (NAME value) ...)] [(bind ...)])'\n"
            unless @$action >= 2
                && defined($action->[1])
                && !ref($action->[1])
                && length($action->[1]);

        my %seen_subclause;
        for my $subclause (@{$action}[2 .. $#$action]) {
            confess "Error: rule '$rule_name' trigger '$action->[1]' subclauses must be '(params ...)' or '(bind ...)'\n"
                unless ref($subclause) eq 'ARRAY'
                    && @$subclause
                    && defined($subclause->[0])
                    && !ref($subclause->[0])
                    && length($subclause->[0]);
            my $head = $subclause->[0];
            confess "Error: rule '$rule_name' trigger '$action->[1]' has duplicate '$head' subclause\n"
                if $seen_subclause{$head}++;
            if ($head eq 'params') {
                $self->_parse_rule_trigger_params($subclause, $rule_name, $action->[1]);
                next;
            }
            if ($head eq 'bind') {
                $self->_parse_rule_trigger_bind($subclause, $rule_name, $action->[1]);
                next;
            }
            confess "Error: rule '$rule_name' trigger '$action->[1]' has unsupported '$head' subclause\n";
        }
        return 1;
    }
    if ($keyword eq 'priority') {
        return $self->_parse_rule_priority($action, $rule_name);
    }
    if ($keyword eq 'pulse') {
        confess "Error: rule '$rule_name' pulse action requires '(pulse target)'\n"
            unless @$action == 2
                && _is_hdl_identifier($action->[1]);
        return 1;
    }
    if ($keyword eq 'store') {
        confess "Error: rule '$rule_name' store action requires '(store <bank-name> <index> <value>)'\n"
            unless @$action == 4
                && _is_hdl_identifier($action->[1])
                && defined($action->[2])
                && !ref($action->[2])
                && length($action->[2])
                && defined($action->[3]);
        $self->_validate_rule_assignment_expr($action->[3], $rule_name);
        return 1;
    }
    if ($keyword eq 'load') {
        confess "Error: rule '$rule_name' load action requires '(load <bank-name> <index> as <target>)'\n"
            unless @$action == 5
                && _is_hdl_identifier($action->[1])
                && defined($action->[2])
                && !ref($action->[2])
                && length($action->[2])
                && defined($action->[3])
                && !ref($action->[3])
                && $action->[3] eq 'as'
                && _is_hdl_identifier($action->[4]);
        return 1;
    }
    if ($keyword eq 'set') {
        confess "Error: rule '$rule_name' set action requires '(set port expr)'\n"
            unless @$action == 3
                && defined($action->[1])
                && !ref($action->[1])
                && length($action->[1])
                && defined($action->[2]);
        $self->_validate_rule_assignment_expr($action->[2], $rule_name);
        return 1;
    }
    if ($RULE_ASSIGNMENT_FORBIDDEN_EXPR_HEADS{$keyword}) {
        confess "Error: rule '$rule_name' action cannot use control-flow form '$keyword'\n";
    }

    confess "Error: rule '$rule_name' assignment actions require '(port expr)'\n"
        unless @$action == 2
            && defined($action->[1]);

    $self->_validate_rule_assignment_expr($action->[1], $rule_name);

    return 1;
}

sub _parse_rule_trigger_params($self, $clause, $rule_name, $transaction_name) {
    confess "Error: rule '$rule_name' trigger '$transaction_name' params require '(params (NAME value) ...)'\n"
        unless ref($clause) eq 'ARRAY'
            && @$clause >= 2
            && defined($clause->[0])
            && !ref($clause->[0])
            && $clause->[0] eq 'params';

    my %seen;
    for my $entry (@{$clause}[1 .. $#$clause]) {
        confess "Error: rule '$rule_name' trigger '$transaction_name' params entries require '(NAME value)'\n"
            unless ref($entry) eq 'ARRAY' && @$entry == 2;
        my ($name, $value) = @$entry;
        confess "Error: rule '$rule_name' trigger '$transaction_name' parameter override names must be scalar HDL identifiers\n"
            unless _is_hdl_identifier($name);
        confess "Error: rule '$rule_name' trigger '$transaction_name' has duplicate parameter override '$name'\n"
            if $seen{$name}++;
        confess "Error: rule '$rule_name' trigger '$transaction_name' parameter '$name' value must be defined\n"
            unless defined $value;
    }

    return 1;
}

sub _parse_rule_trigger_bind($self, $clause, $rule_name, $transaction_name) {
    confess "Error: rule '$rule_name' trigger '$transaction_name' bind requires '(bind (input port expr) ...)'\n"
        unless ref($clause) eq 'ARRAY'
            && @$clause >= 2
            && defined($clause->[0])
            && !ref($clause->[0])
            && $clause->[0] eq 'bind';

    my %seen;
    for my $entry (@{$clause}[1 .. $#$clause]) {
        confess "Error: rule '$rule_name' trigger '$transaction_name' bind entries must be list forms\n"
            unless ref($entry) eq 'ARRAY' && (@$entry == 3 || @$entry == 4);
        my ($role, $port, $actor_endpoint, $timing_clause) = @$entry;
        confess "Error: rule '$rule_name' trigger '$transaction_name' bind role must be input or output\n"
            unless defined($role) && !ref($role) && ($role eq 'input' || $role eq 'output');
        confess "Error: rule '$rule_name' trigger '$transaction_name' bind port must be a scalar HDL identifier\n"
            unless _is_hdl_identifier($port);
        if (defined $timing_clause) {
            confess "Error: rule '$rule_name' trigger '$transaction_name' output bind timing selection is supported only on input bindings\n"
                if $role eq 'output';
            confess "Error: rule '$rule_name' trigger '$transaction_name' input bind timing must be '(timing snapshot)' or '(timing live)'\n"
                unless ref($timing_clause) eq 'ARRAY'
                    && @$timing_clause == 2
                    && defined($timing_clause->[0])
                    && !ref($timing_clause->[0])
                    && $timing_clause->[0] eq 'timing'
                    && defined($timing_clause->[1])
                    && !ref($timing_clause->[1])
                    && ($timing_clause->[1] eq 'snapshot' || $timing_clause->[1] eq 'live');
        }
        if ($role eq 'output') {
            confess "Error: rule '$rule_name' trigger '$transaction_name' output bind target must be a scalar HDL identifier\n"
                unless _is_hdl_identifier($actor_endpoint);
        } else {
            confess "Error: rule '$rule_name' trigger '$transaction_name' input bind expression must be a scalar signal, numeric/exact-width literal, or non-empty list expression\n"
                unless _is_activation_input_binding_expr_shape($actor_endpoint);
        }
        confess "Error: rule '$rule_name' trigger '$transaction_name' has duplicate binding for port '$port'\n"
            if $seen{$port}++;
    }

    return 1;
}

sub _validate_rule_assignment_expr($self, $expr, $rule_name) {
    return 1 unless ref($expr);

    confess "Error: rule '$rule_name' assignment RHS expression must be a non-empty list\n"
        unless ref($expr) eq 'ARRAY' && @$expr;

    my $head = $expr->[0];
    confess "Error: rule '$rule_name' assignment expression heads must be scalar\n"
        unless defined($head) && !ref($head) && length($head);

    confess "Error: rule '$rule_name' assignment RHS cannot use control-flow form '$head'\n"
        if $RULE_ASSIGNMENT_FORBIDDEN_EXPR_HEADS{$head};

    for my $operand (@{$expr}[1 .. $#$expr]) {
        $self->_validate_rule_assignment_expr($operand, $rule_name)
            if ref($operand);
    }

    return 1;
}

sub _validate_rule_trigger_targets($self, $actor) {
    my $actor_name = $actor->{actor_name};
    my %transaction_names = map { $_->{name} => 1 } @{$actor->{transactions} || []};

    for my $rule (@{$actor->{rules} || []}) {
        my $rule_name = $rule->{name};
        for my $action (@{$rule->{actions} || []}) {
            next unless ref($action) eq 'ARRAY' && @$action;
            next unless defined($action->[0]) && !ref($action->[0]) && $action->[0] eq 'trigger';

            my $target = $action->[1];
            confess "Error: rule '$rule_name' triggers unknown transaction '$target' in actor '$actor_name'\n"
                unless defined($target)
                    && !ref($target)
                    && $transaction_names{$target};
        }
    }

    return 1;
}

sub _validate_rule_pulse_targets($self, $actor) {
    my $actor_name = $actor->{actor_name} // 'unknown';
    my %valid_targets = map { $_->{name} => 'output' } @{$actor->{interface}{outputs} || []};

    for my $entry (@{$actor->{storage} || []}) {
        next unless ($entry->{kind} // '') eq 'var';
        for my $signal (@{$entry->{signals} || []}) {
            $valid_targets{$signal->{name}} = 'storage'
                if defined($signal->{name}) && !ref($signal->{name});
        }
    }

    for my $rule (@{$actor->{rules} || []}) {
        my $rule_name = $rule->{name} // 'unknown';
        for my $action (@{$rule->{actions} || []}) {
            next unless ref($action) eq 'ARRAY' && @$action >= 2;
            next unless defined($action->[0]) && !ref($action->[0]) && $action->[0] eq 'pulse';

            my $target = $action->[1];
            next if defined($target) && !ref($target) && $valid_targets{$target};
            confess "Error: rule '$rule_name' pulse target '$target' in actor '$actor_name' must name a scalar output or storage var\n";
        }
    }

    return 1;
}

sub _validate_rule_priority_targets($self, $actor) {
    my $actor_name = $actor->{actor_name};
    my %rule_names = map { $_->{name} => 1 } @{$actor->{rules} || []};

    for my $rule (@{$actor->{rules} || []}) {
        my $rule_name = $rule->{name};
        for my $action (@{$rule->{actions} || []}) {
            next unless ref($action) eq 'ARRAY' && @$action;
            next unless defined($action->[0]) && !ref($action->[0]) && $action->[0] eq 'priority';

            my $target = $action->[2];
            confess "Error: rule '$rule_name' priority targets unknown rule '$target' in actor '$actor_name'\n"
                unless defined($target)
                    && !ref($target)
                    && $rule_names{$target};
        }
    }

    return 1;
}

sub _validate_actor_priority_targets($self, $actor) {
    my $actor_name = $actor->{actor_name};
    my %names = (
        map({ $_->{name} => 1 } @{$actor->{transactions} || []}),
        map({ $_->{name} => 1 } @{$actor->{rules} || []}),
    );

    for my $priority (@{$actor->{priorities} || []}) {
        for my $target ($priority->[0], $priority->[2]) {
            confess "Error: priority target '$target' is not a declared transaction or rule in actor '$actor_name'\n"
                unless defined($target)
                    && !ref($target)
                    && $names{$target};
        }
    }

    return 1;
}

sub _parse_resources($self, $clause) {
    my @resources;
    my %seen;

    for my $i (1 .. $#$clause) {
        my $res = $clause->[$i];
        confess "Error: resource must be a list\n" unless ref($res) eq 'ARRAY';
        my ($kw, $name, @forms) = @$res;
        confess "Error: resource entries require '(resource name (arbiter $RESOURCE_ARBITER_SYNTAX) [(kind kind)] [(users rule...)] [(members output...)])'\n"
            unless @$res >= 3
                && defined($kw)
                && !ref($kw)
                && $kw eq 'resource'
                && defined($name)
                && !ref($name)
                && length($name);

        confess "Error: duplicate resource '$name'\n" if $seen{$name}++;

        my %seen_subclause;
        my ($arbiter, $kind);
        my @users;
        my @members;
        my %seen_users;
        my %seen_members;

        for my $form (@forms) {
            confess "Error: resource '$name' subclauses must be list forms\n"
                unless ref($form) eq 'ARRAY' && @$form;
            my $head = $form->[0];
            confess "Error: resource '$name' subclause heads must be scalar\n"
                unless defined($head) && !ref($head) && length($head);
            confess "Error: duplicate resource '$name' subclause '$head'\n"
                if $seen_subclause{$head}++;

            if ($head eq 'arbiter') {
                confess "Error: resource '$name' arbiter requires '(arbiter $RESOURCE_ARBITER_SYNTAX)'\n"
                    unless @$form == 2
                        && defined($form->[1])
                        && !ref($form->[1])
                        && $RESOURCE_ARBITERS{$form->[1]};
                $arbiter = $form->[1];
                next;
            }

            if ($head eq 'kind') {
                confess "Error: resource '$name' kind requires '(kind $RESOURCE_KIND_SYNTAX)'\n"
                    unless @$form == 2
                        && defined($form->[1])
                        && !ref($form->[1])
                        && $RESOURCE_KINDS{$form->[1]};
                $kind = $form->[1];
                next;
            }

            if ($head eq 'users') {
                confess "Error: resource '$name' users requires '(users rule...)'\n"
                    unless @$form >= 2;
                for my $u (@{$form}[1 .. $#$form]) {
                    confess "Error: resource '$name' users must be scalar names\n"
                        unless defined($u) && !ref($u) && length($u);
                    confess "Error: duplicate resource '$name' user '$u'\n"
                        if $seen_users{$u}++;
                    push @users, $u;
                }
                next;
            }

            if ($head eq 'members') {
                confess "Error: resource '$name' members requires '(members name...)'\n"
                    unless @$form >= 2;
                for my $member (@{$form}[1 .. $#$form]) {
                    confess "Error: resource '$name' members must be scalar names\n"
                        unless defined($member) && !ref($member) && length($member);
                    confess "Error: duplicate resource '$name' member '$member'\n"
                        if $seen_members{$member}++;
                    push @members, $member;
                }
                next;
            }

            confess "Error: resource '$name' has unsupported subclause '$head'\n";
        }

        confess "Error: resource '$name' requires '(arbiter $RESOURCE_ARBITER_SYNTAX)'\n"
            unless defined($arbiter);
        confess "Error: resource '$name' with users requires an enforced '(kind ...)' such as '(kind rule_slot)', '(kind output_bundle)', '(kind transaction_start)', or '(kind storage_port)'\n"
            if @users && !defined($kind);
        confess "Error: resource '$name' members are supported only with '(kind output_bundle)' or '(kind storage_port)'\n"
            if @members && (($kind // '') ne 'output_bundle') && (($kind // '') ne 'storage_port');
        confess "Error: storage_port resource '$name' with users requires explicit '(members storage_signal...)'\n"
            if @users && (($kind // '') eq 'storage_port') && !@members;

        my %resource = (name => $name, arbiter => $arbiter);
        $resource{kind} = $kind if defined($kind);
        $resource{users} = \@users if @users;
        $resource{members} = \@members if @members;
        push @resources, \%resource;
    }
    return \@resources;
}

sub _validate_resource_user_targets($self, $actor) {
    my $actor_name = $actor->{actor_name};
    my %rule_names = map { $_->{name} => 1 } @{$actor->{rules} || []};
    my %transaction_names = map { $_->{name} => 1 } @{$actor->{transactions} || []};
    my %output_bundle_member_names = map { $_->{name} => 1 } @{$actor->{interface}{outputs} || []};
    my %storage_member_names;
    for my $entry (@{$actor->{storage} || []}) {
        for my $signal (@{$entry->{signals} || []}) {
            $output_bundle_member_names{$signal->{name}} = 1
                if defined($signal->{name}) && !ref($signal->{name});
            $storage_member_names{$signal->{name}} = 1
                if defined($signal->{name}) && !ref($signal->{name});
        }
    }

    for my $resource (@{$actor->{resources} || []}) {
        my $kind = $resource->{kind} // '';
        if (@{$resource->{members} || []}) {
            confess "Error: resource '$resource->{name}' members are supported only with '(kind output_bundle)' or '(kind storage_port)' in actor '$actor_name'\n"
                unless $kind eq 'output_bundle' || $kind eq 'storage_port';
            for my $member (@{$resource->{members} || []}) {
                my $ok = defined($member) && !ref($member)
                    && (
                        ($kind eq 'output_bundle' && $output_bundle_member_names{$member})
                        || ($kind eq 'storage_port' && $storage_member_names{$member})
                    );
                my $expected = $kind eq 'storage_port'
                    ? 'a declared actor-owned storage signal'
                    : 'a declared actor output or actor-owned storage signal';
                confess "Error: resource '$resource->{name}' member '$member' is not $expected in actor '$actor_name'\n"
                    unless $ok;
            }
        }

        if ($kind eq 'transaction_start' && @{$resource->{users} || []}) {
            my $transaction = $resource->{name};
            confess "Error: transaction_start resource '$transaction' is not a declared transaction in actor '$actor_name'\n"
                unless defined($transaction)
                    && !ref($transaction)
                    && $transaction_names{$transaction};
        }

        next unless $kind eq 'rule_slot' || $kind eq 'output_bundle' || $kind eq 'transaction_start' || $kind eq 'storage_port';
        for my $user (@{$resource->{users} || []}) {
            confess "Error: resource '$resource->{name}' user '$user' is not a declared rule in actor '$actor_name'\n"
                unless defined($user)
                    && !ref($user)
                    && $rule_names{$user};
        }
    }

    return 1;
}

sub _validate_storage_actor_names($self, $actor) {
    my $actor_name = $actor->{actor_name};
    my %ports = (
        map({ $_->{name} => 'input' } @{$actor->{interface}{inputs} || []}),
        map({ $_->{name} => 'output' } @{$actor->{interface}{outputs} || []}),
    );

    my %reserved;
    $reserved{$actor->{clock}} = 'clock'
        if defined($actor->{clock}) && length($actor->{clock});
    $reserved{$actor->{reset}{name}} = 'reset'
        if ref($actor->{reset}) eq 'HASH'
            && defined($actor->{reset}{name})
            && length($actor->{reset}{name});
    if (ref($actor->{clock_domains}) eq 'HASH') {
        for my $domain (@{$actor->{clock_domains}{domains} || []}) {
            $reserved{$domain->{clock}} = "clock-domain '$domain->{name}' clock"
                if defined($domain->{clock}) && length($domain->{clock});
            $reserved{$domain->{reset}{name}} = "clock-domain '$domain->{name}' reset"
                if ref($domain->{reset}) eq 'HASH'
                    && defined($domain->{reset}{name})
                    && length($domain->{reset}{name});
        }
    }
    for my $crossing (@{$actor->{crossings} || []}) {
        my $name = $crossing->{name};
        $reserved{$crossing->{from}{signal}} = "crossing event '$name' request"
            if ref($crossing->{from}) eq 'HASH'
                && defined($crossing->{from}{signal})
                && length($crossing->{from}{signal});
        $reserved{$crossing->{to}{signal}} = "crossing event '$name' pulse"
            if ref($crossing->{to}) eq 'HASH'
                && defined($crossing->{to}{signal})
                && length($crossing->{to}{signal});
        $reserved{$crossing->{ready}{signal}} = "crossing event '$name' ready"
            if ref($crossing->{ready}) eq 'HASH'
                && defined($crossing->{ready}{signal})
                && length($crossing->{ready}{signal});
    }
    $reserved{can_accept} = 'scheduler-generated signal';

    for my $entry (@{$actor->{storage} || []}) {
        for my $signal (@{$entry->{signals} || []}) {
            my $name = $signal->{name};
            confess "Error: actor '$actor_name' storage signal '$name' conflicts with interface $ports{$name} port '$name'\n"
                if exists $ports{$name};
            confess "Error: actor '$actor_name' storage signal '$name' conflicts with $reserved{$name} '$name'\n"
                if exists $reserved{$name};
        }
    }

    return 1;
}

sub _parse_priority($self, $clause) {
    confess "Error: (priority ...) requires '(priority lhs over rhs)'\n"
        unless @$clause == 4
            && defined($clause->[1])
            && !ref($clause->[1])
            && length($clause->[1])
            && defined($clause->[2])
            && !ref($clause->[2])
            && $clause->[2] eq 'over'
            && defined($clause->[3])
            && !ref($clause->[3])
            && length($clause->[3]);

    return [ @{$clause}[1 .. $#$clause] ];
}

sub _parse_drive_def($self, $clause, $drives, $actor) {
    confess "Error: (drive ...) requires a name\n" unless @$clause >= 2;
    my $spec = $clause->[1];
    my ($name, @params);
    if (ref($spec) eq 'ARRAY') {
        # Parameterized: (drive (name p1 p2) body...)
        $name = $spec->[0];
        @params = @{$spec}[1 .. $#$spec];
    } else {
        # Simple: (drive name body...)
        $name = $spec;
        @params = ();
    }
    confess "Error: (drive ...) requires a scalar name\n"
        unless defined($name) && !ref($name) && length($name);
    my %seen_params;
    for my $param (@params) {
        confess "Error: drive '$name' parameter names must be scalar\n"
            unless defined($param) && !ref($param) && length($param);
        confess "Error: duplicate drive '$name' parameter '$param'\n"
            if $seen_params{$param}++;
    }
    confess "Error: duplicate drive '$name'\n" if exists $drives->{$name};
    my %actor_instances = map { $_->{name} => 1 }
        @{(($actor || {})->{actor_network} || {})->{instances} || []};
    my @body = @{$clause}[2 .. $#$clause];
    for my $entry (@body) {
        confess "Error: drive '$name' body entries must be list forms\n"
            unless ref($entry) eq 'ARRAY' && @$entry;
        my $deferred_atl_sink_expression_candidate =
            ref($entry->[0]) && _contains_dotted_token($entry->[0]);
        confess "Error: drive '$name' body ATL scalar actor-to-actor data movement sink expressions remain deferred\n"
            if $deferred_atl_sink_expression_candidate
                && _contains_atl_data_movement_endpoint_token($entry->[0], \%actor_instances);
        confess "Error: drive '$name' body entry heads must be scalar\n"
            unless (defined($entry->[0]) && !ref($entry->[0]) && length($entry->[0]))
                || $deferred_atl_sink_expression_candidate;
        confess "Error: drive '$name' body assignments require '(port value)'\n"
            unless @$entry == 2
                && defined($entry->[1])
                && (!ref($entry->[1]) || ref($entry->[1]) eq 'ARRAY');
    }
    $drives->{$name} = { body => \@body, params => \@params };
}

sub _parse_actor_network_instance($self, $clause, $actor_name) {
    confess "Error: actor '$actor_name' static actor instance requires '(instance name of actor_type)'\n"
        unless @$clause == 4
            && defined($clause->[2])
            && !ref($clause->[2])
            && $clause->[2] eq 'of';

    my ($name, $actor_type) = ($clause->[1], $clause->[3]);
    return _actor_network_from_instance_parts($actor_name, $name, $actor_type, 'actor');
}

sub _looks_like_actor_network_compact_instance_alias($clause) {
    return ref($clause) eq 'ARRAY'
        && @$clause >= 2
        && defined($clause->[1])
        && !ref($clause->[1])
        && $clause->[1] eq ':';
}

sub _parse_actor_network_compact_instance_alias($self, $clause, $actor_name) {
    confess "Error: actor '$actor_name' compact static actor instance alias requires '(name : actor_type)'\n"
        unless @$clause == 3;

    my ($name, $actor_type) = ($clause->[0], $clause->[2]);
    return _actor_network_from_instance_parts($actor_name, $name, $actor_type, 'instance_alias');
}

sub _actor_network_from_instance_parts {
    my ($actor_name, $name, $actor_type, $declaration) = @_;
    confess "Error: actor '$actor_name' static actor instance name must be a scalar HDL identifier\n"
        unless _is_hdl_identifier($name);
    FSM::Support::HDLInstanceIdentifierPolicy->assert_authored_instance_identifier(
        $name,
        origin => "Actor '$actor_name' static actor instance",
    );
    confess "Error: actor '$actor_name' static actor instance '$name' type must be a scalar HDL identifier or selected ATL library-qualified 'ALIAS.EXPORT' token\n"
        unless _is_hdl_identifier($actor_type) || _is_library_qualified_actor_type($actor_type);
    confess "Error: actor '$actor_name' static actor instance '$name' cannot instantiate its own enclosing actor type '$actor_type'\n"
        if $actor_type eq $actor_name;

    return _actor_network_from_instances(
        $actor_name,
        [
            {
                name        => $name,
                actor_type  => $actor_type,
                declaration => $declaration,
            },
        ],
        [],
    );
}

sub _parse_actor_network_group($self, $clause, $actor_name) {
    confess "Error: actor '$actor_name' ATL concurrent group requires '(group name (members actor...) (mode concurrent))'\n"
        unless @$clause == 4;

    my $name = $clause->[1];
    confess "Error: actor '$actor_name' ATL concurrent group name must be a scalar HDL identifier\n"
        unless _is_hdl_identifier($name);

    my ($members, $mode);
    my %seen_clause;
    for my $part (@{$clause}[2, 3]) {
        confess "Error: actor '$actor_name' ATL concurrent group '$name' entries must be '(members ...)' or '(mode concurrent)'\n"
            unless ref($part) eq 'ARRAY' && @$part;
        my $head = $part->[0];
        confess "Error: actor '$actor_name' ATL concurrent group '$name' entry heads must be scalar\n"
            unless defined($head) && !ref($head);
        confess "Error: actor '$actor_name' ATL concurrent group '$name' has duplicate '$head' clause\n"
            if $seen_clause{$head}++;

        if ($head eq 'members') {
            confess "Error: actor '$actor_name' ATL concurrent group '$name' members require '(members actor actor...)'\n"
                unless @$part >= 3;
            $members = [ @{$part}[1 .. $#$part] ];
            next;
        }

        if ($head eq 'mode') {
            confess "Error: actor '$actor_name' ATL concurrent group '$name' mode requires '(mode concurrent)'\n"
                unless @$part == 2 && defined($part->[1]) && !ref($part->[1]);
            confess "Error: actor '$actor_name' ATL concurrent group '$name' only supports '(mode concurrent)' in the current subset\n"
                unless $part->[1] eq 'concurrent';
            $mode = $part->[1];
            next;
        }

        confess "Error: actor '$actor_name' ATL concurrent group '$name' has unsupported clause '$head'\n";
    }

    confess "Error: actor '$actor_name' ATL concurrent group '$name' requires '(members ...)' and '(mode concurrent)'\n"
        unless defined($members) && defined($mode);

    return _actor_network_from_instances(
        $actor_name,
        [],
        [
            {
                name        => $name,
                members     => $members,
                mode        => $mode,
                declaration => 'group',
                source      => 'actor_body',
                scheduling  => 'metadata_only',
            },
        ],
    );
}

sub _parse_actor_network_concurrent_alias($self, $clause, $actor_name) {
    confess "Error: actor '$actor_name' ATL compact concurrent group alias requires '(concurrent name actor actor...)'\n"
        unless @$clause >= 3;

    my $name = $clause->[1];
    confess "Error: actor '$actor_name' ATL compact concurrent group alias name must be a scalar HDL identifier\n"
        unless _is_hdl_identifier($name);

    my @members = @{$clause}[2 .. $#$clause];
    return _actor_network_from_instances(
        $actor_name,
        [],
        [
            {
                name        => $name,
                members     => \@members,
                mode        => 'concurrent',
                declaration => 'concurrent_alias',
                source      => 'actor_body',
                scheduling  => 'metadata_only',
            },
        ],
    );
}

sub _merge_actor_network($self, $actor, $incoming) {
    return 1 unless ref($incoming) eq 'HASH';

    my $actor_name = $actor->{actor_name} // 'unknown';
    my @existing = @{($actor->{actor_network} || {})->{instances} || []};
    my @incoming = @{$incoming->{instances} || []};
    my @merged = (@existing, @incoming);
    my @existing_groups = @{($actor->{actor_network} || {})->{groups} || []};
    my @incoming_groups = @{$incoming->{groups} || []};
    my @merged_groups = (@existing_groups, @incoming_groups);

    return 1 unless @merged || @merged_groups;

    my %seen;
    for my $instance (@merged) {
        my $name = $instance->{name};
        confess "Error: actor '$actor_name' static actor network has duplicate instance '$name'\n"
            if $seen{$name}++;
    }
    my %seen_group;
    for my $group (@merged_groups) {
        my $name = $group->{name};
        confess "Error: actor '$actor_name' static actor network has duplicate group '$name'\n"
            if $seen_group{$name}++;
    }

    $actor->{actor_network} = _actor_network_from_instances($actor_name, \@merged, \@merged_groups);
    return 1;
}

sub _actor_network_from_instances {
    my ($actor_name, $instances, $groups) = @_;
    my @instances = @{$instances || []};
    my @groups = @{$groups || []};
    confess "Error: actor '$actor_name' static actor network requires one actor instance or group in the current subset\n"
        unless @instances || @groups;

    return {
        kind      => 'static_declaration',
        instances => [ map { _clone_isf_value($_) } @instances ],
        groups => [ map { _clone_isf_value($_) } @groups ],
        event_waits => [],
        transaction_triggers => [],
        data_movements => [],
        association_schedules => [],
        group_schedules => [],
    };
}

sub _validate_actor_network_groups {
    my ($actor, $actor_instances) = @_;
    my @groups = @{(($actor->{actor_network} || {})->{groups}) || []};
    return 1 unless @groups;

    confess "Error: actor '$actor->{actor_name}' ATL concurrent groups require a single-clock actor in the current subset\n"
        if ref($actor->{clock_domains}) eq 'HASH';

    for my $group (@groups) {
        my $name = $group->{name};
        my @members = @{$group->{members} || []};
        confess "Error: actor '$actor->{actor_name}' ATL concurrent group '$name' requires at least two members\n"
            unless @members >= 2;
        my %seen_member;
        for my $member (@members) {
            confess "Error: actor '$actor->{actor_name}' ATL concurrent group '$name' member names must be scalar HDL identifiers\n"
                unless _is_hdl_identifier($member);
            confess "Error: actor '$actor->{actor_name}' ATL concurrent group '$name' references unknown static actor instance '$member'\n"
                unless ref($actor_instances) eq 'HASH' && $actor_instances->{$member};
            confess "Error: actor '$actor->{actor_name}' ATL concurrent group '$name' has duplicate member '$member'\n"
                if $seen_member{$member}++;
        }
    }

    return 1;
}

sub _parse_phase($self, $clause) {
    return $self->_parse_named_body_clause($clause, 'phase');
}

sub _parse_stage($self, $clause) {
    return $self->_parse_named_body_clause($clause, 'stage');
}

sub _parse_verification_observation($self, $clause, $actor_name) {
    confess "Error: actor '$actor_name' observe declaration requires '(observe NAME (role passive_monitor) (signals SIG...))'\n"
        unless @$clause >= 2;

    my $name = $clause->[1];
    confess "Error: observe declaration in actor '$actor_name' requires a scalar HDL identifier name\n"
        unless _is_hdl_identifier($name);

    my ($role, @signals);
    my %seen_clause;
    for my $part (@{$clause}[2 .. $#$clause]) {
        confess "Error: observe '$name' in actor '$actor_name' clauses must be list forms\n"
            unless ref($part) eq 'ARRAY' && @$part;
        my $head = $part->[0];
        confess "Error: observe '$name' in actor '$actor_name' clause heads must be scalar\n"
            unless defined($head) && !ref($head) && length($head);
        confess "Error: observe '$name' in actor '$actor_name' has duplicate '$head' clause\n"
            if $seen_clause{$head}++;

        if ($head eq 'role') {
            confess "Error: observe '$name' in actor '$actor_name' role requires '(role passive_monitor)'\n"
                unless @$part == 2 && defined($part->[1]) && !ref($part->[1]) && length($part->[1]);
            $role = $part->[1];
            confess "Error: observe '$name' in actor '$actor_name' has unsupported role '$role'; supported role: passive_monitor\n"
                unless $role eq 'passive_monitor';
            next;
        }

        if ($head eq 'signals') {
            my @items = grep { defined } @{$part}[1 .. $#$part];
            confess "Error: observe '$name' in actor '$actor_name' requires a non-empty '(signals SIG...)' clause\n"
                unless @items;

            my %seen_signal;
            for my $signal (@items) {
                confess "Error: observe '$name' in actor '$actor_name' signals entries must be scalar actor interface signal names\n"
                    unless _is_hdl_identifier($signal);
                confess "Error: observe '$name' in actor '$actor_name' has duplicate signal '$signal'\n"
                    if $seen_signal{$signal}++;
                push @signals, $signal;
            }
            next;
        }

        confess "Error: observe '$name' in actor '$actor_name' has unsupported clause '$head'\n";
    }

    confess "Error: observe '$name' in actor '$actor_name' requires '(role passive_monitor)'\n"
        unless defined $role;
    confess "Error: observe '$name' in actor '$actor_name' requires a non-empty '(signals SIG...)' clause\n"
        unless @signals;

    return {
        name    => $name,
        role    => $role,
        signals => \@signals,
    };
}

sub _parse_verification_bridge($self, $clause, $actor_name) {
    confess "Error: actor '$actor_name' verification-bridge requires domain, protocol, and transaction clauses\n"
        unless @$clause >= 2;

    my ($domain, $protocol, $transaction);
    my (@probes, @residues);
    my %seen_singleton;
    my (%seen_probe, %seen_residue);
    for my $part (@{$clause}[1 .. $#$clause]) {
        confess "Error: actor '$actor_name' verification-bridge clauses must be list forms\n"
            unless ref($part) eq 'ARRAY' && @$part;
        my $head = $part->[0];
        confess "Error: actor '$actor_name' verification-bridge clause heads must be scalar\n"
            unless defined($head) && !ref($head) && length($head);

        if ($head eq 'domain') {
            confess "Error: actor '$actor_name' verification-bridge has duplicate domain clause\n"
                if $seen_singleton{$head}++;
            confess "Error: actor '$actor_name' verification-bridge domain requires '(domain NAME)'\n"
                unless @$part == 2 && _is_hdl_identifier($part->[1]);
            $domain = $part->[1];
            next;
        }
        if ($head eq 'protocol') {
            confess "Error: actor '$actor_name' verification-bridge has duplicate protocol clause\n"
                if $seen_singleton{$head}++;
            $protocol = $self->_parse_verification_bridge_protocol($part, $actor_name);
            next;
        }
        if ($head eq 'transaction') {
            confess "Error: actor '$actor_name' verification-bridge has duplicate transaction clause\n"
                if $seen_singleton{$head}++;
            $transaction = $self->_parse_verification_bridge_transaction($part, $actor_name);
            next;
        }
        if ($head eq 'probe') {
            confess "Error: actor '$actor_name' verification-bridge probe requires '(probe NAME read_only)'\n"
                unless @$part == 3 && _is_hdl_identifier($part->[1])
                    && defined($part->[2]) && !ref($part->[2]) && $part->[2] eq 'read_only';
            confess "Error: actor '$actor_name' verification-bridge has duplicate probe '$part->[1]'\n"
                if $seen_probe{$part->[1]}++;
            push @probes, { name => $part->[1], access => $part->[2] };
            next;
        }
        if ($head eq 'residue') {
            confess "Error: actor '$actor_name' verification-bridge residue requires '(residue ID)'\n"
                unless @$part == 2 && _is_hdl_identifier($part->[1]);
            confess "Error: actor '$actor_name' verification-bridge has duplicate residue '$part->[1]'\n"
                if $seen_residue{$part->[1]}++;
            push @residues, $part->[1];
            next;
        }
        confess "Error: actor '$actor_name' verification-bridge has unsupported clause '$head'\n";
    }

    confess "Error: actor '$actor_name' verification-bridge requires exactly one '(domain NAME)' clause\n"
        unless defined $domain;
    confess "Error: actor '$actor_name' verification-bridge requires exactly one '(protocol ...)' clause\n"
        unless defined $protocol;
    confess "Error: actor '$actor_name' verification-bridge requires exactly one '(transaction ...)' clause\n"
        unless defined $transaction;

    return {
        domain      => $domain,
        protocol    => $protocol,
        transaction => $transaction,
        probes      => \@probes,
        residues    => \@residues,
    };
}

sub _parse_verification_bridge_protocol($self, $part, $actor_name) {
    confess "Error: actor '$actor_name' verification-bridge protocol requires a scalar HDL identifier name\n"
        unless @$part >= 2 && _is_hdl_identifier($part->[1]);
    my $name = $part->[1];
    my ($profile, $revision, $role, @facts);
    my %seen;
    my %seen_fact;
    for my $clause (@{$part}[2 .. $#$part]) {
        confess "Error: actor '$actor_name' verification-bridge protocol '$name' clauses must be list forms\n"
            unless ref($clause) eq 'ARRAY' && @$clause;
        my $head = $clause->[0];
        confess "Error: actor '$actor_name' verification-bridge protocol '$name' clause heads must be scalar\n"
            unless defined($head) && !ref($head) && length($head);
        confess "Error: actor '$actor_name' verification-bridge protocol '$name' has duplicate '$head' clause\n"
            if $seen{$head}++;
        if ($head eq 'profile' || $head eq 'revision' || $head eq 'role') {
            confess "Error: actor '$actor_name' verification-bridge protocol '$name' $head requires one non-empty scalar value\n"
                unless @$clause == 2 && defined($clause->[1]) && !ref($clause->[1]) && length($clause->[1]);
            $profile = $clause->[1] if $head eq 'profile';
            $revision = $clause->[1] if $head eq 'revision';
            $role = $clause->[1] if $head eq 'role';
            next;
        }
        if ($head eq 'facts') {
            for my $fact (@{$clause}[1 .. $#$clause]) {
                confess "Error: actor '$actor_name' verification-bridge protocol '$name' facts require '(fact NAME VALUE)' entries\n"
                    unless ref($fact) eq 'ARRAY' && @$fact == 3 && ($fact->[0] // '') eq 'fact'
                        && _is_hdl_identifier($fact->[1]) && defined($fact->[2]) && !ref($fact->[2]) && length($fact->[2]);
                confess "Error: actor '$actor_name' verification-bridge protocol '$name' has duplicate fact '$fact->[1]'\n"
                    if $seen_fact{$fact->[1]}++;
                push @facts, { name => $fact->[1], value => $fact->[2] };
            }
            next;
        }
        confess "Error: actor '$actor_name' verification-bridge protocol '$name' has unsupported clause '$head'\n";
    }
    confess "Error: actor '$actor_name' verification-bridge protocol '$name' requires profile, revision, role, and non-empty facts clauses\n"
        unless defined($profile) && defined($revision) && defined($role) && @facts;
    return {
        name     => $name,
        profile  => $profile,
        revision => $revision,
        role     => $role,
        facts    => \@facts,
    };
}

sub _parse_verification_bridge_transaction($self, $part, $actor_name) {
    confess "Error: actor '$actor_name' verification-bridge transaction requires a scalar HDL identifier name\n"
        unless @$part >= 2 && _is_hdl_identifier($part->[1]);
    my $name = $part->[1];
    my (@fields, @events);
    my (%seen_clause, %seen_field, %seen_event);
    for my $clause (@{$part}[2 .. $#$part]) {
        confess "Error: actor '$actor_name' verification-bridge transaction '$name' clauses must be list forms\n"
            unless ref($clause) eq 'ARRAY' && @$clause;
        my $head = $clause->[0];
        confess "Error: actor '$actor_name' verification-bridge transaction '$name' clause heads must be scalar\n"
            unless defined($head) && !ref($head) && length($head);
        confess "Error: actor '$actor_name' verification-bridge transaction '$name' supports only one fields and one events clause\n"
            if $seen_clause{$head}++;
        if ($head eq 'fields') {
            for my $field (@{$clause}[1 .. $#$clause]) {
                confess "Error: actor '$actor_name' verification-bridge transaction '$name' fields require '(field NAME SOURCE drive|sample PHASE_ROLE)' entries\n"
                    unless ref($field) eq 'ARRAY' && @$field == 5 && ($field->[0] // '') eq 'field'
                        && _is_hdl_identifier($field->[1]) && _is_hdl_identifier($field->[2])
                        && defined($field->[3]) && !ref($field->[3]) && $field->[3] =~ /\A(?:drive|sample)\z/
                        && defined($field->[4]) && !ref($field->[4]) && $field->[4] =~ /\A(?:address_phase|data_phase|configuration|unspecified)\z/;
                confess "Error: actor '$actor_name' verification-bridge transaction '$name' has duplicate field '$field->[1]'\n"
                    if $seen_field{$field->[1]}++;
                push @fields, {
                    name       => $field->[1],
                    source     => $field->[2],
                    direction  => $field->[3],
                    phase_role => $field->[4],
                };
            }
            next;
        }
        if ($head eq 'events') {
            for my $event (@{$clause}[1 .. $#$clause]) {
                confess "Error: actor '$actor_name' verification-bridge transaction '$name' events require '(event NAME scenario_start|predicate|rising PHASE [EXPR])' entries\n"
                    unless ref($event) eq 'ARRAY' && @$event >= 4 && ($event->[0] // '') eq 'event'
                        && _is_hdl_identifier($event->[1])
                        && defined($event->[2]) && !ref($event->[2]) && $event->[2] =~ /\A(?:scenario_start|predicate|rising)\z/
                        && defined($event->[3]) && !ref($event->[3]) && $event->[3] =~ /\A(?:drive|sample|react|check)\z/;
                my ($event_name, $kind, $phase) = @{$event}[1, 2, 3];
                confess "Error: actor '$actor_name' verification-bridge transaction '$name' has duplicate event '$event_name'\n"
                    if $seen_event{$event_name}++;
                confess "Error: actor '$actor_name' verification-bridge event '$event_name' scenario_start takes no expression\n"
                    if $kind eq 'scenario_start' && @$event != 4;
                confess "Error: actor '$actor_name' verification-bridge event '$event_name' $kind requires exactly one expression\n"
                    if $kind ne 'scenario_start' && @$event != 5;
                push @events, {
                    name       => $event_name,
                    kind       => $kind,
                    phase      => $phase,
                    expression => $kind eq 'scenario_start' ? undef : _clone_isf_value($event->[4]),
                };
            }
            next;
        }
        confess "Error: actor '$actor_name' verification-bridge transaction '$name' has unsupported clause '$head'\n";
    }
    confess "Error: actor '$actor_name' verification-bridge transaction '$name' requires non-empty fields and events clauses\n"
        unless @fields && @events;
    return { name => $name, fields => \@fields, events => \@events };
}

sub _finalize_actor_verification_bridge($self, $actor) {
    my $bridge = $actor->{verification_bridge};
    return 1 unless ref($bridge) eq 'HASH';

    my $actor_name = $actor->{actor_name} // 'unknown';
    confess "Error: actor '$actor_name' verification-bridge requires a single-clock actor\n"
        if ref($actor->{clock_domains}) eq 'HASH';
    confess "Error: actor '$actor_name' verification-bridge requires an explicit clock and reset\n"
        unless defined($actor->{clock}) && !ref($actor->{clock}) && ref($actor->{reset}) eq 'HASH';

    my %endpoint_by_name;
    for my $direction (qw(inputs outputs)) {
        my $public_direction = $direction eq 'inputs' ? 'input' : 'output';
        for my $port (@{($actor->{interface} || {})->{$direction} || []}) {
            $endpoint_by_name{$port->{name}} = {
                kind      => 'endpoint',
                name      => $port->{name},
                direction => $public_direction,
                width     => 0 + $port->{width},
                signed    => $port->{signed} ? 1 : 0,
            };
        }
    }
    my %parameter_by_name = map { ($_->{name} => $_) } @{$actor->{params} || []};
    my %probe_by_name;
    for my $probe (@{$bridge->{probes} || []}) {
        my $storage = _actor_storage_signal_by_name($actor, $probe->{name});
        confess "Error: actor '$actor_name' verification-bridge probe '$probe->{name}' must reference resolved actor-owned scalar storage\n"
            unless ref($storage) eq 'HASH' && defined($storage->{width}) && !ref($storage->{width})
                && "$storage->{width}" =~ /\A[1-9][0-9]*\z/;
        confess "Error: actor '$actor_name' verification-bridge probe '$probe->{name}' cannot reference a public interface endpoint\n"
            if $endpoint_by_name{$probe->{name}};
        $probe->{source} = {
            kind      => 'storage',
            name      => $probe->{name},
            direction => 'sample',
            width     => 0 + $storage->{width},
            signed    => $storage->{signed} ? 1 : 0,
        };
        $probe_by_name{$probe->{name}} = $probe;
    }

    for my $field (@{$bridge->{transaction}{fields} || []}) {
        my $source_name = $field->{source};
        my $source = $endpoint_by_name{$source_name};
        if (!$source && $parameter_by_name{$source_name}) {
            my $parameter = $parameter_by_name{$source_name};
            my $width = $parameter->{width};
            confess "Error: actor '$actor_name' verification-bridge field '$field->{name}' parameter '$source_name' lacks a resolved positive scalar width\n"
                unless defined($width) && !ref($width) && "$width" =~ /\A[1-9][0-9]*\z/;
            $source = {
                kind      => 'configuration',
                name      => $source_name,
                direction => 'configuration',
                width     => 0 + $width,
                signed    => $parameter->{signed} ? 1 : 0,
            };
        }
        confess "Error: actor '$actor_name' verification-bridge field '$field->{name}' references unknown endpoint or configuration '$source_name'\n"
            unless $source;
        confess "Error: actor '$actor_name' verification-bridge drive field '$field->{name}' must reference an input endpoint or configuration\n"
            if $field->{direction} eq 'drive'
                && $source->{direction} ne 'input' && $source->{direction} ne 'configuration';
        confess "Error: actor '$actor_name' verification-bridge sample field '$field->{name}' must reference an output endpoint\n"
            if $field->{direction} eq 'sample' && $source->{direction} ne 'output';
        $field->{source} = _clone_isf_value($source);
    }

    for my $event (@{$bridge->{transaction}{events} || []}) {
        next unless defined $event->{expression};
        my $width = _validate_verification_bridge_expression(
            $event->{expression},
            $actor,
            \%endpoint_by_name,
            \%probe_by_name,
            "actor '$actor_name' verification-bridge event '$event->{name}'",
        );
        confess "Error: actor '$actor_name' verification-bridge predicate event '$event->{name}' requires a one-bit Boolean expression\n"
            if $event->{kind} eq 'predicate' && (!defined($width) || $width != 1);
        if ($event->{kind} eq 'rising') {
            confess "Error: actor '$actor_name' verification-bridge rising event '$event->{name}' requires one scalar one-bit signal reference\n"
                if ref($event->{expression});
            my $width = _verification_bridge_reference_width(
                $event->{expression}, $actor, \%endpoint_by_name, \%probe_by_name,
            );
            confess "Error: actor '$actor_name' verification-bridge rising event '$event->{name}' requires one scalar one-bit signal reference\n"
                unless defined($width) && $width == 1;
        }
    }
    return 1;
}

sub _verification_bridge_reference_width {
    my ($name, $actor, $endpoint_by_name, $probe_by_name) = @_;
    return $endpoint_by_name->{$name}{width} if $endpoint_by_name->{$name};
    return $probe_by_name->{$name}{source}{width} if $probe_by_name->{$name};
    return 1 if $name eq ($actor->{clock} // '') || $name eq (($actor->{reset} || {})->{name} // '');
    my $storage = _actor_storage_signal_by_name($actor, $name);
    return ref($storage) eq 'HASH' ? $storage->{width} : undef;
}

sub _validate_verification_bridge_expression {
    my ($expression, $actor, $endpoint_by_name, $probe_by_name, $context) = @_;
    if (ref($expression) eq 'ARRAY') {
        confess "Error: $context expression list must contain an operator and operand\n"
            unless @$expression >= 2;
        my $operator = $expression->[0];
        confess "Error: $context expression operator must be scalar\n"
            unless defined($operator) && !ref($operator) && length($operator);
        confess "Error: $context expression uses unsupported operator '$operator'\n"
            unless $VERIFICATION_BRIDGE_EXPRESSION_OPERATOR{$operator};
        my $operand_count = $#$expression;
        confess "Error: $context unary operator '$operator' requires exactly one operand\n"
            if ($operator eq '!' || $operator eq '~') && $operand_count != 1;
        confess "Error: $context comparison operator '$operator' requires exactly two operands\n"
            if $operator =~ /\A(?:=|==|!=|<|>|<=|>=)\z/ && $operand_count != 2;
        confess "Error: $context bitwise operator '$operator' requires at least two operands\n"
            if ($operator eq '&' || $operator eq '|' || $operator eq '^'
                || $operator eq '!|' || $operator eq '~|') && $operand_count < 2;
        my @widths;
        for my $operand (@{$expression}[1 .. $#$expression]) {
            push @widths, _validate_verification_bridge_expression(
                $operand, $actor, $endpoint_by_name, $probe_by_name, $context,
            );
        }
        my @known_widths = grep { defined $_ } @widths;
        my %known_width = map { $_ => 1 } @known_widths;
        confess "Error: $context operator '$operator' has incompatible operand widths\n"
            if keys(%known_width) > 1;
        return 1 if $operator =~ /\A(?:=|==|!=|<|>|<=|>=)\z/;
        return @known_widths ? $known_widths[0] : undef;
    }
    confess "Error: $context expression leaves must be scalar\n"
        if !defined($expression) || ref($expression);
    return 1 if $expression =~ /\A(?:true|false)\z/;
    return undef if $expression =~ /\A[0-9]+\z/;
    return 0 + $1 if $expression =~ /\A([0-9]+)'[sS]?[bBoOdDhH][0-9a-fA-F_xXzZ?]+\z/;
    return $endpoint_by_name->{$expression}{width} if $endpoint_by_name->{$expression};
    return $probe_by_name->{$expression}{source}{width} if $probe_by_name->{$expression};
    return 1 if $expression eq ($actor->{clock} // '') || $expression eq (($actor->{reset} || {})->{name} // '');
    my $storage = _actor_storage_signal_by_name($actor, $expression);
    return $storage->{width} if ref($storage) eq 'HASH';
    confess "Error: $context expression references unknown endpoint, probe, timing signal, or actor storage '$expression'\n";
}

sub _finalize_actor_verification_observations($self, $actor) {
    my @observations = @{$actor->{verification_observations} || []};
    return 1 unless @observations;

    my $actor_name = $actor->{actor_name} // 'unknown';
    confess "Error: actor '$actor_name' observe declarations require a single-clock actor; multi-domain observation partitioning remains deferred\n"
        if ref($actor->{clock_domains}) eq 'HASH';

    my %interface_by_name;
    for my $direction (qw(inputs outputs)) {
        my $public_direction = $direction eq 'inputs' ? 'input' : 'output';
        for my $port (@{($actor->{interface} || {})->{$direction} || []}) {
            my $port_name = $port->{name};
            my $width = $port->{width};
            confess "Error: actor '$actor_name' interface port '$port_name' cannot be observed because its width is not a resolved positive scalar width\n"
                unless defined($width) && !ref($width) && "$width" =~ /\A[1-9][0-9]*\z/;
            $interface_by_name{$port_name} = {
                name      => $port_name,
                direction => $public_direction,
                width     => 0 + $width,
            };
        }
    }

    for my $observation (@observations) {
        my @resolved_signals;
        for my $signal (@{$observation->{signals} || []}) {
            my $interface_signal = $interface_by_name{$signal};
            if (!$interface_signal) {
                my $storage = _actor_storage_signal_by_name($actor, $signal);
                confess "Error: observe '$observation->{name}' in actor '$actor_name' references actor-owned storage '$signal'; observe signals must be actor interface inputs or outputs\n"
                    if $storage;

                my $transaction_port = _actor_transaction_port_by_name($actor, $signal);
                confess "Error: observe '$observation->{name}' in actor '$actor_name' references transaction-local port '$signal' in transaction '$transaction_port->{transaction}'; observe signals must be actor interface inputs or outputs\n"
                    if $transaction_port;

                confess "Error: observe '$observation->{name}' in actor '$actor_name' references unknown actor interface signal '$signal'\n";
            }
            push @resolved_signals, _clone_isf_value($interface_signal);
        }
        $observation->{signals} = \@resolved_signals;
    }

    return 1;
}

sub _validate_transaction_phase_stage_clauses($self, $clauses) {
    return unless ref($clauses) eq 'ARRAY';

    for my $clause (@$clauses) {
        next unless ref($clause) eq 'ARRAY' && @$clause;
        my $keyword = $clause->[0];
        next unless defined($keyword) && !ref($keyword);

        if ($keyword eq 'phase' || $keyword eq 'stage') {
            $self->_parse_named_body_clause($clause, $keyword);
        }

        if ($keyword eq 'when' || $keyword eq 'repeat') {
            $self->_validate_transaction_phase_stage_clauses([@{$clause}[2 .. $#$clause]]);
        } elsif ($keyword eq 'switch') {
            for my $branch (@{$clause}[2 .. $#$clause]) {
                next unless ref($branch) eq 'ARRAY';
                $self->_validate_transaction_phase_stage_clauses([@{$branch}[1 .. $#$branch]]);
            }
        }
    }
}

sub _parse_named_body_clause($self, $clause, $kind) {
    confess "Error: ($kind ...) requires a name\n" unless @$clause >= 2;
    my $name = $clause->[1];
    confess "Error: ($kind ...) requires a scalar name\n"
        unless defined($name) && !ref($name) && length($name);

    my @body;
    for my $i (2 .. $#$clause) {
        my $entry = $clause->[$i];
        confess "Error: $kind '$name' body entries must be list forms\n"
            unless ref($entry) eq 'ARRAY' && @$entry;
        confess "Error: $kind '$name' body entry heads must be scalar\n"
            unless defined($entry->[0]) && !ref($entry->[0]) && length($entry->[0]);
        push @body, $entry;
    }

    return { name => $name, body => \@body };
}

sub _read_text_file($path) {
    open my $fh, '<', $path
        or confess "Error: unable to read '$path': $!\n";
    local $/;
    my $content = <$fh>;
    close $fh
        or confess "Error: unable to close '$path' after reading: $!\n";
    return defined($content) ? $content : '';
}

1;

perl/FSM/Package/AggregatePathSupport.pm:
package FSM::Package::AggregatePathSupport;

=head1 NAME

FSM::Package::AggregatePathSupport - Shared declared aggregate path resolver

=head1 DESCRIPTION

Owns type-directed traversal for declared aggregate member/item paths. Frontend
and composition layers can consume the same resolved path segments and leaf
type facts without carrying parallel walkers that drift over time.

=cut

use v5.20;
use strict;
use warnings;
use feature qw(signatures);
no warnings 'experimental::signatures';

use FSM::Package::PayloadTypeSupport;

sub resolve ($class, %args) {
    my $root_type_spec = $args{root_type_spec};
    my $path_text = $args{path_text} // '';

    return $class->_failure('empty_path')
        unless length $path_text;

    return $class->_failure('missing_declared_type')
        unless ref($root_type_spec) eq 'HASH';

    my $root_kind = $root_type_spec->{kind} || '';
    return $class->_failure(
        'scalar_root',
        current_type_label => FSM::Package::PayloadTypeSupport->type_spec_label($root_type_spec),
    ) unless $root_kind eq 'record' || $root_kind eq 'list';

    my $remaining = $path_text;
    my $current_type_spec = $root_type_spec;
    my @path_segments;

    while (length $remaining) {
        if ($remaining =~ s/\A\.([A-Za-z_]\w*)//) {
            my $member_name = $1;
            my $kind = $current_type_spec->{kind} || '';

            return $class->_failure(
                'member_on_non_record',
                member_name => $member_name,
                current_type_label => FSM::Package::PayloadTypeSupport->type_spec_label($current_type_spec),
            ) unless $kind eq 'record';

            my $members = $current_type_spec->{members} || {};
            return $class->_failure(
                'unknown_member',
                member_name => $member_name,
                known_members => [ @{ $current_type_spec->{member_order} || [] } ],
            ) unless exists $members->{$member_name};

            push @path_segments, { kind => 'member', name => $member_name };
            $current_type_spec = $members->{$member_name};
            next;
        }

        if ($remaining =~ s/\A\[(\d+)(?::(\d+))?\]//) {
            my ($first_index, $second_index) = ($1, $2);
            my $kind = $current_type_spec->{kind} || '';

            if ($kind eq 'list') {
                return $class->_failure('list_range_not_supported')
                    if defined $second_index;

                my $items = $current_type_spec->{items} || [];
                return $class->_failure(
                    'list_index_out_of_range',
                    index => 0 + $first_index,
                    max_index => (@$items ? $#$items : -1),
                ) unless $first_index < @$items;

                push @path_segments, { kind => 'item', index => 0 + $first_index };
                $current_type_spec = $items->[$first_index];
                next;
            }

            if ($kind eq 'bit' || $kind eq 'bits') {
                my $scalar_width = $current_type_spec->{width} // 0;
                if (defined $second_index) {
                    my ($high, $low) = ($first_index, $second_index);
                    my $max_index = $high > $low ? $high : $low;
                    return $class->_failure(
                        'scalar_slice_out_of_range',
                        high => 0 + $high,
                        low => 0 + $low,
                        scalar_width => 0 + $scalar_width,
                    ) unless $scalar_width > 0 && $max_index < $scalar_width;

                    my $slice_width = abs($high - $low) + 1;
                    push @path_segments, { kind => 'bit_slice', high => 0 + $high, low => 0 + $low };
                    $current_type_spec = FSM::Package::PayloadTypeSupport->scalar_type_spec_from_width($slice_width);
                    next;
                }

                return $class->_failure(
                    'scalar_index_out_of_range',
                    index => 0 + $first_index,
                    scalar_width => 0 + $scalar_width,
                ) unless $scalar_width > 0 && $first_index < $scalar_width;

                push @path_segments, { kind => 'bit_index', index => 0 + $first_index };
                $current_type_spec = FSM::Package::PayloadTypeSupport->scalar_type_spec_from_width(1);
                next;
            }

            return $class->_failure(
                'index_on_non_indexable',
                current_type_label => FSM::Package::PayloadTypeSupport->type_spec_label($current_type_spec),
            );
        }

        return $class->_failure(
            'parse_error',
            remaining => $remaining,
        );
    }

    my $resolved_width = ref($current_type_spec) eq 'HASH' ? ($current_type_spec->{width} // undef) : undef;
    return $class->_failure('missing_leaf_width')
        unless defined($resolved_width) && $resolved_width > 0;

    return {
        ok => 1,
        path_segments => $class->clone_structured_value(\@path_segments),
        type_spec => $class->clone_structured_value($current_type_spec),
        width => 0 + $resolved_width,
    };
}

sub resolve_type_path ($class, %args) {
    my $result = $class->resolve(%args);
    return (undef, undef) unless $result->{ok};
    return (
        $class->clone_structured_value($result->{type_spec}),
        $result->{width},
    );
}

sub resolve_packed_range ($class, %args) {
    my $root_type_spec = $args{root_type_spec};
    return $class->_failure('missing_declared_type')
        unless ref($root_type_spec) eq 'HASH';

    my $path_segments = $args{path_segments};
    if (ref($path_segments) ne 'ARRAY') {
        my $resolved_path = $class->resolve(
            root_type_spec => $root_type_spec,
            path_text => $args{path_text},
        );
        return $resolved_path unless $resolved_path->{ok};
        $path_segments = $resolved_path->{path_segments};
    }

    return $class->_failure('empty_path')
        unless ref($path_segments) eq 'ARRAY' && @$path_segments;

    my $root_kind = $root_type_spec->{kind} || '';
    return $class->_failure(
        'scalar_root',
        current_type_label => FSM::Package::PayloadTypeSupport->type_spec_label($root_type_spec),
    ) unless $root_kind eq 'record' || $root_kind eq 'list';

    my $current_type_spec = $root_type_spec;
    my $base_low = 0;

    for my $segment (@$path_segments) {
        my $kind = $segment->{kind} || '';
        my $type_kind = $current_type_spec->{kind} || '';

        if ($kind eq 'member') {
            my $member_name = $segment->{name};
            return $class->_failure(
                'member_on_non_record',
                member_name => $member_name,
                current_type_label => FSM::Package::PayloadTypeSupport->type_spec_label($current_type_spec),
            ) unless $type_kind eq 'record';

            my $members = $current_type_spec->{members} || {};
            return $class->_failure(
                'unknown_member',
                member_name => $member_name,
                known_members => [ @{ $current_type_spec->{member_order} || [] } ],
            ) unless exists $members->{$member_name};

            my $offset = $class->record_member_low_offset($current_type_spec, $member_name);
            return $class->_failure(
                'member_missing_packed_offset',
                member_name => $member_name,
            ) unless defined $offset;

            $base_low += $offset;
            $current_type_spec = $members->{$member_name};
            next;
        }

        if ($kind eq 'item') {
            return $class->_failure(
                'index_on_non_indexable',
                current_type_label => FSM::Package::PayloadTypeSupport->type_spec_label($current_type_spec),
            ) unless $type_kind eq 'list';

            my $index = $segment->{index};
            my $items = $current_type_spec->{items} || [];
            my $index_label = defined($index) && $index =~ /^\d+$/ ? 0 + $index : $index;
            return $class->_failure(
                'list_index_out_of_range',
                index => $index_label,
                max_index => (@$items ? $#$items : -1),
            ) unless defined($index) && $index =~ /^\d+$/ && $index < @$items;

            my $offset = $class->list_item_low_offset($current_type_spec, $index);
            return $class->_failure(
                'item_missing_packed_offset',
                index => 0 + $index,
            ) unless defined $offset;

            $base_low += $offset;
            $current_type_spec = $items->[$index];
            next;
        }

        if ($kind eq 'bit_index') {
            return $class->_failure(
                'index_on_non_indexable',
                current_type_label => FSM::Package::PayloadTypeSupport->type_spec_label($current_type_spec),
            ) unless $type_kind eq 'bit' || $type_kind eq 'bits';

            my $index = $segment->{index};
            my $width = $current_type_spec->{width} // 0;
            my $index_label = defined($index) && $index =~ /^\d+$/ ? 0 + $index : $index;
            return $class->_failure(
                'scalar_index_out_of_range',
                index => $index_label,
                scalar_width => 0 + $width,
            ) unless defined($index) && $index =~ /^\d+$/ && $width > 0 && $index < $width;

            $base_low += $index;
            $current_type_spec = FSM::Package::PayloadTypeSupport->scalar_type_spec_from_width(1);
            next;
        }

        if ($kind eq 'bit_slice') {
            return $class->_failure(
                'index_on_non_indexable',
                current_type_label => FSM::Package::PayloadTypeSupport->type_spec_label($current_type_spec),
            ) unless $type_kind eq 'bit' || $type_kind eq 'bits';

            my ($high, $low) = ($segment->{high}, $segment->{low});
            my $width = $current_type_spec->{width} // 0;
            my $high_label = defined($high) && $high =~ /^\d+$/ ? 0 + $high : $high;
            my $low_label = defined($low) && $low =~ /^\d+$/ ? 0 + $low : $low;
            return $class->_failure(
                'scalar_slice_out_of_range',
                high => $high_label,
                low => $low_label,
                scalar_width => 0 + $width,
            ) unless defined($high) && defined($low) && $high =~ /^\d+$/ && $low =~ /^\d+$/;

            my $slice_high = $high > $low ? $high : $low;
            my $slice_low = $high > $low ? $low : $high;
            return $class->_failure(
                'scalar_slice_out_of_range',
                high => 0 + $high,
                low => 0 + $low,
                scalar_width => 0 + $width,
            ) unless $width > 0 && $slice_high < $width;

            $base_low += $slice_low;
            $current_type_spec = FSM::Package::PayloadTypeSupport->scalar_type_spec_from_width(
                $slice_high - $slice_low + 1,
            );
            next;
        }

        return $class->_failure(
            'unsupported_path_segment',
            segment_kind => $kind,
        );
    }

    my $resolved_width = ref($current_type_spec) eq 'HASH' ? ($current_type_spec->{width} // undef) : undef;
    return $class->_failure('missing_leaf_width')
        unless defined($resolved_width) && $resolved_width > 0;

    return {
        ok => 1,
        high => $base_low + $resolved_width - 1,
        low => $base_low,
        width => 0 + $resolved_width,
        type_spec => $class->clone_structured_value($current_type_spec),
    };
}

=head2 type_spec_for_packed_fragment

Return the type contract for one packed bit range relative to an aggregate root.
Exact nested record/list fragments keep their aggregate type; arbitrary
cross-member fragments fall back to a scalar width contract.

=cut

sub type_spec_for_packed_fragment ($class, %args) {
    my $root_type_spec = $args{root_type_spec};
    return unless ref($root_type_spec) eq 'HASH';

    my ($high, $low) = ($args{high}, $args{low});
    return unless defined($high)
        && defined($low)
        && $high =~ /^\d+$/
        && $low =~ /^\d+$/
        && $high >= $low;

    my $root_width = $root_type_spec->{width};
    return unless defined($root_width) && $root_width > 0 && $high < $root_width;

    if (defined $args{total_width}) {
        my $total_width = $args{total_width};
        return unless $total_width == $root_width;
    }

    return $class->_type_spec_for_relative_packed_fragment($root_type_spec, 0 + $high, 0 + $low);
}

sub _type_spec_for_relative_packed_fragment ($class, $type_spec, $high, $low) {
    return unless ref($type_spec) eq 'HASH';
    my $width = $type_spec->{width};
    return unless defined($width) && $width > 0;
    return unless defined($high) && defined($low) && $high >= $low && $low >= 0 && $high < $width;

    return $class->clone_structured_value($type_spec)
        if $low == 0 && $high == $width - 1;

    my $kind = $type_spec->{kind} || '';
    if ($kind eq 'record') {
        return $class->_record_fragment_type_spec($type_spec, $high, $low);
    }
    if ($kind eq 'list') {
        return $class->_list_fragment_type_spec($type_spec, $high, $low);
    }

    return FSM::Package::PayloadTypeSupport->scalar_type_spec_from_width($high - $low + 1);
}

sub _record_fragment_type_spec ($class, $type_spec, $high, $low) {
    my $members = $type_spec->{members} || {};
    for my $member_name (@{$type_spec->{member_order} || []}) {
        next unless exists $members->{$member_name};
        my $member_type_spec = $members->{$member_name};
        my $member_low = $class->record_member_low_offset($type_spec, $member_name);
        next unless defined $member_low;
        my $member_width = $member_type_spec->{width};
        next unless defined($member_width) && $member_width > 0;
        my $member_high = $member_low + $member_width - 1;

        next unless $low >= $member_low && $high <= $member_high;
        return $class->_type_spec_for_relative_packed_fragment(
            $member_type_spec,
            $high - $member_low,
            $low - $member_low,
        );
    }

    return FSM::Package::PayloadTypeSupport->scalar_type_spec_from_width($high - $low + 1);
}

sub _list_fragment_type_spec ($class, $type_spec, $high, $low) {
    my $items = $type_spec->{items} || [];
    for my $index (0 .. $#$items) {
        my $item_type_spec = $items->[$index];
        my $item_low = $class->list_item_low_offset($type_spec, $index);
        next unless defined $item_low;
        my $item_width = $item_type_spec->{width};
        next unless defined($item_width) && $item_width > 0;
        my $item_high = $item_low + $item_width - 1;

        next unless $low >= $item_low && $high <= $item_high;
        return $class->_type_spec_for_relative_packed_fragment(
            $item_type_spec,
            $high - $item_low,
            $low - $item_low,
        );
    }

    return FSM::Package::PayloadTypeSupport->scalar_type_spec_from_width($high - $low + 1);
}

sub record_member_low_offset ($class, $record_type_spec, $member_name) {
    my $members = $record_type_spec->{members} || {};
    my $order = $record_type_spec->{member_order} || [];
    my $offset = 0;

    for my $ordered_member (reverse @$order) {
        return $offset if $ordered_member eq $member_name;
        return undef unless exists $members->{$ordered_member};
        $offset += $members->{$ordered_member}{width} // 0;
    }

    return undef;
}

sub list_item_low_offset ($class, $list_type_spec, $target_index) {
    my $items = $list_type_spec->{items} || [];
    return undef unless defined($target_index) && $target_index =~ /^\d+$/ && $target_index < @$items;

    my $offset = 0;
    for my $index (reverse 0 .. $#$items) {
        return $offset if $index == $target_index;
        $offset += $items->[$index]{width} // 0;
    }

    return undef;
}

sub clone_structured_value ($class, $value) {
    return undef unless defined $value;

    if (ref($value) eq 'HASH') {
        return {
            map { $_ => $class->clone_structured_value($value->{$_}) } sort keys %$value
        };
    }

    if (ref($value) eq 'ARRAY') {
        return [ map { $class->clone_structured_value($_) } @$value ];
    }

    return $value;
}

sub _failure ($class, $code, %details) {
    return {
        ok => 0,
        code => $code,
        %details,
    };
}

1;

__END__

=head1 METHODS

=head2 resolve

Resolves one authored aggregate path against a declared aggregate type spec and
returns stable path segments plus the resolved leaf type and width.

=head2 resolve_type_path

Returns only the resolved leaf type spec and width, or C<(undef, undef)> when
the path cannot be resolved.

=head2 resolve_packed_range

Resolves a declared aggregate path into the packed base-signal bit range that
the leaf occupies.

=head2 record_member_low_offset

Returns the packed low-bit offset of a record member within its record.

=head2 list_item_low_offset

Returns the packed low-bit offset of a list item within its generated packed
list representation.

=head2 clone_structured_value

Clones a nested scalar/list/record type-spec structure.

=cut

perl/FSM/Package/ImportResolver.pm:
package FSM::Package::ImportResolver;

=head1 NAME

FSM::Package::ImportResolver - Shared semantic package import resolver

=head1 DESCRIPTION

Owns the bounded semantic package import lane shared by composition tops and
direct generated roots. This package resolves named package imports from
embedded C<?pkg:name> roots or external searchable C<.fsm> files and returns
typed L<FSM::Package::Spec> records for later symbol injection.

=cut

use v5.20;
use strict;
use warnings;
use Carp qw(confess);
use feature qw(signatures);
no warnings 'experimental::signatures';

use File::Basename qw(dirname);
use File::Spec;
use FSM::Package::Parser;
use FSM::Pipeline::SourceFrontend;

sub resolve_imports ($class, %args) {
    my $package_imports = $args{package_imports}
        or confess "Package::ImportResolver requires package_imports";
    my $embedded_package_sources = $args{embedded_package_sources} || {};
    my $source_path_resolver = $args{source_path_resolver}
        or confess "Package::ImportResolver requires a source_path_resolver";

    my $parser = FSM::Package::Parser->new(
        debug => ($args{debug_level} // 0) > 0,
    );

    my %resolved_packages;
    for my $package_name (@$package_imports) {
        next if exists $resolved_packages{$package_name};

        $resolved_packages{$package_name} = $class->_resolve_one_package_import(
            parser => $parser,
            embedded_package_sources => $embedded_package_sources,
            source_path_resolver => $source_path_resolver,
            package_name => $package_name,
            fsm_file => $args{fsm_file},
            owner_label => ($args{owner_label} // 'Source'),
            docs_hint => ($args{docs_hint} // ''),
        );
    }

    return \%resolved_packages;
}

sub _resolve_one_package_import ($class, %args) {
    my $parser = $args{parser}
        or confess "Package::ImportResolver requires a parser";
    my $embedded_package_sources = $args{embedded_package_sources} || {};
    my $package_name = $args{package_name}
        or confess "Package::ImportResolver requires a package_name";

    if (my $embedded_ast = $embedded_package_sources->{$package_name}) {
        return $parser->parse_package_root($embedded_ast);
    }

    my ($package_path, $search_dirs, $searched_paths) = $class->resolve_external_package_source_path(%args);
    my $raw_ast = FSM::Pipeline::SourceFrontend->parse_fsm_file(
        fsm_file => $package_path,
        debug_level => 0,
    );
    my $source_info = FSM::Pipeline::SourceFrontend->classify_source_ast($raw_ast);
    my $header = $source_info->{header} // 'unknown';

    confess
        "$args{owner_label} imports package '$package_name' from '$package_path', "
      . "but package-source root support is blocked because that file does not use a '?pkg:package_name' root. "
      . "Observed root: '$header'. "
      . "Search roots: ".join(', ', @$search_dirs).". "
      . "Searched locations: ".join(', ', @$searched_paths)."."
      . $class->_formatted_docs_hint($args{docs_hint})
        unless defined($header) && $header =~ /^\?pkg:/;

    my $package_spec = $parser->parse_source($raw_ast);
    confess
        "$args{owner_label} imports package '$package_name' from '$package_path', "
      . "but package-name matching is blocked because that file declares '?pkg:".$package_spec->name."' instead of '?pkg:$package_name'. "
      . "Package imports currently require the imported package name and the package root name to match exactly."
      . $class->_formatted_docs_hint($args{docs_hint})
        unless $package_spec->name eq $package_name;

    return $package_spec;
}

sub resolve_external_package_source_path ($class, %args) {
    my $source_path_resolver = $args{source_path_resolver}
        or confess "Package::ImportResolver requires a source_path_resolver";
    my $package_name = $args{package_name}
        or confess "Package::ImportResolver requires a package_name";

    my @preferred_dirs;
    if (defined($args{fsm_file}) && length($args{fsm_file}) && $args{fsm_file} =~ m{/}) {
        push @preferred_dirs, dirname($args{fsm_file});
    }

    my @search_dirs = @{
        $source_path_resolver->normalized_search_paths(
            preferred_dirs => \@preferred_dirs,
            include_cwd => 1,
        )
    };

    my $target_filename = "$package_name.fsm";
    my @searched_paths = map { File::Spec->catfile($_, $target_filename) } @search_dirs;

    for my $candidate (@searched_paths) {
        return ($candidate, \@search_dirs, \@searched_paths) if -f $candidate;
    }

    confess
        "$args{owner_label} imports package '$package_name', "
      . "but package-source resolution is blocked because no active '?pkg:$package_name' source was found either embedded in the same file or in an external '.fsm' file. "
      . "Search roots: ".join(', ', @search_dirs).". "
      . "Searched locations: ".join(', ', @searched_paths).". "
      . "The semantic package lane currently resolves package sources beside the current source, through repeated '--path DIR' roots, through 'FSMLIB', or in the current directory."
      . $class->_formatted_docs_hint($args{docs_hint});
}

sub _formatted_docs_hint ($class, $docs_hint) {
    return "\n" unless defined($docs_hint) && length($docs_hint);
    return $docs_hint =~ /\n\z/ ? $docs_hint : "$docs_hint\n";
}

1;

__END__

=head1 METHODS

=head2 resolve_imports

Resolves one bounded package-import list into typed L<FSM::Package::Spec>
records using embedded package roots first and then the normal external source
search roots.

=head2 resolve_external_package_source_path

Searches the active package import roots for one external package source file
named C<package_name.fsm>.

=cut

perl/FSM/Package/Parser.pm:
package FSM::Package::Parser;

use v5.20;
use strict;
use warnings;
use Carp qw(confess);
use feature qw(signatures);
no warnings 'experimental::signatures';

use FSM::Adapter::FSMGenFull::ExpressionBuilder;
use FSM::Adapter::FSMGenFull::SignalManager;
use FSM::Package::DeclarativeTypeSupport;
use FSM::Package::DeclarativeSymbolResolver;
use FSM::Package::DeclarativeTypeResolver;
use FSM::Package::Spec;
use FSM::Package::SignalManagerProjectionSupport;
use FSM::Package::Symbols;

sub new ($class, %args) {
    return bless {
        debug => $args{debug} // 0,
    }, $class;
}

sub parse_source ($self, $raw_ast) {
    my $package_ast = $self->find_package_root($raw_ast);
    confess "Expected package source containing '?pkg:name'" unless $package_ast;
    return $self->parse_package_root($package_ast);
}

sub find_package_root ($self, $raw_ast) {
    return undef unless ref($raw_ast) eq 'ARRAY';

    if (@$raw_ast > 0 && !ref($raw_ast->[0]) && $raw_ast->[0] =~ /^\?pkg:/) {
        return _clone($raw_ast);
    }

    for my $ast_node (@$raw_ast) {
        next unless ref($ast_node) eq 'ARRAY';
        next unless @$ast_node > 0;
        next if ref($ast_node->[0]);
        return _clone($ast_node) if $ast_node->[0] =~ /^\?pkg:/;
    }

    return undef;
}

sub parse_package_root ($self, $package_ast) {
    my ($header, $children) = @$package_ast;
    my $package_name = $self->decode_package_name($header);

    $children ||= [];
    confess "Package '$package_name' must contain a child list" unless ref($children) eq 'ARRAY';

    my $symbols = FSM::Package::Symbols->new();
    my $symbol_manager = FSM::Adapter::FSMGenFull::SignalManager->new(
        debug => ($self->{debug} ? 1 : 0),
    );
    my $expression_builder = FSM::Adapter::FSMGenFull::ExpressionBuilder->new(
        debug => ($self->{debug} ? 1 : 0),
        signal_manager => $symbol_manager,
    );
    my @pending_constant_entries;
    my @pending_enum_entries;
    my @pending_type_entries;

    for my $child (@$children) {
        confess
            "Package '$package_name' contains a non-list child item, ".
            "but package child structure is blocked because every package child must be a real declaration block such as '+constants' or '+enums'."
            unless ref($child) eq 'ARRAY';
        confess
            "Package '$package_name' contains an empty child entry, ".
            "but package child structure is blocked because every package child must begin with a real string header such as '+constants' or '+enums'."
            unless @$child;
        my $child_header = $child->[0];
        confess
            "Package '$package_name' contains a child entry that does not begin with a string header, ".
            "but package child header shape is blocked because every package child must begin with a real string header such as '+constants' or '+enums'."
            if ref($child_header);

        if (defined($child_header) && $child_header eq '+constants') {
            push @pending_constant_entries, @{ $self->parse_package_constants_block(
                $package_name,
                $child,
                $symbols,
            ) };
            next;
        }

        if (defined($child_header) && $child_header eq '+enums') {
            push @pending_enum_entries, @{ $self->parse_package_enums_block(
                $package_name,
                $child,
                $symbols,
            ) };
            next;
        }

        if (defined($child_header) && $child_header eq '+types') {
            push @pending_type_entries, @{ $self->parse_package_types_block(
                $package_name,
                $child,
                $symbols,
            ) };
            next;
        }

        confess
            "Package '$package_name' contains child '$child_header', ".
            "but package child kind support is blocked because the active package parser currently accepts only '+constants', '+enums', and '+types'.";
    }

    $self->resolve_pending_package_symbols(
        $package_name,
        $symbols,
        $symbol_manager,
        $expression_builder,
        \@pending_constant_entries,
        \@pending_enum_entries,
    );

    $self->resolve_pending_package_types(
        $package_name,
        $symbols,
        $symbol_manager,
        \@pending_type_entries,
    );

    return FSM::Package::Spec->new(
        name => $package_name,
        symbols => $symbols,
        raw_ast => $package_ast,
    );
}

sub parse_package_constants_block ($self, $package_name, $child_ast, $symbols) {
    my (undef, $constants_list) = @$child_ast;

    confess
        "Package '$package_name' contains malformed '+constants' section, ".
        "but package symbol section shape is blocked because '+constants' currently requires a non-empty list of '(NAME value)' entries where the value is either a literal scalar, a non-empty list aggregate, or a non-empty hash-like aggregate."
        unless ref($constants_list) eq 'ARRAY' && @$constants_list;

    my @constant_entries;
    for my $constant_def (@$constants_list) {
        confess
            "Package '$package_name' contains malformed '+constants' entry, ".
            "but package symbol entry shape is blocked because each '+constants' entry must be a pair '(NAME value)'."
            unless ref($constant_def) eq 'ARRAY' && @$constant_def == 2;

        my ($name, $value) = @$constant_def;
        my $resolved_name = $self->unwrap_scalar_token($name);

        confess
            "Package '$package_name' contains malformed '+constants' entry for constant '".$self->describe_contract_name($resolved_name)."', ".
            "but package symbol token shape is blocked because each '+constants' entry must use an HDL-identifier-compatible name."
            unless $self->is_contract_identifier($resolved_name);

        push @constant_entries, {
            name => $resolved_name,
            value_ast => $value,
        };
    }

    $symbols->push_raw_block($child_ast);
    return \@constant_entries;
}

sub parse_package_enums_block ($self, $package_name, $child_ast, $symbols) {
    my (undef, $enums_list) = @$child_ast;

    confess
        "Package '$package_name' contains malformed '+enums' section, ".
        "but package symbol section shape is blocked because '+enums' currently requires a non-empty list of '(enum_name (MEMBER value) ...)' definitions."
        unless ref($enums_list) eq 'ARRAY' && @$enums_list;

    my @enum_entries;
    for my $enum_def (@$enums_list) {
        confess
            "Package '$package_name' contains malformed '+enums' definition, ".
            "but package symbol entry shape is blocked because each '+enums' definition must use the shape '(enum_name (MEMBER value) ...)'."
            unless ref($enum_def) eq 'ARRAY' && @$enum_def == 2;

        my ($enum_name, $members_list) = @$enum_def;
        my $resolved_enum_name = $self->unwrap_scalar_token($enum_name);

        confess
            "Package '$package_name' contains malformed '+enums' definition for enum '".$self->describe_contract_name($resolved_enum_name)."', ".
            "but package symbol token shape is blocked because each '+enums' definition must use an HDL-identifier-compatible enum name and at least one '(MEMBER value)' entry."
            unless $self->is_contract_identifier($resolved_enum_name)
                && ref($members_list) eq 'ARRAY'
                && @$members_list;

        my @member_entries;
        for my $member_def (@$members_list) {
            confess
                "Package '$package_name' contains malformed '+enums' member for enum '$resolved_enum_name', ".
                "but package symbol entry shape is blocked because each enum member must be a pair '(MEMBER value)'."
                unless ref($member_def) eq 'ARRAY' && @$member_def == 2;

            my ($member_name, $member_value) = @$member_def;
            my $resolved_member_name = $self->unwrap_scalar_token($member_name);
            my $resolved_member_value = $self->unwrap_scalar_token($member_value);

            confess
                "Package '$package_name' contains malformed '+enums' member '".$self->describe_contract_name($resolved_member_name)."' for enum '$resolved_enum_name', ".
                "but package symbol token shape is blocked because each enum member must use an HDL-identifier-compatible member name and a scalar value token."
                unless $self->is_contract_identifier($resolved_member_name)
                    && defined($resolved_member_value)
                    && !ref($resolved_member_value);

            push @member_entries, {
                name => $resolved_member_name,
                value_token => $resolved_member_value,
            };
        }

        push @enum_entries, {
            name => $resolved_enum_name,
            members => \@member_entries,
        };
    }

    $symbols->push_raw_block($child_ast);
    return \@enum_entries;
}

sub parse_package_types_block ($self, $package_name, $child_ast, $symbols) {
    my (undef, $types_list) = @$child_ast;

    confess
        "Package '$package_name' contains malformed '+types' section, ".
        "but package type section shape is blocked because '+types' currently requires a non-empty list of '(type NAME bit)', '(type NAME (bits N))', '(type NAME (signed bit))', '(type NAME (signed (bits N)))', '(type NAME (two_state ...))', '(type NAME (four_state ...))', '(type NAME (list ...))', '(type NAME (record (field TYPE) ...))', or '(type NAME other_type)' entries."
        unless ref($types_list) eq 'ARRAY' && @$types_list;

    my @type_entries;
    for my $type_def (@$types_list) {
        confess
            "Package '$package_name' contains malformed '+types' entry, ".
            "but package type entry shape is blocked because each '+types' entry must use the shape '(type NAME bit)', '(type NAME (bits N))', '(type NAME (signed bit))', '(type NAME (signed (bits N)))', '(type NAME (two_state ...))', '(type NAME (four_state ...))', '(type NAME (list ...))', '(type NAME (record (field TYPE) ...))', or '(type NAME other_type)'."
            unless ref($type_def) eq 'ARRAY' && @$type_def >= 2;

        my ($keyword, $name, $spec_ast);
        if (@$type_def >= 3) {
            ($keyword, $name) = @$type_def[0, 1];
            $spec_ast = @$type_def == 3
                ? $type_def->[2]
                : [ @$type_def[2 .. $#$type_def] ];
        } elsif (@$type_def == 2 && ref($type_def->[1]) eq 'ARRAY' && @{$type_def->[1]} >= 2) {
            $keyword = $type_def->[0];
            $name = $type_def->[1][0];
            $spec_ast = @{$type_def->[1]} == 2
                ? $type_def->[1][1]
                : [ @{$type_def->[1]}[1 .. $#{$type_def->[1]}] ];
        } else {
            confess
                "Package '$package_name' contains malformed '+types' entry, ".
                "but package type entry shape is blocked because each '+types' entry must use the shape '(type NAME bit)', '(type NAME (bits N))', '(type NAME (signed bit))', '(type NAME (signed (bits N)))', '(type NAME (two_state ...))', '(type NAME (four_state ...))', '(type NAME (list ...))', '(type NAME (record (field TYPE) ...))', or '(type NAME other_type)'.";
        }

        my $resolved_keyword = $self->unwrap_scalar_token($keyword);
        my $resolved_name = $self->unwrap_scalar_token($name);

        confess
            "Package '$package_name' contains malformed '+types' entry for type '".$self->describe_contract_name($resolved_name)."', ".
            "but package type token shape is blocked because each '+types' entry must begin with the literal keyword 'type' and use an HDL-identifier-compatible type name."
            unless defined($resolved_keyword)
                && !ref($resolved_keyword)
                && $resolved_keyword eq 'type'
                && $self->is_contract_identifier($resolved_name);

        push @type_entries, {
            name => $resolved_name,
            spec_ast => $spec_ast,
        };
    }

    $symbols->push_raw_block($child_ast);
    return \@type_entries;
}

sub resolve_pending_package_symbols ($self, $package_name, $symbols, $symbol_manager, $expression_builder, $constant_entries, $enum_entries) {
    $constant_entries ||= [];
    $enum_entries ||= [];
    return 1 unless @$constant_entries || @$enum_entries;

    FSM::Package::DeclarativeSymbolResolver->resolve_symbols(
        constant_entries => $constant_entries,
        enum_entries => $enum_entries,
        value_items => sub ($value_ast) { return $self->package_value_items($value_ast) },
        unwrap_scalar_token => sub ($value) { return $self->unwrap_scalar_token($value) },
        is_contract_identifier => sub ($value) { return $self->is_contract_identifier($value) },
        resolve_constant_payload => sub ($entry) {
            return $self->canonicalize_package_constant_payload(
                package_name => $package_name,
                section_header => '+constants',
                symbol_kind => 'constant',
                symbol_name => $entry->{name},
                value_ast => $entry->{value_ast},
                expression_builder => $expression_builder,
            );
        },
        resolve_enum_member_payload => sub ($enum_entry, $member_entry) {
            return $self->canonicalize_package_symbol_literal_payload(
                package_name => $package_name,
                section_header => '+enums',
                symbol_kind => 'enum member',
                symbol_name => $enum_entry->{name}.'.'.$member_entry->{name},
                value_token => $member_entry->{value_token},
                expression_builder => $expression_builder,
            );
        },
        store_constant => sub ($name, $payload) {
            $symbols->store_constant($name, $payload);
            FSM::Package::SignalManagerProjectionSupport->project_symbols_into_signal_manager(
                signal_manager => $symbol_manager,
                symbols => FSM::Package::Symbols->new(
                    constants => {
                        $name => $payload,
                    },
                ),
                expression_builder => $expression_builder,
            );
            return $payload;
        },
        store_enum => sub ($enum_name, $members_hashref) {
            $symbols->store_enum($enum_name, $members_hashref);
            FSM::Package::SignalManagerProjectionSupport->project_symbols_into_signal_manager(
                signal_manager => $symbol_manager,
                symbols => FSM::Package::Symbols->new(
                    enums => {
                        $enum_name => $members_hashref,
                    },
                ),
                expression_builder => $expression_builder,
            );
            return $members_hashref;
        },
        cycle_error => sub (%cycle) {
            my @chain = map {
                my $node_type = $_->{type} eq 'enum' ? 'enum' : 'constant';
                $node_type . " '" . ($_->{name} // 'unknown') . "'";
            } @{ $cycle{chain} || [] };

            confess
                "Package '$package_name' contains a declarative symbol dependency cycle, ".
                "but package symbol scope now resolves normal non-cyclic '+constants'/'+enums' references without depending on declaration order and still blocks cycles explicitly. ".
                "Cycle: ".join(' -> ', @chain).".";
        },
    );

    return 1;
}

sub resolve_pending_package_types ($self, $package_name, $symbols, $symbol_manager, $type_entries, %options) {
    $type_entries ||= [];
    return 1 unless @$type_entries;

    FSM::Package::DeclarativeTypeResolver->resolve_types(
        type_entries => $type_entries,
        type_ast_layout => $options{type_ast_layout} // 'lispish',
        unwrap_scalar_token => sub ($value) { return $self->unwrap_scalar_token($value) },
        unwrap_single_nested_list => sub ($value) { return $self->unwrap_single_nested_list($value) },
        is_contract_identifier => sub ($value) { return $self->is_contract_identifier($value) },
        resolve_type_spec => sub ($entry) {
            return $self->canonicalize_package_type_spec(
                package_name => $package_name,
                type_name => $entry->{name},
                spec_ast => $entry->{spec_ast},
                type_ast_layout => $options{type_ast_layout} // 'lispish',
                symbols => $symbols,
                signal_manager => $symbol_manager,
            );
        },
        store_type => sub ($type_name, $type_spec) {
            $symbols->store_type($type_name, $type_spec);
            FSM::Package::SignalManagerProjectionSupport->project_symbols_into_signal_manager(
                signal_manager => $symbol_manager,
                symbols => FSM::Package::Symbols->new(
                    types => {
                        $type_name => $type_spec,
                    },
                ),
            );
            return $type_spec;
        },
        cycle_error => sub (%cycle) {
            my @chain = map {
                "type '" . ($_->{name} // 'unknown') . "'";
            } @{ $cycle{chain} || [] };

            die
                "Package '$package_name' contains a declarative type dependency cycle, ".
                "but package type scope now resolves normal non-cyclic type aliases without depending on declaration order and still blocks cycles explicitly. ".
                "Cycle: ".join(' -> ', @chain).".\n";
        },
    );

    return 1;
}

sub decode_package_name ($self, $header) {
    return $1 if defined($header) && !ref($header) && $header =~ /\A\?pkg:([A-Za-z_]\w*)\z/;

    my $display = defined($header) ? (ref($header) ? ref($header) : $header) : 'undef';
    confess
        "Malformed package root '$display'. ".
        "The active contract expects '?pkg:package_name' with an HDL-identifier-compatible package name ([A-Za-z_]\\w*).";
}

sub unwrap_scalar_token ($self, $value) {
    my $unwrapped = $value;
    while (ref($unwrapped) eq 'ARRAY' && @$unwrapped == 1) {
        $unwrapped = $unwrapped->[0];
    }
    return $unwrapped;
}

sub unwrap_single_nested_list ($self, $value) {
    my $unwrapped = $value;
    while (ref($unwrapped) eq 'ARRAY' && @$unwrapped == 1 && ref($unwrapped->[0]) eq 'ARRAY') {
        $unwrapped = $unwrapped->[0];
    }
    return $unwrapped;
}

sub is_contract_identifier ($self, $value) {
    return defined($value)
        && !ref($value)
        && $value =~ /\A[A-Za-z_]\w*\z/;
}

sub describe_contract_name ($self, $value) {
    return defined($value) && !ref($value) ? $value : 'unknown';
}

sub is_contract_type_reference ($self, $value) {
    return defined($value)
        && !ref($value)
        && $value =~ /\A(?:[A-Za-z_]\w*)(?:\.[A-Za-z_]\w*)?\z/;
}

sub canonicalize_package_type_spec ($self, %args) {
    my $package_name = $args{package_name} // 'package';
    my $type_name = $args{type_name} // 'unknown';
    my $spec_ast = $args{spec_ast};
    my $symbols = $args{symbols};
    my $signal_manager = $args{signal_manager};

    my $resolved_spec = FSM::Package::DeclarativeTypeSupport->canonicalize_type_spec(
        spec_ast => $spec_ast,
        type_ast_layout => $args{type_ast_layout} // 'lispish',
        unwrap_scalar_token => sub ($value) { return $self->unwrap_scalar_token($value) },
        unwrap_single_nested_list => sub ($value) { return $self->unwrap_single_nested_list($value) },
        is_contract_type_reference => sub ($value) { return $self->is_contract_type_reference($value) },
        resolve_type_reference => sub ($type_ref) {
            my $resolved_from_symbols = (
                $symbols && $self->is_contract_type_reference($type_ref)
                    ? $symbols->resolve_type($type_ref)
                    : undef
            );
            return $resolved_from_symbols if $resolved_from_symbols;

            return (
                $signal_manager && $self->is_contract_type_reference($type_ref)
                    ? $signal_manager->resolve_type($type_ref)
                    : undef
            );
        },
        resolve_positive_integer_width_symbol => sub ($width_symbol) {
            return (
                $symbols && $symbols->can('resolve_positive_integer_width_symbol')
                    ? $symbols->resolve_positive_integer_width_symbol($width_symbol)
                    : undef
            );
        },
        is_contract_identifier => sub ($value) { return $self->is_contract_identifier($value) },
    );
    return $resolved_spec if $resolved_spec;

    die
        "Package '$package_name' contains malformed '+types' entry for type '$type_name', ".
        "but the first active '+types' lane supports 'bit', '(bits N)', '(bits WIDTH_SYMBOL)', '(signed bit)', '(signed (bits N))', '(signed (bits WIDTH_SYMBOL))', '(two_state ...)', '(four_state ...)', '(list ...)', '(record (field TYPE) ...)', or aliases to already-resolved local/imported types.\n";
}

sub canonicalize_package_symbol_literal_payload ($self, %args) {
    my $package_name = $args{package_name} // 'package';
    my $section_header = $args{section_header} // '+symbols';
    my $symbol_kind = $args{symbol_kind} // 'symbol';
    my $symbol_name = $args{symbol_name} // 'unknown';
    my $value_token = $args{value_token};
    my $expression_builder = $args{expression_builder};

    my $literal_expr = eval {
        $expression_builder->parse_scalar_expression($value_token);
    };
    my $parse_error = $@;

    confess
        "Package '$package_name' contains '$section_header' entry for $symbol_kind '$symbol_name' with value token '$value_token', ".
        "but package symbol literal support is blocked because package symbol values currently must resolve to literal scalar values such as '0', '8'3', '8'hA5', or 'const_8b0'."
        if $parse_error || ref($literal_expr) ne 'FSM::CoreAST::Literal';

    return $literal_expr->to_systemverilog;
}

sub canonicalize_package_constant_payload ($self, %args) {
    my $package_name = $args{package_name} // 'package';
    my $section_header = $args{section_header} // '+constants';
    my $symbol_kind = $args{symbol_kind} // 'constant';
    my $symbol_name = $args{symbol_name} // 'unknown';
    my $value_ast = $args{value_ast};
    my $expression_builder = $args{expression_builder};

    my $scalar_value = $self->unwrap_scalar_token($value_ast);
    if (defined($scalar_value) && !ref($scalar_value)) {
        my $payload = $self->canonicalize_package_symbol_literal_payload(
            %args,
            value_token => $scalar_value,
        );
        return {
            kind => 'scalar',
            payload => $payload,
        };
    }

    confess
        "Package '$package_name' contains '$section_header' entry for $symbol_kind '$symbol_name', ".
        "but package aggregate value support is blocked because that value is neither a scalar literal nor a real aggregate list/hash payload."
        unless ref($value_ast) eq 'ARRAY';

    confess
        "Package '$package_name' contains '$section_header' entry for $symbol_kind '$symbol_name' with an empty aggregate value, ".
        "but package aggregate value support is blocked because aggregate package values must be non-empty lists or non-empty hash-like member sets."
        unless @$value_ast;

    my $value_items = $self->package_value_items($value_ast);

    confess
        "Package '$package_name' contains '$section_header' entry for $symbol_kind '$symbol_name' with an empty aggregate value, ".
        "but package aggregate value support is blocked because aggregate package values must be non-empty lists or non-empty hash-like member sets."
        unless @$value_items;

    my $hash_like_entries = 0;
    my $non_hash_entries = 0;
    for my $entry (@$value_items) {
        my $member_name = (ref($entry) eq 'ARRAY' && @$entry == 2)
            ? $self->unwrap_scalar_token($entry->[0])
            : undef;
        if (defined($member_name) && $self->is_contract_identifier($member_name)) {
            $hash_like_entries++;
        } else {
            $non_hash_entries++;
        }
    }

    if ($hash_like_entries && !$non_hash_entries) {
        my %members;
        my @member_order;
        for my $entry (@$value_items) {
            my ($member_name_ast, $member_value_ast) = @$entry;
            my $member_name = $self->unwrap_scalar_token($member_name_ast);
            confess
                "Package '$package_name' contains '$section_header' entry for $symbol_kind '$symbol_name' with duplicate member '$member_name', ".
                "but package aggregate packing is blocked because hash-like aggregate values must use each member name at most once so one packed member order remains unambiguous."
                if exists $members{$member_name};
            push @member_order, $member_name;
            $members{$member_name} = $self->canonicalize_package_constant_payload(
                package_name => $package_name,
                section_header => $section_header,
                symbol_kind => "$symbol_kind member",
                symbol_name => $symbol_name.'.'.$member_name,
                value_ast => $member_value_ast,
                expression_builder => $expression_builder,
            );
        }

        return {
            kind => 'map',
            member_order => \@member_order,
            members => \%members,
        };
    }

    confess
        "Package '$package_name' contains '$section_header' entry for $symbol_kind '$symbol_name' with a mixed aggregate value, ".
        "but package aggregate value support is blocked because list-style and hash-style aggregate entries cannot be mixed in one package value."
        if $hash_like_entries && $non_hash_entries;

    my @items;
    for my $index (0 .. $#$value_items) {
        push @items, $self->canonicalize_package_constant_payload(
            package_name => $package_name,
            section_header => $section_header,
            symbol_kind => "$symbol_kind item",
            symbol_name => $symbol_name."[$index]",
            value_ast => $value_items->[$index],
            expression_builder => $expression_builder,
        );
    }

    return {
        kind => 'list',
        items => \@items,
    };
}

sub package_value_items ($self, $value_ast) {
    my $cursor = $value_ast;

    while (ref($cursor) eq 'ARRAY' && @$cursor == 1 && ref($cursor->[0]) eq 'ARRAY') {
        $cursor = $cursor->[0];
    }

    my @items;
    while (1) {
        if (!ref($cursor)) {
            push @items, $cursor if defined $cursor;
            last;
        }

        if (ref($cursor) eq 'ARRAY' && @$cursor == 1) {
            push @items, $cursor->[0] if defined $cursor->[0];
            last;
        }

        if (ref($cursor) eq 'ARRAY' && @$cursor == 2) {
            push @items, $cursor->[0];
            $cursor = $cursor->[1];
            next;
        }

        if (ref($cursor) eq 'ARRAY') {
            push @items, @$cursor;
            last;
        }

        push @items, $cursor;
        last;
    }

    return \@items;
}

sub _clone ($value) {
    return [map { _clone($_) } @$value] if ref($value) eq 'ARRAY';
    return {map { $_ => _clone($value->{$_}) } keys %$value} if ref($value) eq 'HASH';
    return $value;
}

1;

perl/FSM/Pipeline/SourceFrontend.pm:
package FSM::Pipeline::SourceFrontend;

=head1 NAME

FSM::Pipeline::SourceFrontend - Frontend owner for source parsing and semantic module creation

=head1 DESCRIPTION

Owns the bounded source-frontend family that was still sitting inline in
C<FSM::Pipeline::HDLGenerator>. This package parses one C<.fsm> file with the
Lispish reader, classifies the top-level source kind, parses composition
sources into typed composition specs, and turns direct-root raw AST into the
semantic FSM/DT module used by later pipeline stages.

=cut

use v5.20;
use strict;
use warnings;
use Carp qw(confess);
use feature qw(signatures);
no warnings 'experimental::signatures';

use Data::Dumper;
use FSM::Adapter::FSMGenFull;
use FSM::Adapter::FSMGenFull::ExpressionBuilder;
use FSM::Adapter::FSMGenFull::SignalManager;
use FSM::Composition::Parser;
use FSM::Debug;
use FSM::Package::ImportResolver;
use FSM::Package::SignalManagerProjectionSupport;
use FSM::SourceClassifier;
use FSM::SourcePathResolver;
use FSM::Support::DocumentationHints qw(
    package_boundary_hint
    strict_mode_boundary_hint
    supported_boundary_hint
);
use Lispish;

sub parse_fsm_file ($class, %args) {
    my $fsm_file = $args{fsm_file}
        or confess "SourceFrontend requires an fsm_file";
    my $debug_level = $args{debug_level} // 0;

    my $source_text = $class->_slurp_fsm_file($fsm_file);
    return $class->parse_fsm_source(
        source_text => $source_text,
        source_label => $fsm_file,
        debug_level => $debug_level,
    );
}

sub parse_fsm_source ($class, %args) {
    my $source_text = $args{source_text};
    my $source_label = $args{source_label} // 'in-memory .fsm source';
    my $debug_level = $args{debug_level} // 0;
    confess "SourceFrontend parse_fsm_source requires scalar source_text"
        unless defined($source_text) && !ref($source_text) && length($source_text);
    confess "SourceFrontend parse_fsm_source requires scalar source_label"
        unless defined($source_label) && !ref($source_label) && length($source_label);
    my %allowed = map { $_ => 1 } qw(source_text source_label debug_level);
    my @unknown = sort grep { !$allowed{$_} } keys %args;
    confess "SourceFrontend parse_fsm_source received unknown argument(s): "
        . join(', ', @unknown) if @unknown;

    fsm_trace_enter('Parse FSM source with Lispish', 2);
    fsm_debug("Parsing FSM source '$source_label' with Lispish parser", 1);

    my $prepared_source_text = $class->_protect_braces_inside_slash_tokens($source_text);

    my $raw_ast = Lispish::multi(\$prepared_source_text);

    $class->_restore_preserved_slash_token_braces($raw_ast);

    unless ($raw_ast) {
        fsm_error("Lispish parser returned undefined AST for '$source_label'");
        confess "Error: Failed to parse FSM file with Lispish\n";
    }

    if ($debug_level > 0) {
        fsm_debug("Raw AST structure:", 2);
        if ($debug_level >= 3) {
            local $Data::Dumper::Maxdepth = 0;
            local $Data::Dumper::Indent = 1;
            my $dumped = Dumper($raw_ast);
            fsm_debug("Full raw AST dump:\n$dumped", 3);
        }
    }

    fsm_debug("FSM source parsed successfully", 1);
    fsm_trace_exit('FSM source parsed', 2);
    return $raw_ast;
}

sub _slurp_fsm_file ($class, $fsm_file) {
    open my $fh, '<', $fsm_file
        or confess "Error: Failed to open FSM file '$fsm_file': $!";
    local $/;
    my $source_text = <$fh>;
    close $fh
        or confess "Error: Failed to close FSM file '$fsm_file': $!";

    unless (defined $source_text && length $source_text) {
        die "Error: Source file '$fsm_file' is empty. Provide a non-empty FSMGen source file.\n";
    }

    return $source_text;
}

sub _protect_braces_inside_slash_tokens ($class, $source_text) {
    my $left_placeholder = $class->_slash_token_left_brace_placeholder;
    my $right_placeholder = $class->_slash_token_right_brace_placeholder;

    if (index($source_text, $left_placeholder) >= 0 || index($source_text, $right_placeholder) >= 0) {
        confess "Internal error: slash-token brace-preservation placeholder collision in FSM source";
    }

    my $protected = q{};
    my $index = 0;
    my $length = length($source_text);

    while ($index < $length) {
        my ($token, $end_index) = $class->_consume_slash_token($source_text, $index);
        if (defined $token) {
            $token =~ s/\{/$left_placeholder/g;
            $token =~ s/\}/$right_placeholder/g;
            $protected .= $token;
            $index = $end_index + 1;
            next;
        }

        $protected .= substr($source_text, $index, 1);
        $index++;
    }

    return $protected;
}

sub _consume_slash_token ($class, $source_text, $start_index) {
    return unless substr($source_text, $start_index, 1) eq '/';

    my $previous = $start_index > 0 ? substr($source_text, $start_index - 1, 1) : q{};
    return unless !length($previous) || $previous =~ /[\s\("\']/;

    my $length = length($source_text);
    my $slash_count = 0;
    my $end_index = undef;

    for (my $cursor = $start_index; $cursor < $length; $cursor++) {
        my $char = substr($source_text, $cursor, 1);
        next unless $char eq '/';

        $slash_count++;
        if ($slash_count == 3) {
            $end_index = $cursor;
            last;
        }
    }

    return unless defined $end_index;

    my $following = $end_index + 1 < $length ? substr($source_text, $end_index + 1, 1) : q{};
    return unless !length($following) || $following =~ /[\s\)"\';]/;

    return (substr($source_text, $start_index, $end_index - $start_index + 1), $end_index);
}

sub _restore_preserved_slash_token_braces ($class, $raw_ast) {
    return unless defined $raw_ast;

    if (ref($raw_ast) eq 'ARRAY') {
        for my $item (@$raw_ast) {
            if (ref($item)) {
                $class->_restore_preserved_slash_token_braces($item);
                next;
            }

            next unless defined $item;
            $item =~ s/\Q@{[$class->_slash_token_left_brace_placeholder]}\E/\{/g;
            $item =~ s/\Q@{[$class->_slash_token_right_brace_placeholder]}\E/\}/g;
        }
    }
}

sub _slash_token_left_brace_placeholder ($class) {
    return '__FSMGEN_SLASH_TOKEN_LBRACE_PLACEHOLDER_7AF5A6B7__';
}

sub _slash_token_right_brace_placeholder ($class) {
    return '__FSMGEN_SLASH_TOKEN_RBRACE_PLACEHOLDER_7AF5A6B7__';
}

sub classify_source_ast ($class, $raw_ast) {
    my $source_info = FSM::SourceClassifier::classify_source_ast($raw_ast);
    return $class->_augment_source_info_package_import_summary(
        raw_ast => $raw_ast,
        source_info => $source_info,
    );
}

sub parse_composition_source ($class, %args) {
    my $raw_ast = $args{raw_ast}
        or confess "SourceFrontend requires a raw_ast";
    my $debug_level = $args{debug_level} // 0;

    my $parser = FSM::Composition::Parser->new(
        debug => ($debug_level > 0),
    );
    return $parser->parse_source($raw_ast);
}

sub _augment_source_info_package_import_summary ($class, %args) {
    my $source_info = _clone($args{source_info} || {});
    my $package_imports = $class->_safe_source_package_imports(
        raw_ast => $args{raw_ast},
        source_info => $source_info,
    );
    return $source_info unless defined $package_imports;

    $source_info->{package_import_names} = [ @$package_imports ];
    $source_info->{package_import_count} = scalar(@$package_imports);
    return $source_info;
}

sub _safe_source_package_imports ($class, %args) {
    my $source_info = $args{source_info} || {};
    my $kind = $source_info->{kind} // '';

    if ($kind eq 'fsm' || $kind eq 'dt') {
        return $class->_safe_direct_root_package_imports(%args);
    }
    if ($kind eq 'composition') {
        return $class->_safe_composition_package_imports(%args);
    }
    if ($kind eq 'package') {
        return [];
    }

    return undef;
}

sub _safe_direct_root_package_imports ($class, %args) {
    my $source_info = $args{source_info}
        || FSM::SourceClassifier::classify_source_ast($args{raw_ast});
    my $body_items = $class->_direct_root_body_items(
        raw_ast => $args{raw_ast},
        source_info => $source_info,
    );
    return undef unless $body_items;

    my @package_imports;
    my $saw_import_block = 0;
    for my $item (@$body_items) {
        next unless ref($item) eq 'ARRAY';
        next unless defined($item->[0]) && !ref($item->[0]) && $item->[0] eq '+import';
        $saw_import_block = 1;

        my $imports_list = $item->[1];
        return undef unless ref($imports_list) eq 'ARRAY' && @$imports_list;

        for my $package_name (@$imports_list) {
            my $resolved_name = $class->_unwrap_scalar_token($package_name);
            return undef unless defined($resolved_name) && !ref($resolved_name) && $resolved_name =~ /\A[A-Za-z_]\w*\z/;
            push @package_imports, $resolved_name;
        }
    }

    return [] unless $saw_import_block;
    return \@package_imports;
}

sub _safe_composition_package_imports ($class, %args) {
    my $source_info = $args{source_info}
        || FSM::SourceClassifier::classify_source_ast($args{raw_ast});
    my $body_items = $class->_composition_body_items(
        raw_ast => $args{raw_ast},
        source_info => $source_info,
    );
    return undef unless $body_items;

    my @package_imports;
    my $saw_import_block = 0;
    for my $item (@$body_items) {
        next unless ref($item) eq 'ARRAY';
        next unless defined($item->[0]) && !ref($item->[0]) && $item->[0] eq '+import';
        $saw_import_block = 1;

        my $imports_list = $item->[1];
        return undef unless ref($imports_list) eq 'ARRAY' && @$imports_list;

        for my $package_name (@$imports_list) {
            my $resolved_name = $class->_unwrap_scalar_token($package_name);
            return undef unless defined($resolved_name) && !ref($resolved_name) && $resolved_name =~ /\A[A-Za-z_]\w*\z/;
            push @package_imports, $resolved_name;
        }
    }

    return [] unless $saw_import_block;
    return \@package_imports;
}

sub enforce_strict_source_boundary ($class, %args) {
    return unless $args{strict_mode};

    my $source_info = $args{source_info}
        || $class->classify_source_ast($args{raw_ast});
    my $header = $source_info->{header} // '';
    my $source_label = $args{source_label} // ($header || 'source');

    if ($header eq '+fsm') {
        confess
            "Strict mode rejects the legacy '+fsm' root family for source '$source_label'. "
          . "Use the modern '?fsm:module_name' root form instead of '+fsm', "
          . "or re-run without strict mode if you need legacy compatibility. "
          . strict_mode_boundary_hint();
    }

    if ($header =~ /^\?module:/) {
        confess
            "Strict mode rejects the legacy '?module:' direct-root alias for source '$source_label'. "
          . "Use the canonical '?mod:module_name' root form for module/entity-architecture roots, "
          . "or re-run without strict mode if you need compatibility with the current shared implementation path. "
          . strict_mode_boundary_hint();
    }

    return if $header =~ /^\?mod:/;

    my $body_items = $class->_direct_root_body_items(
        raw_ast => $args{raw_ast},
        source_info => $source_info,
    );
    if ($body_items) {
        for my $item (@$body_items) {
            next unless $class->_is_legacy_empty_size_section($item);

            confess
                "Strict mode rejects the legacy empty '(+size)' section in source '$source_label'. "
              . "Remove the empty section or replace it with explicit '(+size (signal width) ...)' entries, "
              . "or re-run without strict mode if you need legacy compatibility. "
              . strict_mode_boundary_hint();
        }

        for my $item (@$body_items) {
            my $reset_issue = $class->_strict_system_reset_contract_issue($item);
            next unless $reset_issue;

            confess
                "Strict mode rejects the legacy or misleading '$reset_issue->{form}' +system spelling in source '$source_label'. "
              . "Use '(sreset reset)' for synchronous active-high reset or '(areset rst_n)' for asynchronous active-low reset, "
              . "or re-run without strict mode if you need legacy compatibility. "
              . strict_mode_boundary_hint();
        }

        for my $item (@$body_items) {
            next unless $class->_is_legacy_compact_init_directive($item);

            confess
                "Strict mode rejects the legacy compact '(:= signal=value)' top-level directive in source '$source_label'. "
              . "Use the canonical '(:= (signal value))' form for strict-mode init/default metadata, "
              . "or re-run without strict mode if you still need the compact ':=' surface. "
              . strict_mode_boundary_hint();
        }

        if (my $lteplus_issue = $class->_find_strict_legacy_lteplus_assignment_issue($body_items)) {
            confess
                "Strict mode rejects legacy '<=+' assignment '$lteplus_issue->{display}' in source '$source_label'. "
              . "Use the preferred '<=-' pair form '$lteplus_issue->{canonical_hint}' for strict-mode D-input dual-output assignment intent, "
              . "or re-run without strict mode if you still need '<=+' compatibility. "
              . strict_mode_boundary_hint();
        }

        if (my $infix_issue = $class->_find_strict_infix_assignment_issue($body_items)) {
            confess
                "Strict mode rejects infix assignment '$infix_issue->{display}' in source '$source_label'. "
              . "Use the canonical pair form '$infix_issue->{canonical_hint}' for strict-mode assignment intent, "
              . "or re-run without strict mode if you still need infix assignment compatibility. "
              . strict_mode_boundary_hint();
        }

    }

    my $composition_body_items = $class->_composition_body_items(
        raw_ast => $args{raw_ast},
        source_info => $source_info,
    );
    if ($composition_body_items) {
        if (my $slash_link_issue = $class->_find_strict_composition_wiring_slash_link_issue($composition_body_items)) {
            confess
                "Strict mode rejects legacy '?wiring' slash-link token '$slash_link_issue->{token}' in source '$source_label'. "
              . "Use the canonical '$slash_link_issue->{canonical_hint}' form or verbose '$slash_link_issue->{verbose_hint}' form for strict-mode composition wiring, "
              . "or re-run without strict mode if you still need '/source/target/' compatibility. "
              . strict_mode_boundary_hint();
        }
    }
}

sub enforce_strict_generated_child_source_boundary ($class, %args) {
    return unless $args{strict_mode};

    my $declared_child_kind = $args{declared_child_kind}
        or confess "SourceFrontend requires a declared_child_kind";
    my $source_info = $args{source_info}
        || $class->classify_source_ast($args{raw_ast});
    my $header = $source_info->{header} // '';
    my $source_label = $args{source_label} // ($header || 'source');

    if ($declared_child_kind eq '?fsmc' && $header eq '+fsm') {
        confess
            "Strict mode rejects the legacy '+fsm' root family as the root of '$declared_child_kind' source '$source_label'. "
          . "Use the canonical '?fsm:source_name' root form for FSM child sources, "
          . "or re-run without strict mode if you need legacy compatibility. "
          . strict_mode_boundary_hint();
    }

    if ($declared_child_kind eq '?dtc' && $header =~ /^\?(?:mod|module):/) {
        confess
            "Strict mode rejects '$header' as the root of '$declared_child_kind' source '$source_label'. "
          . "Use the canonical '?dt:source_name' root form for standalone-DT child sources, "
          . "or re-run without strict mode if you need compatibility with the current shared implementation path. "
          . strict_mode_boundary_hint();
    }
}

sub create_fsm_module ($class, %args) {
    my $raw_ast = $args{raw_ast}
        or confess "SourceFrontend requires a raw_ast";
    my $debug_level = $args{debug_level} // 0;
    my $source_info = $args{source_info}
        || $class->classify_source_ast($raw_ast);
    my $source_header = $source_info->{header} // 'direct source';
    my $source_path_resolver = $args{source_path_resolver}
        // FSM::SourcePathResolver->new();
    my $frontend_context = ref($args{frontend_context}) eq 'HASH'
        ? $args{frontend_context}
        : undef;

    $class->enforce_strict_source_boundary(
        raw_ast => $raw_ast,
        strict_mode => ($args{strict_mode} // 0),
        source_label => $args{source_label},
    );

    fsm_trace_enter('Build semantic FSM module from raw AST', 2);
    fsm_debug("Creating semantic FSM module from raw AST", 1);

    my $signal_manager = FSM::Adapter::FSMGenFull::SignalManager->new(
        debug => ($debug_level > 0),
    );
    my $package_imports = $class->_direct_root_package_imports(
        raw_ast => $raw_ast,
        source_info => $source_info,
        source_label => ($args{source_label} // $source_header),
    );
    my $resolved_package_imports = {};
    if (@$package_imports) {
        $resolved_package_imports = FSM::Package::ImportResolver->resolve_imports(
            package_imports => $package_imports,
            embedded_package_sources => $class->collect_embedded_package_sources($raw_ast),
            fsm_file => $args{fsm_file},
            source_path_resolver => $source_path_resolver,
            owner_label => "Direct source '$source_header'" . (
                defined($args{fsm_file}) && length($args{fsm_file})
                    ? " in '$args{fsm_file}'"
                    : ''
            ),
            debug_level => $debug_level,
            docs_hint => ' ' . package_boundary_hint(),
        );
        $class->_import_package_symbols_into_signal_manager(
            signal_manager => $signal_manager,
            resolved_package_imports => $resolved_package_imports,
            package_imports => $package_imports,
            debug_level => $debug_level,
        );
    }

    my $adapter = FSM::Adapter::FSMGenFull->new(
        debug => ($debug_level > 0),
        signal_manager => $signal_manager,
    );

    my $fsm_module;
    eval {
        $fsm_module = $adapter->parse_fsm($raw_ast);
    };

    if ($@) {
        fsm_trace_decision(0, 'Adapter parse_fsm() raised exception', 1);
        confess "Error parsing FSM with adapter: $@\n";
    }

    unless ($fsm_module) {
        fsm_error('Adapter parse_fsm() returned undefined module');
        confess "Error: Failed to create FSM module\n";
    }

    if ($debug_level > 1 && $fsm_module) {
        fsm_debug("Semantic FSM module created successfully", 1);
        if ($debug_level >= 3) {
            local $Data::Dumper::Maxdepth = 0;
            local $Data::Dumper::Indent = 1;
            my $dumped = Dumper($fsm_module);
            fsm_debug("Full FSM module AST dump:\n$dumped", 3);
        }
    }

    if (@$package_imports) {
        $fsm_module->{attributes}{package_imports} = [ @$package_imports ];
    }
    if ($frontend_context) {
        $frontend_context->{package_imports} = [ @$package_imports ];
        $frontend_context->{resolved_package_imports} = $resolved_package_imports;
    }

    fsm_debug("FSM module created successfully", 1);
    fsm_trace_exit('Semantic FSM module created', 2);
    return $fsm_module;
}

sub _direct_root_body_items ($class, %args) {
    my $raw_ast = $args{raw_ast};
    return undef unless ref($raw_ast) eq 'ARRAY';

    my $source_info = $args{source_info}
        || $class->classify_source_ast($raw_ast);
    my $kind = $source_info->{kind} // '';
    return undef unless $kind eq 'fsm' || $kind eq 'dt';

    my $header = $source_info->{header} // '';

    if (@$raw_ast > 0 && !ref($raw_ast->[0])) {
        if ($header =~ /^\?(?:fsm|dt|mod|module):/) {
            return ref($raw_ast->[1]) eq 'ARRAY' ? _clone($raw_ast->[1]) : undef;
        }

        if ($header eq '+fsm' && ref($raw_ast->[1]) eq 'ARRAY') {
            my @body = @{$raw_ast->[1]} > 1 ? @{$raw_ast->[1]}[1 .. $#{$raw_ast->[1]}] : ();
            return _clone(\@body);
        }
    }

    if (@$raw_ast > 0 && ref($raw_ast->[0]) eq 'ARRAY') {
        my $first = $raw_ast->[0];
        my $first_header = $first->[0];

        if (defined($first_header) && !ref($first_header) && $first_header =~ /^\?(?:fsm|dt|mod|module):/) {
            return ref($first->[1]) eq 'ARRAY' ? _clone($first->[1]) : undef;
        }

        if (defined($first_header) && !ref($first_header) && $first_header eq '+fsm') {
            if (@$raw_ast == 1) {
                my $payload = $first->[1];
                return [] unless ref($payload) eq 'ARRAY';
                my @body = @$payload > 1 ? @$payload[1 .. $#$payload] : ();
                return _clone(\@body);
            }

            my @body = @$raw_ast > 1 ? @$raw_ast[1 .. $#$raw_ast] : ();
            return _clone(\@body);
        }
    }

    return undef;
}

sub _composition_body_items ($class, %args) {
    my $raw_ast = $args{raw_ast};
    return undef unless ref($raw_ast) eq 'ARRAY';

    my $source_info = $args{source_info}
        || FSM::SourceClassifier::classify_source_ast($raw_ast);
    return undef unless ($source_info->{kind} // '') eq 'composition';

    my $header = $source_info->{header} // '';

    if (@$raw_ast > 0 && !ref($raw_ast->[0]) && $raw_ast->[0] eq $header) {
        return _clone($raw_ast->[1]) if @$raw_ast > 1 && ref($raw_ast->[1]) eq 'ARRAY';
    }

    for my $ast_node (@$raw_ast) {
        next unless ref($ast_node) eq 'ARRAY' && @$ast_node > 1;
        next if ref($ast_node->[0]);
        next unless $ast_node->[0] eq $header;
        return _clone($ast_node->[1]) if ref($ast_node->[1]) eq 'ARRAY';
    }

    return undef;
}

sub _is_legacy_empty_size_section ($class, $node) {
    return 0 unless ref($node) eq 'ARRAY';
    return 0 unless defined($node->[0]) && !ref($node->[0]) && $node->[0] eq '+size';
    return 1 if @$node == 1;
    return 1 if @$node == 2 && !defined($node->[1]);
    return 0;
}

sub _strict_system_reset_contract_issue ($class, $node) {
    return 0 unless ref($node) eq 'ARRAY';
    return 0 unless defined($node->[0]) && !ref($node->[0]) && $node->[0] eq '+system';
    return 0 unless ref($node->[1]) eq 'ARRAY';

    for my $entry (@{$node->[1]}) {
        next unless ref($entry) eq 'ARRAY';
        next unless defined($entry->[0]) && !ref($entry->[0]);
        my ($directive, $name) = @$entry;
        next unless defined($directive) && !ref($directive);
        next unless $directive eq 'sreset' || $directive eq 'areset' || $directive eq 'asreset';
        my @arguments = ref($name) eq 'ARRAY' ? @$name : ($name);
        my $unwrapped_name = $class->_unwrap_scalar_token($arguments[0]);
        my $reset_name = defined($unwrapped_name) && !ref($unwrapped_name) ? $unwrapped_name : 'unknown';
        my $form = "($directive $reset_name)";

        return { form => $form, reason => 'legacy_asreset_alias' }
            if $directive eq 'asreset';
        # Naming heuristics belong to the legacy two-token forms. Explicit
        # polarity and malformed extended declarations are checked by the parser.
        next if @$entry != 2 || @arguments != 1;
        return { form => $form, reason => 'active_high_name_looks_active_low' }
            if $directive eq 'sreset' && $class->_looks_active_low_reset_name($reset_name);
        return { form => $form, reason => 'active_low_name_does_not_look_active_low' }
            if $directive eq 'areset' && !$class->_looks_active_low_reset_name($reset_name);
    }

    return 0;
}

sub _looks_active_low_reset_name ($class, $reset_name) {
    return defined($reset_name)
        && $reset_name =~ /(?:_n|n)\z/i;
}

sub _is_legacy_compact_init_directive ($class, $node) {
    return 0 unless ref($node) eq 'ARRAY';
    return 0 unless defined($node->[0]) && !ref($node->[0]) && $node->[0] eq ':=';
    for my $payload (@$node[1 .. $#$node]) {
        my $unwrapped = $class->_unwrap_scalar_token($payload);
        return 1
            if defined($unwrapped)
                && !ref($unwrapped)
                && $unwrapped =~ /\A[A-Za-z_]\w*=.+\z/;
    }
    return 0;
}

sub _find_strict_legacy_lteplus_assignment_issue ($class, $node) {
    return undef unless ref($node) eq 'ARRAY';

    if (my $issue = $class->_strict_legacy_lteplus_assignment_issue_for_action($node)) {
        return $issue;
    }

    for my $child (@$node) {
        next unless ref($child) eq 'ARRAY';
        if (my $issue = $class->_find_strict_legacy_lteplus_assignment_issue($child)) {
            return $issue;
        }
    }

    return undef;
}

sub _strict_legacy_lteplus_assignment_issue_for_action ($class, $node) {
    return undef unless ref($node) eq 'ARRAY' && @$node >= 2;

    my $head = $class->_unwrap_scalar_token($node->[0]);
    if (defined($head) && !ref($head) && $head eq '<=+') {
        my ($target, $rhs) = $class->_assignment_pair_target_and_rhs($node);
        return {
            operator => '<=+',
            target => $target,
            rhs => $rhs,
            display => $class->_render_lispish_node($node),
            canonical_hint => $class->_render_canonical_assignment_pair_hint('<=-', $target, $rhs),
        };
    }

    my ($target, $spec) = @$node[0, 1];
    return undef if defined($target) && !ref($target) && $class->_is_assignment_operator_token($target);
    return undef if defined($target) && !ref($target) && $target =~ /\A</;
    return undef unless $class->_is_strict_infix_assignment_target($target);
    return undef unless ref($spec) eq 'ARRAY' && @$spec >= 2;

    my $operator = $class->_unwrap_scalar_token($spec->[0]);
    return undef unless defined($operator) && !ref($operator) && $operator eq '<=+';

    my $rhs = $class->_unwrap_scalar_token($spec->[1]);
    return {
        operator => '<=+',
        target => $target,
        rhs => $rhs,
        display => $class->_render_infix_assignment_action($target, $spec),
        canonical_hint => $class->_render_canonical_assignment_pair_hint('<=-', $target, $rhs),
    };
}

sub _assignment_pair_target_and_rhs ($class, $node) {
    my $payload = $node->[1];
    if (ref($payload) eq 'ARRAY' && @$payload == 1 && ref($payload->[0]) eq 'ARRAY') {
        $payload = $payload->[0];
    }

    if (ref($payload) eq 'ARRAY' && @$payload >= 2) {
        return ($payload->[0], $payload->[1]);
    }

    return ($node->[1], $node->[2]) if @$node >= 3;

    return ($node->[1], undef);
}

sub _find_strict_infix_assignment_issue ($class, $node) {
    return undef unless ref($node) eq 'ARRAY';

    if (my $issue = $class->_strict_infix_assignment_issue_for_action($node)) {
        return $issue;
    }

    for my $child (@$node) {
        next unless ref($child) eq 'ARRAY';
        if (my $issue = $class->_find_strict_infix_assignment_issue($child)) {
            return $issue;
        }
    }

    return undef;
}

sub _find_strict_composition_wiring_slash_link_issue ($class, $node) {
    return undef unless ref($node) eq 'ARRAY';

    if (@$node >= 2 && !ref($node->[0]) && ($node->[0] // '') =~ /^\?wiring:/ && ref($node->[1]) eq 'ARRAY') {
        for my $item (@{$node->[1]}) {
            next unless defined($item) && !ref($item);
            next unless $item =~ m{\A/([^/]+)/([^/]+)/\z};
            return {
                token => $item,
                source => $1,
                target => $2,
                canonical_hint => "($1 $2)",
                verbose_hint => "(connect $1 $2)",
            };
        }
    }

    for my $child (@$node) {
        next unless ref($child) eq 'ARRAY';
        if (my $issue = $class->_find_strict_composition_wiring_slash_link_issue($child)) {
            return $issue;
        }
    }

    return undef;
}

sub _strict_infix_assignment_issue_for_action ($class, $node) {
    return undef unless ref($node) eq 'ARRAY' && @$node >= 2;

    my ($target, $spec) = @$node[0, 1];
    return undef if defined($target) && !ref($target) && $class->_is_assignment_operator_token($target);
    return undef if defined($target) && !ref($target) && $target =~ /\A</;
    return undef unless $class->_is_strict_infix_assignment_target($target);
    return undef unless ref($spec) eq 'ARRAY' && @$spec >= 2;

    my $operator = $class->_unwrap_scalar_token($spec->[0]);
    return undef unless $class->_is_assignment_operator_token($operator);

    my $rhs = $class->_unwrap_scalar_token($spec->[1]);
    return {
        operator => $operator,
        target => $target,
        rhs => $rhs,
        display => $class->_render_infix_assignment_action($target, $spec),
        canonical_hint => $class->_render_canonical_assignment_pair_hint($operator, $target, $rhs),
    };
}

sub _is_strict_infix_assignment_target ($class, $target) {
    return 1 if defined($target) && !ref($target);

    my $unwrapped = $class->_unwrap_scalar_token($target);
    return 0 unless ref($unwrapped) eq 'ARRAY' && @$unwrapped;
    return 0 if ref($unwrapped->[0]);

    return $unwrapped->[0] eq 'concat' || $unwrapped->[0] eq 'cat';
}

sub _is_assignment_operator_token ($class, $token) {
    return defined($token)
        && !ref($token)
        && $token =~ /\A(?:=|<-|<-=|<=|<=-|<=\+|<[0-9]+)\z/;
}

sub _render_infix_assignment_action ($class, $target, $spec) {
    my @parts = (
        $class->_render_lispish_node($target),
        map { $class->_render_lispish_node($_) } @$spec,
    );
    return '(' . join(' ', @parts) . ')';
}

sub _render_canonical_assignment_pair_hint ($class, $operator, $target, $rhs) {
    return '('
        . $operator
        . ' ('
        . $class->_render_lispish_node($target)
        . ' '
        . $class->_render_lispish_node($rhs)
        . '))';
}

sub _render_lispish_node ($class, $node) {
    return 'undef' unless defined $node;
    return $node unless ref($node) eq 'ARRAY';
    return '()' unless @$node;

    if (@$node == 1) {
        return $class->_render_lispish_node($node->[0]);
    }

    if (@$node == 2 && defined($node->[0]) && !ref($node->[0]) && ref($node->[1]) eq 'ARRAY') {
        return '(' . join(' ', $node->[0], map { $class->_render_lispish_node($_) } @{$node->[1]}) . ')';
    }

    return '(' . join(' ', map { $class->_render_lispish_node($_) } @$node) . ')';
}

sub _direct_root_package_imports ($class, %args) {
    my $body_items = $class->_direct_root_body_items(%args);
    return [] unless $body_items;

    my $source_info = $args{source_info}
        || $class->classify_source_ast($args{raw_ast});
    my $source_label = $args{source_label} // ($source_info->{header} // 'source');

    my @package_imports;
    for my $item (@$body_items) {
        next unless ref($item) eq 'ARRAY';
        next unless defined($item->[0]) && !ref($item->[0]) && $item->[0] eq '+import';
        push @package_imports, @{ $class->_parse_direct_import_block($source_label, $item) };
    }

    return \@package_imports;
}

sub _parse_direct_import_block ($class, $source_label, $imports_ast) {
    my (undef, $imports_list) = @$imports_ast;

    confess
        "Malformed '+import' section in source '$source_label'. "
      . "The active contract supports '+import' only as a non-empty list of HDL-identifier-compatible package names. "
      . supported_boundary_hint()
        unless ref($imports_list) eq 'ARRAY' && @$imports_list;

    my @package_names;
    for my $package_name (@$imports_list) {
        my $resolved_name = $class->_unwrap_scalar_token($package_name);
        confess
            "Malformed '+import' package name '$resolved_name' in source '$source_label'. "
          . "The active contract expects each imported package name to be an HDL-identifier-compatible bare name. "
          . supported_boundary_hint()
            unless defined($resolved_name) && !ref($resolved_name) && $resolved_name =~ /\A[A-Za-z_]\w*\z/;
        push @package_names, $resolved_name;
    }

    return \@package_names;
}

sub collect_embedded_package_sources ($class, $raw_ast) {
    my %embedded_package_sources;
    return \%embedded_package_sources unless ref($raw_ast) eq 'ARRAY';

    for my $ast_node (@$raw_ast) {
        next unless ref($ast_node) eq 'ARRAY';
        next unless @$ast_node > 0;
        next if ref($ast_node->[0]);
        next unless $ast_node->[0] =~ /^\?pkg:/;
        my $package_name = $class->_decode_embedded_package_source_name($ast_node->[0]);
        next unless $package_name;
        $embedded_package_sources{$package_name} = _clone($ast_node);
    }

    return \%embedded_package_sources;
}

sub _decode_embedded_package_source_name ($class, $header) {
    return $1 if defined($header) && !ref($header) && $header =~ /\A\?pkg:([A-Za-z_]\w*)\z/;
    return undef;
}

sub _unwrap_scalar_token ($class, $value) {
    my $unwrapped = $value;
    while (ref($unwrapped) eq 'ARRAY' && @$unwrapped == 1) {
        $unwrapped = $unwrapped->[0];
    }
    return $unwrapped;
}

sub _clone ($value) {
    return undef unless defined $value;

    if (ref($value) eq 'HASH') {
        return {
            map { $_ => _clone($value->{$_}) } keys %$value
        };
    }

    if (ref($value) eq 'ARRAY') {
        return [ map { _clone($_) } @$value ];
    }

    return $value;
}

sub _import_package_symbols_into_signal_manager ($class, %args) {
    my $signal_manager = $args{signal_manager}
        or confess "SourceFrontend requires a signal_manager to import package symbols";
    my $resolved_package_imports = $args{resolved_package_imports} || {};
    my $package_imports = $args{package_imports} || [sort keys %$resolved_package_imports];

    for my $package_name (@$package_imports) {
        my $package_spec = $resolved_package_imports->{$package_name} or next;
        my $symbols = $package_spec->symbols or next;
        FSM::Package::SignalManagerProjectionSupport->project_symbols_into_signal_manager(
            signal_manager => $signal_manager,
            symbols => $symbols,
            namespace_prefix => $package_name,
            debug_level => $args{debug_level} // 0,
        );
    }
}

1;

__END__

=head1 METHODS

=head2 parse_fsm_file

Parses one C<.fsm> file with the Lispish reader and returns the raw AST.

=head2 parse_fsm_source

Parses one non-empty in-memory C<.fsm> source string through the same brace
preservation and Lispish reader path as C<parse_fsm_file>.  A caller-provided
source label is used only for bounded diagnostics.

=head2 classify_source_ast

Classifies one raw AST into the current direct-root or composition source kind
surface.

=head2 parse_composition_source

Parses one already-classified composition raw AST into the typed composition
spec consumed by the composition generation path.

=head2 create_fsm_module

Builds one semantic FSM/DT module from a direct-root raw AST through the
current C<FSMGenFull> adapter.

=head2 enforce_strict_source_boundary

Checks the current strict-mode root-family boundary for one direct-root source
before semantic module creation.

=head2 enforce_strict_generated_child_source_boundary

Checks the current strict-mode boundary for one generated composition child
source before semantic child realization continues.

=cut

perl/FSM/Support/ISFInterfacePortMetadat:
package FSM::Support::ISFInterfacePortMetadata;

use strict;
use warnings;
use Carp qw(confess);
use Exporter 'import';
use Scalar::Util qw(refaddr);
use Storable qw(dclone);
use FSM::Package::AggregatePathSupport;

our @EXPORT_OK = qw(
    capture_interface_port_metadata
    snapshot_interface_port_metadata
    interface_port_metadata_contract
);

sub interface_port_metadata_contract {
    return {
        entry_keys => [qw(name direction width)],
        optional_entry_keys => [qw(type type_kind domain fields)],
        direction_values => [qw(input output)],
        type_kind_values => [qw(bit bits record)],
        field_keys => [qw(path width lsb msb signed)],
        optional_field_keys => ['state_model'],
        field_signed_values => [0, 1],
        field_state_model_values => [qw(two_state four_state)],
        shape => 'declared inputs in source order followed by declared outputs in source order; empty for a known empty interface; null when declaration metadata is unknown',
        field_layout => 'record scalar leaves in authored traversal order; port-relative member/item paths; first leaf most significant; inclusive packed ranges',
        meaning => 'declared ISF interface metadata; no inferred signals, private handoffs, source admission or hardware behavior is established by this projection',
    };
}

# The parser will supply its validated declarations. This producer is also
# tested on resolved record types before record source admission is enabled.
# It projects explicit properties rather than exporting parser/type objects.
sub capture_interface_port_metadata {
    my ($interface, $default_domain) = @_;
    return undef unless defined $interface;
    _require(ref($interface) eq 'HASH', 'expected declared interface');
    $interface = dclone($interface);
    _require(!defined($default_domain) || _identifier($default_domain), 'invalid default domain');
    my @ports;
    for my $pair (['inputs', 'input'], ['outputs', 'output']) {
        my ($key, $direction) = @$pair;
        _require(ref($interface->{$key}) eq 'ARRAY', "expected $key array");
        for my $port (@{$interface->{$key}}) {
            _require(ref($port) eq 'HASH', 'expected declared port');
            _require(_name($port->{name}), 'invalid declared port name');
            _require(_positive_integer($port->{width}), 'invalid declared port width');
            my %entry = (name => $port->{name}, direction => $direction, width => $port->{width});
            my $domain = defined($port->{domain}) ? $port->{domain} : $default_domain;
            $entry{domain} = $domain if defined $domain;
            if (exists $port->{type}) {
                $entry{type} = $port->{type};
                my $spec = $port->{type_spec};
                _require(ref($spec) eq 'HASH', "port '$port->{name}' lacks resolved type");
                my @paths;
                _collect_scalar_paths($spec, '', \@paths, {});
                _require(_positive_integer($port->{width}) && $port->{width} == $spec->{width},
                    "port '$port->{name}' type width disagrees");
                $entry{type_kind} = $spec->{kind};
                if ($spec->{kind} eq 'record') {
                    $entry{fields} = [map { _field_metadata($spec, $_) } @paths];
                } else {
                    _require($spec->{kind} eq 'bit' || $spec->{kind} eq 'bits',
                        "port '$port->{name}' unsupported root type");
                }
            } else {
                _require(!exists($port->{type_spec}), "port '$port->{name}' has type facts without an alias");
            }
            push @ports, \%entry;
        }
    }
    return snapshot_interface_port_metadata(\@ports);
}

sub _collect_scalar_paths {
    my ($spec, $path, $paths, $active) = @_;
    _require(ref($spec) eq 'HASH', 'invalid resolved member type');
    my $address = refaddr($spec);
    _require(!$active->{$address}, 'cyclic resolved type');
    local $active->{$address} = 1;
    _require(_positive_integer($spec->{width}), 'invalid resolved type width');
    my $kind = $spec->{kind} // '';
    if ($kind eq 'bit' || $kind eq 'bits') {
        _require($kind ne 'bit' || $spec->{width} == 1, 'bit type width must be one');
        _require(!exists($spec->{signed}) || _binary($spec->{signed}), 'invalid resolved signed property');
        _require(!exists($spec->{state_model}) || _state_model($spec->{state_model}), 'invalid resolved state model');
        push @$paths, $path;
        return;
    }
    my $width = 0;
    if ($kind eq 'record') {
        my ($members, $order) = @{$spec}{qw(members member_order)};
        _require(ref($members) eq 'HASH' && ref($order) eq 'ARRAY' && scalar(@$order),
            'record requires ordered members');
        _require(keys(%$members) == @$order, 'record member inventory disagrees');
        my %seen;
        for my $name (@$order) {
            _require(_identifier($name) && !$seen{$name}++ && exists($members->{$name}),
                'invalid or duplicate record member');
            _collect_scalar_paths($members->{$name}, "$path.$name", $paths, $active);
            $width += $members->{$name}{width};
        }
    } elsif ($kind eq 'list') {
        _require(length($path), 'list-root interface metadata remains unsupported');
        my $items = $spec->{items};
        _require(ref($items) eq 'ARRAY' && scalar(@$items), 'list requires ordered items');
        for my $index (0 .. $#$items) {
            _collect_scalar_paths($items->[$index], "$path\[$index\]", $paths, $active);
            $width += $items->[$index]{width};
        }
    } else {
        _require(0, 'unsupported resolved type kind');
    }
    _require($width == $spec->{width}, 'resolved aggregate width disagrees with members');
}

sub _field_metadata {
    my ($spec, $path) = @_;
    my $resolved = FSM::Package::AggregatePathSupport->resolve_packed_range(
        root_type_spec => $spec, path_text => $path,
    );
    _require($resolved->{ok}, 'declared record field has no packed range');
    my $leaf = $resolved->{type_spec};
    (my $relative_path = $path) =~ s/^\.//;
    my %field = (
        path => $relative_path, width => 0 + $resolved->{width},
        lsb => 0 + $resolved->{low}, msb => 0 + $resolved->{high},
        signed => ($leaf->{signed} // 0) ? 1 : 0,
    );
    $field{state_model} = $leaf->{state_model} if exists $leaf->{state_model};
    return \%field;
}

# Unknown provenance stays unknown. Known metadata is checked and rebuilt so
# each consumer receives a closed detached value, including nested fields.
sub snapshot_interface_port_metadata {
    my ($value) = @_;
    return undef unless defined $value;
    _require(ref($value) eq 'ARRAY', 'expected port metadata array');
    $value = dclone($value);
    my (@ports, %seen);
    my $outputs_started = 0;
    for my $port (@$value) {
        _require(ref($port) eq 'HASH', 'expected port metadata entry');
        _closed_keys($port, [qw(name direction width)], [qw(type type_kind domain fields)]);
        _require(_name($port->{name}) && !$seen{$port->{name}}++, 'invalid or duplicate port name');
        _require(defined($port->{direction}) && !ref($port->{direction})
            && scalar($port->{direction} =~ /\A(?:input|output)\z/), 'invalid direction');
        _require($port->{direction} ne 'input' || !$outputs_started, 'inputs must precede outputs');
        $outputs_started = 1 if $port->{direction} eq 'output';
        _require(_positive_integer($port->{width}), 'invalid port width');
        my %copy = (name => $port->{name}, direction => $port->{direction}, width => 0 + $port->{width});
        if (exists $port->{domain}) {
            _require(_identifier($port->{domain}), 'invalid domain');
            $copy{domain} = $port->{domain};
        }
        if (exists $port->{type}) {
            _require(defined($port->{type}) && !ref($port->{type})
                && scalar($port->{type} =~ /\A[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)?\z/), 'invalid type alias');
            _require(defined($port->{type_kind}) && !ref($port->{type_kind})
                && scalar($port->{type_kind} =~ /\A(?:bit|bits|record)\z/), 'invalid resolved type kind');
            _require($port->{type_kind} ne 'bit' || $port->{width} == 1, 'bit port width must be one');
            @copy{qw(type type_kind)} = @{$port}{qw(type type_kind)};
        } else {
            _require(!exists($port->{type_kind}) && !exists($port->{fields}), 'type facts require an alias');
        }
        if (($port->{type_kind} // '') eq 'record') {
            $copy{fields} = _snapshot_fields($port->{fields}, $port->{width});
        } else {
            _require(!exists($port->{fields}), 'scalar port cannot have record fields');
        }
        push @ports, \%copy;
    }
    return \@ports;
}

sub _snapshot_fields {
    my ($fields, $width) = @_;
    _require(ref($fields) eq 'ARRAY' && scalar(@$fields), 'record requires scalar field metadata');
    my (@copy, %seen);
    my $next_high = $width - 1;
    for my $field (@$fields) {
        _require(ref($field) eq 'HASH', 'expected scalar field entry');
        _closed_keys($field, [qw(path width lsb msb signed)], ['state_model']);
        my $path = $field->{path};
        _require(defined($path) && !ref($path)
            && $path =~ /\A[A-Za-z_]\w*(?:(?:\.[A-Za-z_]\w*)|(?:\[[0-9]+\]))*\z/
            && !$seen{$path}++, 'invalid or duplicate field path');
        _require(_positive_integer($field->{width}) && _nonnegative_integer($field->{lsb})
            && _nonnegative_integer($field->{msb}) && $field->{msb} == $next_high
            && $field->{msb} - $field->{lsb} + 1 == $field->{width}, 'field ranges do not form ordered packed layout');
        _require(_binary($field->{signed}), 'invalid scalar field signed property');
        my %entry = (path => $path, map { $_ => 0 + $field->{$_} } qw(width lsb msb signed));
        if (exists $field->{state_model}) {
            _require(_state_model($field->{state_model}), 'invalid scalar field state model');
            $entry{state_model} = $field->{state_model};
        }
        push @copy, \%entry;
        $next_high = $field->{lsb} - 1;
    }
    _require($next_high == -1, 'record field layout does not cover the port');
    return \@copy;
}

sub _closed_keys {
    my ($value, $required, $optional) = @_;
    my %allowed = map { $_ => 1 } (@$required, @$optional);
    _require(!grep(!exists($value->{$_}), @$required), 'missing metadata key');
    _require(!grep(!$allowed{$_}, keys %$value), 'unknown metadata key');
}

# Predicate results must be single values in argument-list context: a failed
# regex otherwise returns an empty list and shifts the diagnostic into slot 0.
sub _name { (defined($_[0]) && !ref($_[0]) && length($_[0])) ? 1 : 0 }
sub _identifier { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A[A-Za-z_]\w*\z/) ? 1 : 0 }
sub _positive_integer { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A[1-9][0-9]*\z/) ? 1 : 0 }
sub _nonnegative_integer { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A(?:0|[1-9][0-9]*)\z/) ? 1 : 0 }
sub _binary { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A[01]\z/) ? 1 : 0 }
sub _state_model { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A(?:two_state|four_state)\z/) ? 1 : 0 }
sub _require {
    confess "Invalid ISF interface port metadata: validation requires a predicate and message\n"
        unless @_ == 2;
    confess "Invalid ISF interface port metadata: $_[1]\n" unless $_[0];
}

1;

perl/FSM/Support/ISFRecordPortValues.pm:
package FSM::Support::ISFRecordPortValues;

use strict;
use warnings;
use Carp qw(confess);
use Exporter 'import';
use Storable qw(dclone);
use FSM::Package::AggregatePathSupport;
use FSM::Composition::InterfacePortBuilder;
use FSM::Support::ISFInterfacePortMetadata qw(capture_interface_port_metadata);

our @EXPORT_OK = qw(record_value_scope record_value_reference validate_record_port_copy);

# Preparation only: callers supply resolved declaration facts, not source text.
# Local bindings mask outer declarations even when their type is unresolved.
sub record_value_scope {
    my %args = @_;
    _keys(\%args, [qw(outer local)], [], 'scope');
    my %scope;
    for my $layer (qw(outer local)) {
        my $roots = $args{$layer};
        _require(ref($roots) eq 'HASH', "$layer roots must be a map");
        for my $name (sort keys %$roots) {
            _require(_identifier($name), 'invalid declaration root');
            my $root = $roots->{$name};
            _keys($root, [qw(role type_spec)], [], "root '$name'");
            # Numeric validation can change Perl scalar flags and therefore
            # JSON kinds even without an assignment. Detach before any reads.
            $root = dclone($root);
            _require(_role($root->{role}), "root '$name' has invalid role");
            my $spec = $root->{type_spec};
            _validate_type($spec, "root '$name'") if defined $spec;
            $scope{$name} = {
                role => $root->{role},
                type_spec => FSM::Package::AggregatePathSupport->clone_structured_value($spec),
            };
        }
    }
    return \%scope;
}

# An unrelated token or unresolved binding belongs to the caller's existing
# validator. In particular, it must not fall through to a shadowed outer root.
sub record_value_reference {
    my %args = @_;
    _keys(\%args, [qw(scope token access context)], ['allow_whole'], 'reference');
    my ($scope, $token, $access, $context) = @args{qw(scope token access context)};
    _require(ref($scope) eq 'HASH', 'reference scope must be a map');
    _require(_text($context), 'reference requires context');
    _require(defined($access) && !ref($access) && ($access eq 'read' || $access eq 'write'),
        "$context has invalid access");
    my $allow_whole = $args{allow_whole} // 0;
    _require(_binary($allow_whole), "$context has invalid whole-value permission");
    return undef unless defined($token) && !ref($token)
        && $token =~ /\A([A-Za-z_]\w*)(.*)\z/s;
    my ($name, $path) = ($1, $2);
    return undef unless exists $scope->{$name};
    my $root = $scope->{$name};
    _keys($root, [qw(role type_spec)], [], "$context root '$name'");
    $root = dclone($root);
    _require(_role($root->{role}), "$context root '$name' has invalid role");
    _require($access ne 'write' || $root->{role} ne 'input',
        "$context cannot write declared input '$token'");
    return undef unless defined $root->{type_spec};
    _validate_type($root->{type_spec}, "$context root '$name'");
    my %result = (root => $name, role => $root->{role}, path_text => $path);
    if (!length $path) {
        my $spec = $root->{type_spec};
        _require($allow_whole || !_aggregate($spec),
            "$context requires a scalar value; '$token' is a whole $spec->{kind}");
        $result{type_spec} = FSM::Package::AggregatePathSupport->clone_structured_value($spec);
        $result{width} = 0 + $spec->{width};
        return \%result;
    }
    # Preserve scalar formal/local slices when they mask an outer record.
    # Core traversal accepts scalar indexing after a member; a one-member
    # wrapper supplies that anchor without changing the packed bit offsets.
    my ($path_root, $path_text) = ($root->{type_spec}, $path);
    if (!_aggregate($path_root)) {
        $path_root = _wrapper($path_root);
        $path_text = '.value' . $path;
    }
    my $resolved = FSM::Package::AggregatePathSupport->resolve_packed_range(
        root_type_spec => $path_root, path_text => $path_text,
    );
    _require($resolved->{ok}, "$context has invalid declared path '$token': "
        . ($resolved->{code} // 'unresolved'));
    _require(!_aggregate($resolved->{type_spec}),
        "$context requires a scalar leaf; '$token' resolves to $resolved->{type_spec}{kind}");
    @result{qw(type_spec width low high)} = @{$resolved}{qw(type_spec width low high)};
    return \%result;
}

# Return false for the caller's established scalar/storage-only assignment
# contract. Only a whole record port introduces the stricter copy obligation.
sub validate_record_port_copy {
    my %args = @_;
    _keys(\%args, [qw(source target context)], [], 'copy');
    my ($source, $target, $context) = @args{qw(source target context)};
    _require(_text($context), 'copy requires context');
    $source = dclone($source) if ref($source) eq 'HASH';
    $target = dclone($target) if ref($target) eq 'HASH';
    _validate_reference($_, $context) for grep { defined $_ } ($source, $target);
    return 0 unless _record_port($source) || _record_port($target);
    _require(_whole_record($source) && _whole_record($target),
        "$context whole record port copy requires declared record roots");
    _require($target->{role} ne 'input',
        "$context cannot write declared input '$target->{root}'");
    _require(!FSM::Composition::InterfacePortBuilder->declared_type_conflicts(
        $source->{type_spec}, $target->{type_spec}),
        "$context record port copy from '$source->{root}' to '$target->{root}' requires the same resolved record type");
    return 1;
}

sub _validate_reference {
    my ($value, $context) = @_;
    _keys($value, [qw(root role path_text type_spec width)], [qw(low high)], "$context value");
    _require(_identifier($value->{root}) && _role($value->{role})
        && defined($value->{path_text}) && !ref($value->{path_text}), "$context has invalid declaration facts");
    _validate_type($value->{type_spec}, $context);
    _require(_positive($value->{width}) && $value->{width} == $value->{type_spec}{width},
        "$context value width disagrees with resolved type");
    my $leaf = length($value->{path_text}) ? 1 : 0;
    _require($leaf == (exists($value->{low}) && exists($value->{high}) ? 1 : 0),
        "$context value range disagrees with path");
    _require($leaf || (!exists($value->{low}) && !exists($value->{high})),
        "$context whole value cannot have a range");
    if ($leaf) {
        _require(!_aggregate($value->{type_spec}) && _nonnegative($value->{low})
            && _nonnegative($value->{high}) && $value->{high} - $value->{low} + 1 == $value->{width},
            "$context has invalid scalar range");
    }
}

sub _validate_type {
    my ($spec, $context) = @_;
    _require(ref($spec) eq 'HASH', "$context lacks a resolved type");
    # The qualified declaration producer owns recursive layout, cycle, width,
    # member inventory and scalar-property validation. A wrapper lets the same
    # check consume existing list storage without admitting list-root ports.
    my $checked = $spec;
    if (($spec->{kind} // '') eq 'list') {
        $checked = _wrapper($spec);
    }
    my $ok = eval {
        capture_interface_port_metadata({inputs => [{name => 'value', type => 'resolved_value',
            width => $checked->{width}, type_spec => $checked}], outputs => []});
        1;
    };
    my $error = $@;
    _require($ok, "$context has invalid resolved type: $error");
    _closed_type($spec, $context);
}

sub _closed_type {
    my ($spec, $context) = @_;
    my $kind = $spec->{kind};
    my @extra = $kind eq 'record' ? qw(members member_order) : $kind eq 'list' ? ('items') : ();
    _keys($spec, [qw(kind width signed), @extra],
        _aggregate($spec) ? [] : ['state_model'], "$context resolved type");
    _require(_binary($spec->{signed}), "$context has invalid resolved signed fact");
    if (_aggregate($spec)) {
        _require($spec->{signed} == 0, "$context aggregate has a scalar signed overlay");
        my @children = $kind eq 'record'
            ? map { $spec->{members}{$_} } @{$spec->{member_order}}
            : @{$spec->{items}};
        _closed_type($_, $context) for @children;
    }
}

sub _record_port {
    my ($value) = @_;
    return 0 unless _whole_record($value);
    return ($value->{role} eq 'input' || $value->{role} eq 'output') ? 1 : 0;
}
sub _wrapper {
    my ($spec) = @_;
    return {kind => 'record', width => $spec->{width}, signed => 0,
        member_order => ['value'], members => {value => $spec}};
}
sub _whole_record {
    my ($value) = @_;
    return (ref($value) eq 'HASH' && !length($value->{path_text})
        && $value->{type_spec}{kind} eq 'record') ? 1 : 0;
}
sub _aggregate { ($_[0]{kind} eq 'record' || $_[0]{kind} eq 'list') ? 1 : 0 }
sub _identifier { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A[A-Za-z_]\w*\z/) ? 1 : 0 }
sub _role { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A(?:input|output|storage|local)\z/) ? 1 : 0 }
sub _text { (defined($_[0]) && !ref($_[0]) && length($_[0])) ? 1 : 0 }
sub _positive { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A[1-9][0-9]*\z/) ? 1 : 0 }
sub _nonnegative { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A(?:0|[1-9][0-9]*)\z/) ? 1 : 0 }
sub _binary { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A[01]\z/) ? 1 : 0 }
sub _keys {
    my ($value, $required, $optional, $context) = @_;
    _require(ref($value) eq 'HASH', "$context must be a map");
    my %allowed = map { $_ => 1 } (@$required, @$optional);
    _require(!grep(!exists($value->{$_}), @$required), "$context lacks required facts");
    _require(!grep(!$allowed{$_}, keys %$value), "$context has unknown facts");
}
sub _require {
    confess "Invalid ISF record value: validation requires a predicate and message\n" unless @_ == 2;
    confess "Invalid ISF record value: $_[1]\n" unless $_[0];
}

1;

#!/usr/bin/env perl
use strict;
use warnings;
use Test::More;
use JSON::PP;
use Scalar::Util qw(refaddr blessed reftype);
use lib 'perl', 't/lib';
use FSM::Test::DiagnosticCause qw(diagnostic_cause_matches);
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF::LoweringIR;
use FSM::Scheduler::ISF::PreparedFormalReservations;
use FSM::Scheduler::ISF::FormalReservationInventory;
use FSM::Scheduler::ISF::FormalIdentityPlan;

sub source_value_copy {
    my ($value, $copies) = @_;
    return $value unless ref($value);
    die 'unexpected source reference' if blessed($value)
        || (ref($value) ne 'HASH' && ref($value) ne 'ARRAY');
    $copies ||= {};
    my $address = refaddr($value);
    return $copies->{$address} if exists $copies->{$address};
    my $copy = ref($value) eq 'HASH' ? {} : [];
    $copies->{$address} = $copy;
    if (ref($value) eq 'HASH') {
        $copy->{$_} = source_value_copy($value->{$_}, $copies) for keys %$value;
    } else {
        push @$copy, source_value_copy($_, $copies) for @$value;
    }
    return $copy;
}

sub snapshot_graph {
    my ($value, $seen, $path) = @_;
    return $value unless ref($value);
    $seen ||= {}; $path //= '';
    my $address = refaddr($value);
    return ['reference', $seen->{$address}] if exists $seen->{$address};
    $seen->{$address} = $path;
    if (blessed($value)) {
        # The cause controls use this empty native HASH. Other unsupported
        # referents have no declared snapshot contract and fail closed.
        die 'unexpected native snapshot reference' unless ref($value) eq 'PreparedCauseSentinel'
            && reftype($value) eq 'HASH' && !keys %$value;
        return ['empty_native_hash', ref($value), $address];
    }
    if (ref($value) eq 'HASH') {
        my %copy;
        for my $key (sort keys %$value) {
            my $escaped = $key; $escaped =~ s/~/~0/g; $escaped =~ s{/}{~1}g;
            $copy{$key} = snapshot_graph($value->{$key}, $seen, "$path/$escaped");
        }
        return ['hash', \%copy];
    }
    return ['array', [map {snapshot_graph($value->[$_], $seen, "$path/$_")} 0..$#$value]]
        if ref($value) eq 'ARRAY';
    die 'unexpected snapshot reference';
}

sub input_snapshot {JSON::PP->new->canonical->encode(snapshot_graph($_[0]))}

my $lowerer = FSM::Scheduler::ISF::LoweringIR->new;
sub prepare {
    my ($source, $path) = @_;
    my $actor = FSM::Adapter::ISF->new->parse_source($source, $path // 'prepared_reservations.isf');
    no warnings 'redefine';
    local *FSM::Scheduler::ISF::LoweringIR::build_module = sub {die "unexpected executable parent merge\n"};
    return $lowerer->prepare_formal_source($actor);
}
sub collect {FSM::Scheduler::ISF::PreparedFormalReservations->collect($_[0])}
sub rejected {
    my ($prepared, $expected_cause, $label) = @_;
    my $before = input_snapshot($prepared);
    my $ok = eval {collect($prepared); 1};
    my $error = $@;
    ok(!$ok, "$label rejected");
    ok(diagnostic_cause_matches($error, $expected_cause), "$label has a focused diagnostic")
        or diag($error);
    is(input_snapshot($prepared), $before, "$label validation preserves input kinds and references");
}
my $simple = prepare(<<'ISF');
(actor checked_reservations (clock clk) (reset rst_n)
 (interface (input start) (input data (width 4)) (output result (width 4)) (output done))
 (storage (var value_reg (width 8)))
 (drive (isf_port_main payload) (result payload))
 (transaction main (ports (input payload (width 4)) (input value_reg (width 4)))
  (on start) (set payload data) (drive isf_port_main payload) (wait value_reg) (complete done)))
ISF

subtest 'checked inputs retain complete conservative product provenance without parent execution' => sub {
    my $before = input_snapshot($simple);
    my $result = collect($simple);
    is($result->{model}, 'isf_prepared_formal_reservations_v1', 'explicit checked model');
    my $partial = FSM::Scheduler::ISF::FormalReservationInventory->collect({
        map {$_ => $simple->{$_}} grep {$_ eq 'actor' || /products$/ || $_ eq 'domain_partition'} keys %$simple});
    is_deeply($result->{reserved_names}, $partial->{reserved_names}, 'all previously qualified products are retained');
    is_deeply($result->{origins}, $partial->{origins}, 'structural provenance is preserved');
    is_deeply([map {$_->{identity}} @{$result->{scopes}}], [['actor_module', 'checked_reservations', 'parent']],
        'ordinary actor has one explicit parent scope');
    my $plan = FSM::Scheduler::ISF::FormalIdentityPlan->build($simple->{actor},
        generated_children => $simple->{generated_children}, reserved_names => $result->{reserved_names});
    isnt(lc($plan->{formals}{main}{payload}{physical_name}), 'isf_port_main_payload', 'actual drive helper candidate remains reserved');
    my %permuted = map {$_ => $simple->{$_}} reverse sort keys %$simple;
    is_deeply(collect(\%permuted), $result, 'input hash insertion order cannot affect output');
    $result->{scopes}[0]{reserved_names}{mutated} = 1;
    ok(!$result->{reserved_names}{mutated}, 'scope and union snapshots are independent');
    is(input_snapshot($simple), $before, 'collection preserves source preparation kinds and references');
};

subtest 'every top-level category is required even when empty' => sub {
    for my $field (sort keys %$simple) {
        my $bad = source_value_copy($simple); delete $bad->{$field};
        rejected($bad, "Prepared formal reservations have incomplete preparation (missing: $field; unexpected: )", "missing $field");
        $bad = source_value_copy($simple); $bad->{$field} = 'wrong shape';
        rejected($bad, "Prepared formal reservations have malformed preparation field '$field'", "malformed $field");
    }
    my $bad = source_value_copy($simple); $bad->{new_producer_products} = {};
    rejected($bad, "Prepared formal reservations have incomplete preparation (missing: ; unexpected: new_producer_products)", 'unknown producer must be classified');
    $bad = source_value_copy($simple); delete $bad->{transaction_products}{main};
    rejected($bad, "Prepared formal reservations have incomplete transaction products (missing: main; unexpected: )", 'missing live transaction producer');
    $bad = source_value_copy($simple); $bad->{transactions}{ghost} = {};
    rejected($bad, "Prepared formal reservations have incomplete transaction contexts (missing: ; unexpected: ghost)", 'unknown context');
    $bad = source_value_copy($simple); $bad->{generated_children}{ghost} = 1;
    rejected($bad, "Prepared formal reservations have unknown generated_children membership", 'unknown generated child');
    $bad = source_value_copy($simple); $bad->{domain_partition} = {kind => 'future_partition'};
    rejected($bad, "Prepared formal reservations have an unknown domain partition kind", 'unknown partition');
    $bad = source_value_copy($simple); $bad->{reusable_child_products}{unclassified} = {};
    rejected($bad, "Prepared formal reservations have incomplete reusable children (missing: ; unexpected: unclassified)", 'unclassified reusable product');
    $bad = source_value_copy($simple); $bad->{actor_context}{cycle} = $bad;
    my $before = input_snapshot($bad);
    my $ok = eval {collect($bad); 1};
    my $error = $@;
